/* 平成14年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h14.committeeSessions.push(...[{"id":"h14-20020121-6","meetingId":"h14-cm01","date":"2002年1月21日","dateIso":"2002-01-21","committee":"区民委員会","time":"午後１時０２分～午後３時３５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"狂牛病関連の紹介状についてお伺いしたいんですけれども、５４件発行件数があるということですけれども、区として、焼き肉屋とか肉屋、狂牛病に関連する業種に対して、郵送物を送ってくださいまして、その送った件数で５４件というのは何％ぐらいになるんか尋ねました。","respondent":"市川産業振興課長","answer":"焼き肉店が約７０、小売、このうち協同組合を通してご案内を差し上げたのが約１２０あります。４分の1程度の方にご利用いただいたというか、ちょっと数字の考え方がずれるところがありますが、大体そんな状況です。","id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"区に相談して紹介状をいただくという形ですから、行った方は、もうお金は借りられるんだろうという感覚になってしまうと思うんです。借りられなかった２５％の方が、その後、借りられなかった方というのはどうやっていったのかというのは把握はされているんか尋ねました。","respondent":"市川産業振興課長","answer":"１００％の問題ですけれども、このことは、あっ斡という事業の性格上なかなか難しいというふうに考えてあります。できないという、今ほど委員がおっしゃったような決算書等を判断の材料にして行っている現在の方法が一番適切な方法だというふうに考えてあります。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"だめというのが出ると思うんですけれども、私の感覚は、信用保証協会もすぐＯＫを出す優良企業も多く借りられていると思うんです。本当に切羽詰まって困っている企業に対しての対策、これ以外の対策というのは何かあるんか尋ねました。","respondent":"市川産業振興課長","answer":"実際困難な者が利用できないというのは矛盾ではないかというような趣旨のご質問ですけれども、ここで言う資金というのは、あくまで事業資金です。","id":"exchange-003"},{"speaker":"原委員","kind":"質問","question":"その辺のところの考え方をどういうふうに持っているのかというのが１点。５年を経て、ほかの考え方をそこに注入できないかなというように思っているんですけれども、その辺はどういうふうに考えているか尋ねました。","respondent":"市川産業振興課長","answer":"相談員はこの２カ月間は通常より人数を増やして対応をしているところでございまして、私どもも、次のステップに向けていただきたい。こういったことで対応をしてきているところです。","id":"exchange-004"},{"speaker":"原委員","kind":"質問・要望","question":"あるいは今回２５％が信用保証料を得られなかった、そのところをもう少し研究をし、考え方を工夫してほしいと求めました。そのお考えがあれば、お聞きしたいと思います。","respondent":"市川産業振興課長","answer":"考え方、これまでの融資制度というのは、いろいろな意味で手を入れる時期に差しかかっていると思います。融資制度に付随する、こういったことに少し手を入れて、有効な融資あっ斡制度ということの運営を図ってまいりたいと考えております。","id":"exchange-005"},{"speaker":"本田委員","kind":"質問","question":"紹介では飲食業関係が３１件ということで、一番多いんですが、実際の数は飲食業で言えば７０件ですか。国の責任が問われるというようなことも起きているわけですけれども、その辺は、この融資の中でどんなふうに掌握しているんか尋ねました。","respondent":"市川産業振興課長","answer":"特にこの１カ月ぐらい、私は商店街の関係の皆さん方といろいろお話を聞く中で出た幾つか、今委員からご質問の答えとして紹介をします。一つの取り組みとして、ワールドカップにちなんだいろいろなイベントを考える、こういったことも聞いてあります。","id":"exchange-006"},{"speaker":"本田委員","kind":"意見","question":"ワールドカップのイベントというようなお話もございましたけれども、お金を貸すというだけではなくて、そこからどう立ち直っていくか。融資とは直接違うんですけれども、産業振興という面から見て、どんなふうにご検討されていますかとの意見を述べました。","respondent":"市川産業振興課長","answer":"あるいは商店街の関係とかで、現場の経営者の方、事業者の方からいろいろな話を聞ける立場にあります。区として何かそういった再建に向けての支援策があるものならば、私どもが中継地点となって、私どものほうからそういう話を検討する。","id":"exchange-007"},{"speaker":"本田委員","kind":"質問・要望","question":"消費者にとって安全なものですよ、大丈夫ですよというようなアプローチの仕方を研究して、これは一品川区だけではないと思うんです。国、東京都の連携が必要だと思いますけれども、そういう形を早くつくって、解決を図るように努力してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"もう１点は、融資の問題と直接関係ないのかもしれないんですけれども、先ほどプロパー融資から区の紹介を得て、切り替えが進んでいるんだと。従業員２０人以下ぐらいの制度、あるいは品川区でつかんでいる何かがありましたら、その辺も併せてお伺いしたいと思います。","respondent":"市川産業振興課長","answer":"さっき私が説明を一部省略したもので、平成１２年度の紹介状の発行件数４５３、融資の実行件数２６３となっています。あまり世間の風評云々ということよりは、実質的なところで地元の中小金融機関との協調関係というものを進めていくべきだというふうに考えております。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問・要望","question":"そのときに、区としてそういう経営者に対して、これは難しいんでしょうけれども、どういう援助ができるのか。具体的に区として経営者に対して援助ができるような体制というのが考えられるとすると何があるのか、お聞かせほしいと求めました。","respondent":"市川産業振興課長","answer":"信用保証協会に呼びかけとか、特に破綻をした金融機関の制度融資をご利用なさっていたお客様には個別にご案内をして対応をしてきてあります。これが今後どうなるかは、今までの経験を踏まえながら、そういうようなことについては対応策は考えてまいりたいと考えています。","id":"exchange-010"},{"speaker":"金高委員","kind":"質問・要望","question":"どうしてですかと言ったら、信用保証協会の「だめです」という一言でもってだめになった。どういう相談をして上げて、どういう経営改善をするような立場というか、お聞きしたいと思います。","respondent":"市川産業振興課長","answer":"これは実態上ちょっと難しい状況もあります。この辺は今後の研究課題にさせていただければと思います。","id":"exchange-011"},{"speaker":"金高委員","kind":"質問・要望","question":"最終的には信用保証協会が保証するということですから、どうしても制度融資をお願いしたいということで、銀行のほうでもいいでしょうと。もう一つの壁の資料消去化というのもあるわけですから、先々に明るい光があるということも含めての「いいでしょう」ということでの紹介状を出す。","respondent":"市川産業振興課長","answer":"だめだったのかというのは、これは基本的には信用保証協会のほうも、本人以外はなぜだめなのかというのを説明しないことになっています。","id":"exchange-012"},{"speaker":"石田副委員長","kind":"質問","question":"行政として、それでなるならば、そちらでやっていることが１００％近くそちらの仕事だと考えるのであれば、紹介状はどんどん出す。ある程度苦しいところであれば、この目的に一番合ってくると思うんだけれども、そこら辺の点はどうお考えか尋ねました。","respondent":"市川産業振興課長","answer":"そうじゃなくて、先ほど来るる説明しておりますように、品川区の制度融資の一つの特徴だというふうに思ってあります。出す、出さないを決めているという実情はございませんので、その点についてご理解をいただければと思います。","id":"exchange-013"},{"speaker":"石田副委員長","kind":"質問・要望","question":"１年だって、始めた人は始めたばかりとか、いろいろ条件があるじゃないですか。だめということをされてしまうわけですから、私は５０％になっても構わないと思うけれども、違うところでみんな相談をしていると思うんです。","respondent":"市川産業振興課長","answer":"そういう意味からいたしますと、委員がご指摘されている趣旨というのは、現状でもかなり満たされていると思います。これは私ども足元を振り返ってみなくちゃいけないと思いますので、そういう点で、ご指摘の趣旨を受け止めさせていただければと思います。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"１点だけお伺いしたいんですけれども、今５,４３０万人から、２０２０年には７,９００万人という予想が立てられているんですが、今課長から「需要が」というお話が出たんですが、それ以外にこういうふうに７,９００万人になるだろうという予想の根拠を教えてほしいと求めました。","respondent":"金井環境課長","answer":"私どもがこの資料をいただいたのは平成１３年１２月の初めでございまして、そういった細かい根拠は国に聞かないとわからないと思うんです。そういうレベルだけでございまして、そういった具体的な根拠といいますと、国のほうに直接聞きませんとなかなか難しいかなと思います。","id":"exchange-015"},{"speaker":"原委員","kind":"質問","question":"ご説明いただいた４番のところですが、多摩川の河川が新設滑走路のところの手前に出てくるんですか。右の端の隠れた部分に多摩川が出てくるんか尋ねました。","respondent":"金井環境課長","answer":"海のほうに位置する部分のこの辺に、河口部は現在多摩川です。この線が。","id":"exchange-016"},{"speaker":"原委員","kind":"質問","question":"そうすると、ここにこうなっているのが多摩川が出てきたところ、河口になるわけか尋ねました。","respondent":"金井環境課長","answer":"これが多摩川です。","id":"exchange-017"},{"speaker":"原委員","kind":"質問","question":"そうすると、支障が起きないところは１,０００ｍあれば支障はないよという話か尋ねました。","respondent":"金井環境課長","answer":"一般的に大体埋め立てをする予定ですけれども、立体的なことだと思うんですが、影響を与えないようにしていきたい。そういうことです。","id":"exchange-018"},{"speaker":"本田委員","kind":"質問・要望","question":"事業費も１兆円ぐらいの動きがあるというふうに新聞にも書かれておりますけれども、環境問題を含めまして、これと係わる問題は何があるんでしょうか。もし分かっていればお聞かせほしいと求めました。","respondent":"金井環境課長","answer":"もう１点は、南大井、あるいは八潮の一部の地域にテレビ受信料の一部を助成しているというのを聞いております。それについて、今後どうするのか、説明会もやりたいとかというような話は若干間接的に聞いております。","id":"exchange-019"},{"speaker":"本田委員","kind":"確認","question":"品川区上空を飛んでいくということですから、私は、総合的に環境問題ではもう一回物を言う必要があるんじゃないかなというふうに思うんです。八潮団地はこの対象地域に入っていないと思うんですが、いかがか尋ねました。","respondent":"金井環境課長","answer":"東京都も都として首都圏の発展も含めていろいろ検討をされてきていると思いますので、建設の計画の中には難しいかなと。それは廃止の方向で検討をしていきたいということです。","id":"exchange-020"},{"speaker":"本田委員","kind":"質問・要望","question":"将来、１０年、２０年などというのはすぐですからね。これは所管外ですから、強く言っていくべきだというふうに思いますので、要望しておきたいと思います。","respondent":"金井環境課長","answer":"今後の経緯を含めまして、そういう場面になれば、当然ながら区として区の代表者からもきちっとお話をするということでやっていきたいと思います。今までもそういうつもりでやっておりますので、今後ともそんな気持ちでやっていきたいというふうに思います。","id":"exchange-021"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、情報としてぜひ細かいところを含めて区で得られるような努力をして、区議会に報告をしていただければというふうに思うんです。これは要望しておきます。","respondent":"金井環境課長","answer":"委員会が二つにまたがって、同じような資料を出すというのはあまりやっていないわけですが、こういうのは特別としてご報告しています。できる限りのことは努力をしてまいりますが、委員のお話がございましたので、お話は担当のほうにさせていただきたいと思います。","id":"exchange-022"},{"speaker":"南委員長","kind":"確認","question":"私からも改めて伺いたいんですが、現在５,４３０万人の利用数だということと、２０２０年には８,０００万人を超えるだろうというご報告でした。これは２４時間の空港の開設と、そういう認識でいいかどうか、改めて確認したいと思います。","respondent":"金井環境課長","answer":"さらに、国際化に向けては、Ｂ滑走路ができることによって２０１５年以降若干の枠ができそうだと。それについては国際線も検討をしていきたいというような話が、先般の三者協議会の中では、資料としても出されておりました。","id":"exchange-023"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田副委員長","kind":"質問","question":"２万５,０００部と今おっしゃったけれども、これはどこから出てくる数字なんか尋ねました。","respondent":"宮地区民課長","answer":"三紙ということで、毎年規模的には２万５,０００部という形で折り込んでいるんですけれども、品川区、大田区を中心とした区域ということで行っております。","id":"exchange-024"},{"speaker":"石田副委員長","kind":"質問","question":"言い方が悪かったかもしれないんですけれども、もし三紙でも入れるとしたら、２万５,０００部では地域が限定されると思うんです。品川区全体はもちろん入らないし、そこら辺のところは、こういう決め方というのは、単純に近隣を入れるということで考えていらっしゃるんか尋ねました。","respondent":"宮地区民課長","answer":"具体的にどこの地域というのは今データを持っていないんですけれども、全体にはまたがらないということですから、きゅりあんを中心とした区域を半径をとりまして、やっているです。","id":"exchange-025"},{"speaker":"本田委員","kind":"質問","question":"現在１号被保険者というのは、品川区で何人いるんでしょうか。ご検討をされているのか。","respondent":"小野年金制度担当課長","answer":"平成１４年度以降、懸念されることと言いますのは、国民年金の受給権というものが保険料を納めるということによって発生をするということがあります。","id":"exchange-026"},{"speaker":"本田委員","kind":"質問","question":"強制適用で６万３,４１３人で、実際に納めているのは７４％ということですか。だから２６％は納めていない方ということか尋ねました。","respondent":"小野年金制度担当課長","answer":"強制検認率のほうが７4.３％ということですので、保険料を納めなければいけない方のうちの７４％が納めている。２６％の方が納めていないという形になります。","id":"exchange-027"},{"speaker":"本田委員","kind":"質問","question":"本来国の事業ですから、国がちゃんと責任を持ってやってくださいと言えばそれだけのことですけれども、年金離れが今きているでしょう。その辺はどのように考えているんか尋ねました。","respondent":"小野年金制度担当課長","answer":"あるいはコンビニエンスストアでも将来には２４時間納めることができるというような方法も考えていくということで、私どものほうといたしましても。あるいは窓口での対応についてもできるだけ年金の信頼が回復するようにと考えております。","id":"exchange-028"},{"speaker":"本田委員","kind":"質問・要望","question":"６５歳になって十分生活ができるというような年金制度ですよというふうに、国民に、私は心配をしているわけです。２５％ぐらいの未納で済むのかなという心配をしているということで、改善するように、要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"原委員","kind":"質問","question":"議事進行についてですが、この産業マスタープランを、今取り上げてどうのこうのするということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"本田委員","kind":"質問・要望","question":"その他のところにも書いてなく、議題にも書いてなくて、突然今のお話を聞きましたので、そういう議事進行はいかがかなというふうに思うんです。だから、最初から、報告事項なり、日程に入れていただいて、そして議論するようにしていただきたいというふうに思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"原委員","kind":"質問","question":"それについてどうのこうのということは、これは一つの指針が出てきたということですから、どうしようということもできないと思うんです。その辺は、もしやるのであるならばもう少し考えるべきかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"原委員","kind":"質問","question":"ということは、マスタープランというのはすでにちゃんとでき上がってきたものを、中味についてまた論議しようということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"原委員","kind":"質問","question":"その線に沿って、産業を進めますよ、振興していきますよというものが出てきているわけです。それをどういう形で論議しようということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"原委員","kind":"質問","question":"ですから、そこの中のどういうものをどういう形でやるかということを、この中のこれがどうのこうのという話でないと思うんです。ただし、もう少し正副委員長で話し合っていただいた中で論議を深めていくという形にしてほしいと求めました。","respondent":"南委員長","answer":"議題として提供する際には、事前に打ち合わせをし、きちんと整理をして提供していきたいと考えています。この件の進め方について、ほかにご意見はありますか。","id":"exchange-035"},{"speaker":"菊地委員","kind":"質問・要望","question":"例えばですけれども、次の区民委員会で論議を進めていくという方向があるのであれば、それで結構です。ぜひやってほしいし、正副委員長のほうでつくっていただけるということであれば、ぜひそういう形をとってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"本田委員","kind":"質問・要望","question":"議事進行の仕方が初めてではないですかということを申し上げているんです。そこのところをご確認をほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"石田副委員長","kind":"質問・要望","question":"いろいろな形で、今度はその議論を伺いましょうというような方向にいくのか、そこら辺の点がもしおありであれば言っていただく。今そういうお話が出たので、お気づきの点があるのであれば、ぜひ言ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"菊地委員","kind":"質問","question":"今の皆さんのご意見に沿うものかどうか、単純に、このページの中身に触れたときに、ここでちょっと疑問があるんだとかという部分ですので、今の皆さんのお話に沿う話なのかどうかはわかりませんけれども、質問をさせていただいていいんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"原委員","kind":"質問","question":"質問をされていいかどうかちょっと出たんですけれども、内容をどういうものを皆さんで討議するか、議論するかについて決めましょうという話ですよね。そして、この次の中で取り上げるか、あるいはいつになるかわかりませんけれども、そういう手順の持っていき方でないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"原委員","kind":"質問","question":"どちらかにしてほしいと思うんですよ。そうじゃなければ、質問した、それで終わりになってしまうという話になってしまうじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"菊地委員","kind":"質問・要望","question":"それだけに中身そのものを理解すべきものと、より良いものにするには、私自身の意見も出して論議するというのがすごく大事な部分だろうと思うんです。問題点を取り上げて、次回なら次回の正式な議題としていくということであれば、私はそのときに趣旨については発言をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/345074?Template=document&Id=2316#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":37982,"voices":110}},{"id":"h14-20020121-8","meetingId":"h14-cm01","date":"2002年1月21日","dateIso":"2002-01-21","committee":"建設委員会","time":"午後１時０５分～午後２時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"１の陳情の取り下げ","agenda":"１の陳情の取り下げ","exchanges":[{"speaker":"菅家委員","kind":"意見","question":"この件は前に、それにかかる現地視察をして、親族関係のもつれの関係だったと思うんで、取り下げに至るまでの経過を、簡単でいいから。","respondent":"浜脇住環境整備課長","answer":"何回かの住民説明会の中で、肝心な施設建設の内容について、住民周知がなされてなかったという経過がありました。１月２５日ごろから、双方の話し合いの結果、円満な方向に向かっていると思われます。","id":"exchange-001"},{"speaker":"菅家委員","kind":"質問","question":"もうひとつ、用途地域の関連でのもつれがあったように聞いているんですけど、それに対する注文というか、意見なんかはなかったんか尋ねました。","respondent":"浜脇住環境整備課長、伊佐都市計画課長","answer":"代表の方々が２回ぐらい、話し合いがうまくいく方向に行っているということでしたが、用途地域に関する話し合いをしているという情報は入っておりません。 私のほうから、放射第１９号線、第一京浜国道ですが、こちらの都市計画変更について、ご説明申し上げます。こちらの変更概要の２番目に、「車線の数の決定、６車線」と書いてありますが、代表車線としては６車線。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"それから、今後、例えば、車線数が変われば、その都度、都市計画審議会にかけてやるのか。そして、その対象は、国道、都道、区道も、都市計画道路は全部そういう定めになるのか、そこらを教えてほしいと思います。","respondent":"伊佐都市計画課長","answer":"は変更の際に行うこと」とされてありますので、変更のつど新しく定めていくんですが、それを電子データ化して。区としては、意見照会を受けて区計審に諮って、ご審議いただくという形になります。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"このときの扱いは、車線だけ決めて、路側帯はその範疇に入らないのかどうか。そこはどうなっているんか尋ねました。","respondent":"伊佐都市計画課長","answer":"都市計画道路の場合の車線数については、単路部と言いまして、交差点とかそういったものは考慮しない形で定めている。それに照らして、都市計画の幅の中で６車線が入るのかどうかという検討をする中で、路側帯が取れるかと内部的な資料としては検討されますが。","id":"exchange-004"},{"speaker":"築舘委員","kind":"質問・要望","question":"平成１４年末のあれですから、そのときは、また路線を変更しなきゃいけないと思うんですけど、そこら辺がどういうふうになっているのか。そのときに、一遍にやればいいんじゃないかなということも考えるんですが、その辺の理由を教えていただきたい。","respondent":"伊佐都市計画課長","answer":"１点目の、品９１の便が減るのかですが、まだ具体的なダイヤのご説明が行われてございませんが、全体としての便数は現行どおりにしたいと。なぜ変更するのかというご質問ですが、港湾局からの２億円の補助がなくなったということで、早急に経営状況の改善を図りたいと。","id":"exchange-005"},{"speaker":"築舘委員","kind":"質問・要望","question":"南品川の輸送力の確保のため、増便といいますか、別のルートをしっかりとつくっていただきたいということ。ですから、そこのところをまた考えて、しっかりと利用者にとって不便のないようにお願いしたいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"それから、羽田の国際空港化ということで、成田と大分軋轢がありましたよね。その辺のところは、どう仕切りがされたのか、教えてもらえるとありがたいんですが。","respondent":"伊佐都市計画課長","answer":"ただ、大田区の場合は、これに伴いましての沖合展開の跡地利用の部分ですが、まだ国との間で調整がされていない。逆に、今回の再拡張にあわせて、そちらの懸案事項についての議論もきちっとやっていただきたいという意見を言われていると聞いてあります。","id":"exchange-007"},{"speaker":"沢田委員","kind":"意見","question":"そちらのほうは、来年度なのか、どうなのか。今度のセミナーなんかも位置づけてやるべきだと思っているんですが、今考えていることがあれば、手短かに話してほしいと求めました。","respondent":"田村住宅課長","answer":"それと、３点目の適正化法の関係ですが、適正化法そのものにも、やはり、自治体の情報提供という役割も明記されております。その辺の情報提供をブロックでもぜひ必要だということで、今回、渋谷区のほうでご説明させていただいたです。","id":"exchange-008"},{"speaker":"沢田委員","kind":"意見","question":"広報にでも載せて宣伝すべきじゃないかとか、金をかけても役立つかどうかわからない」とか言って、そうやって現在に至っているわけです。その辺は少し進むんですが、まだ予算の発表の段階じゃないんですけど、考え方として、どうなんでしょうとの意見を述べました。","respondent":"田村住宅課長","answer":"特に３０年を超えた分譲マンションの実態ということについても、ある程度の把握が必要になってくるんじゃないかと考えております。その辺の法律の動きも含めまして、品川区としても、基礎的自治体としての取り組みを徐々に進めていく必要があるんじゃないかと考えています。","id":"exchange-009"},{"speaker":"上山委員","kind":"質問・要望","question":"実際にそのときのテーマによっても違うかと思うんですけれども、参加者からいろいろな要望なり、あるいは質問だとか出されたと思うんです。修繕積立金がどうなっているのかだとか、お尋ねしたいんですけれども、いかがか尋ねました。","respondent":"田村住宅課長","answer":"最も関心のある問題は何かということで、４０名中３４名の回答をいただきまして、やはり一番関心が高いのが大規模修繕についてということで、２０名。ダブルカウントしていますので、若干数字的な問題はありますが、そんな状況です。","id":"exchange-010"},{"speaker":"上山委員","kind":"質問","question":"後で理事長さんなんかを含めて、今後どうするのかと大分悩んでいたようで、その日にまた管理組合の会議をやっていたようなんです。広報で２１日に周知されるということなんですけど、質問を出されたりして、そこら辺はいかがか尋ねました。","respondent":"田村住宅課長","answer":"講演会プラス、それぞれテーマを決めて、後段はグループ討議といいますか、今までも情報交換の場を設定しています。こういうやり取りをして、参考になればという形で上げることはできるので、何か工夫をしてみます。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/807981?Template=document&Id=3710#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":17511,"voices":57}},{"id":"h14-20020121-9","meetingId":"h14-cm01","date":"2002年1月21日","dateIso":"2002-01-21","committee":"文教委員会","time":"午後１時５分～午後２時４３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"それから、一貫校というのは新たに検討をするというのは、いつどこでどういうふうに決めたのでしょうか。だから、小中一貫校をやろうというカリキュラムを組むんですから、教育委員会の中で論議があったのか、その辺の経過を知りたいんです。","respondent":"指田教育次長","answer":"いつからかという形になりますけれども、当然のことながら教育改革プラン２１を進めていく中において、さまざまな検討をしてきてあります。そういった点から見れば、教育改革が始まったときから検討が入っていたというふうにお考えいただいて結構ではないかと思ってあります。","id":"exchange-001"},{"speaker":"桜井委員","kind":"意見","question":"プラン２１推進委員会で検討されているのかなと思っても、第９回までいただいているんですけれども、９回までの中では入っていませんよね。だから、どこで論議がされたのかというのを知りたいんですとの意見を述べました。","respondent":"指田教育次長","answer":"内容によってはプラン２１推進委員会にかけて、中身を全部固めて、これで来年度からやっていくんだというものでもございません。例えば、これからどういうふうにすればいいのかとかいろんなことが出てくるわけですから、その点を含めて小中一貫校という検討が出てきて。","id":"exchange-002"},{"speaker":"桜井委員","kind":"確認","question":"今までの連絡校のレベルと全く違う学校づくりにいくわけですから。だから、ここに書いてある事実はどれで、そうでないのはどこかというのを確認したいんですけれども。","respondent":"指田教育次長","answer":"今、あるいは各党への説明はどうなのかという問題がまいってまいりますので、ぜひともご理解いただきたいというふうに思ってあります。必ずしも、すべて議会にお諮りした上で、これから検討に入りますという問題でもないだろうというふうに思っているところです。","id":"exchange-003"},{"speaker":"桜井委員","kind":"質問","question":"それで質問しているんですよ、そうじゃないですか。事務局と言うけれども、次長と学務課長と庶務課長なんですか、どこか尋ねました。","respondent":"指田教育次長","answer":"２月８日のプレス発表を待って、きちんとルールに乗ればきちんとご説明をさせてくださいという話をしているわけです。委員会の中でどこのレベルまで検討しているのかという話についても、もうしばらくお待ちいただきたいという話をしているわけです。","id":"exchange-004"},{"speaker":"桜井委員","kind":"質問・要望","question":"そういうことであれば、２月８日以降にきちっと今までの経過と論議の内容を委員会にご報告ほしいと求めました。それはどうか尋ねました。","respondent":"指田教育次長","answer":"当然、２月８日以降になりますと、開催中の委員会になります。したがいまして、ご質問が出てくればきちんとお答えはしていきたいというふうに思っております。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問","question":"一般質問、代表質問でなければ答弁しないということではなくて、委員会の中でちゃんと経過も含めて文書でいただくということでいいんですね、委員会の中でやらないということか尋ねました。","respondent":"指田教育次長","answer":"したがいまして、当然いろんな質問が出てくることも予測されています。３月の開催中の委員会の中ですから、今のところ約束できるかと言われますと、約束は今の段階ではできません。","id":"exchange-006"},{"speaker":"松澤委員","kind":"意見","question":"そのときの反省点はどういうふうになったのか、「以後、気をつけます」とか何か言葉を言っているんだと思うんです。その体質を何とかしてもらいたいと私も思いますので、その点についてとの意見を述べました。","respondent":"若月教育長","answer":"「この小中連携の限界は何だろう」とか、「小中連携でどういうふうに発展していってもらいたいか」とかお伺いすることが多いわけであります。ご指摘いただきましたように、今後こうしたことの起きないように、改めて自己点検をさせていただきたいと考えているところです。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"ですから、私たちとしては実際にこれをいただいたものですから、ここで議論しないといけない思います。やはり今の教育長のお話を伺えば、「わかりました」と私たちも考えざるを得ないかもしれないということで、本当に情報管理の大切さ……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"川西委員","kind":"質問","question":"私はあまりテレビを見ない人ですからわからないんですが、そういうことで聞かれます。そこだけちょっと教えておいていただければ、プレス発表までまだちょっとありますから、わかる範囲で教えておいてもらえば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"川西委員","kind":"意見","question":"そうすると答えていただけないのはなぜかという──では、そういう疑問を持ちましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"桜井委員","kind":"意見","question":"ちゃんと一つの筋道として、教育委員会はどういう見解を持っているかぐらいは聞きたいよね。見解は全くないのとの意見を述べました。","respondent":"指田教育次長","answer":"でも、私どもも本当に２月８日を過ぎませんと、どうしてもこれだけはお話ができません。これだけはやはり基本としてはルールがあるわけですから、そのルールだけはぜひともご理解のほどをよろしくお願いしたいというふうに思います。","id":"exchange-011"},{"speaker":"高星委員","kind":"意見","question":"だから、どうもその辺でちょっと心配なところがあるんだけれども、同じようなことを聞いたような気がするんだけれども。あれの状況、貯金がたまったのかどうなのかとの意見を述べました。","respondent":"鷹倉庶務課長","answer":"今年度末で８６億円を超えます。最終補正はまた別の話としましても、今の段階でわかっていることでは、年度末で８６億円になるです。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"改築計画指針に対する質問ですけれども、これは規模はどのぐらいを見ているんですか。避難したりする部屋なんかがあるというんですが、今の形より大きくなるので高層化になるのではないか、この辺の考え方をお願いします。","respondent":"鷹倉庶務課長","answer":"冒頭の校地利用計画のところに書いてありますけれども、区内の敷地、当該校の敷地を最大限有効活用したいという考えは当然です。したがって、今言えることは、当該校の敷地を最大限有効活用するということだけは間違いございませんと、今の段階では言えます。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"前にもお話ししたことがあるんですけれども、昭和３０年代というのは古い建築基準法ですね。そうすると、その学校は必然的になくなるという考えでよろしいんか尋ねました。","respondent":"鷹倉庶務課長","answer":"５８校あるわけですけれども、今のお話のとおり小さな形でおさまるのか、全く建たなくなるのか。ただ、一番ベースの部分ですから、まずやっていけるだろうというところをまず抑えつつ進めていく必要があるのではないかと考えております。","id":"exchange-014"},{"speaker":"飯沼副委員長","kind":"質問","question":"基本的なところをお伺いしたいんですが、プラン２１のところには、基本的なところを説明を求めました。","respondent":"鷹倉庶務課長","answer":"いろいろなブランチ的な委員会にするのか、ここを合併するのか、それも今後考えてまいりますけれども。改築のほうは、こちらのほうでやっていくような役割分担になっていくのではないかという、今、整理整頓の方向性を持ってあります。","id":"exchange-015"},{"speaker":"飯沼副委員長","kind":"質問","question":"メンバーについてと従来のところの絡みで改築をということですけれども、従来の流れと改築のところが、今後どういうふうに進んでいくのかという、その辺の見通しというか、その辺までは計画にはなっていないんか尋ねました。","respondent":"鷹倉庶務課長","answer":"それともどういう形でやっていったらいいのか、それも今検討していますけれども、十分その辺の意見を聞いていかなければいけない。これはできれば４月か５月あたりにまとめ上げていきたいと考えています。","id":"exchange-016"},{"speaker":"飯沼副委員長","kind":"質問","question":"どんな学校があったらいいのかという、この辺がどういう経過からこれが取られたのかということと、作文のところも人数的には出ていますね。だから、どういう結果でここまでこぎつけたのか、その背景を教えてほしいと思います。","respondent":"鷹倉庶務課長","answer":"去年の４月から学校改築検討委員会という形で進んでいったわけですけれども。児童・生徒の気持ちとして自分たちが提案できるというものを、今回夏休みの宿題の課題の一つという形でやらせていただきました。","id":"exchange-017"},{"speaker":"飯沼副委員長","kind":"質問","question":"夏休みの課題の一つとして、どこか特定の学校ではなくて、全体的にかけて出てきたものの一部ということですか、これが全部ということか尋ねました。","respondent":"鷹倉庶務課長","answer":"やはり、学校によってはいろんな課題がいっぱいありますので、子どもたちが乗らなかった部分もあります。これは全校に投げかけて出てきたものすべてです。","id":"exchange-018"},{"speaker":"飯沼副委員長","kind":"意見","question":"特に、今回親のところがまだないですよね。その辺保護者のところと地域の意見を今後どう受け止めて反映させていく考えがあるのか、その辺を聞かせてくださいとの意見を述べました。","respondent":"鷹倉庶務課長","answer":"ただ、それぞれ具体的な学校が決まった段階で、具体的にどういう形に学校づくりをしていくのか、そういうところの関心が強いのではないかなと。","id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"資料のところで幾つか具体的なことで伺いたいのが、「冷房は、「そう思わない」というところが圧倒的にパーセンテージが高くなっています。私ども質問なんかで「普通教室のクーラー設置をぜひお願いしたい」と、たびたび要望しているんですけれども、検討をする」とありましたね。","respondent":"鷹倉庶務課長","answer":"従来、いろいろ検討していきたいということですけれども、具体的な表現の中でこういう形でさせていただいたです。そうすると、バリアフリー化の点も当然考慮しつつ、この点は検討していく必要があるです。","id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"４階建てにおいても障害を抱えた子どももそうだし、ぜひ高層化にかかわらずエレベーターの問題を考えていっていただきたいなと、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"川西委員","kind":"質問","question":"２ページの２行目ですけれども、「近年改築を行った自治体の先進校を視察した」というのは、どういうところなのか教えてください。それから、中間のまとめで今回発表されましたが、最終決定までのスケジュールを聞かせてください。","respondent":"鷹倉庶務課長","answer":"平成１１年ないし１２年に比較的問新しい考え方に基づいて、いろいろ新しい考え方に基づいてつくった学校と言われてあります。したがって、４月ないし５月ごろにはまとめ上げて、次のステップに入っていきたいなというふうに考えてあります。","id":"exchange-022"},{"speaker":"川西委員","kind":"提案","question":"あれは一定の素案というものを提案されて、それから東京都が提案した場合には区で半年とか７カ月ぐらいあるわけです。これはお願いをしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"桜井委員","kind":"質問","question":"例えば２００６年と想定した場合に、そういう品川区の教育の行政の水準というのか、そういう形というのはどうかなと思うんです。施設連絡会で検討するならそれでいいんですけれども、そこもやっぱり明らかにしてもらいたいと思うんですけれども、いかがか尋ねました。","respondent":"鷹倉庶務課長","answer":"したがって、中間のまとめに書いてあることは、新しい考え方として大体どなたも了承していただけるようなことが書いてあります。２番目の質問にも関係してくるわけですけれども、我々の力の及ぶ限り精力的に邁進していく必要があるのかなと考えているところです。","id":"exchange-024"},{"speaker":"桜井委員","kind":"質問・要望","question":"後段のレベルアップについては、施設連絡会で基準をつくってやっていくのか、そこのところをもう少し確認したいんです。最後に、予算的にもっとかかるとか、いや国からもっと持ってくるとか言ったけれども、予算はどんな感じなんか尋ねました。","respondent":"鷹倉庶務課長","answer":"これがこういう形で説明の中云々という話が出てありますけれども、整理していただきたいのは、全体の学校の改築指針という形の位置づけです。そういうものを踏まえながら、８６億円を大事に使っていく必要があるかなと、このように考えてあります。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"意見","question":"これから改築なさっていく段階において、考え方なんですけれども、例えばどこかの学校を直す場合、そこの敷地を使って直していくのか、それとも今６年生の生徒をどう考えていくのか、戸越台中みたいに新たな場所で何年間か教育を考えているのか、どういう考え方でやっていくかとの意見を述べました。","respondent":"鷹倉庶務課長","answer":"そうすると、５８校の中で、拠点的なところがうまく見つかるかどうかというのが非常に難しい。ご父兄の方々もその間の教育はどうなんだと、一番心配されている部分ですので、十分今気をつけながら進めていきたいと考えています。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"意見","question":"その辺はよく考えておいて、今までも当然考えているんでしょうけれども、その辺を十分重点を置いてもらいたいなということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"桜井委員","kind":"質問","question":"それは４月の入園の段階で決まるということなんでしょうか、１名の補欠はずっと補欠のままというふうになるんでしょうか。それともう一つ、この間の鈴木真澄委員の質問の区立幼稚園に保育室の関係は何か具体的に進んでいるのか尋ねました。","respondent":"久保田学務課長","answer":"いろんな考え方ができるわけなので、１人の方はいつまでも待ってみたいと、そちらを尊重しているです。区立幼稚園の検討ですけれども、鋭意検討している最中ですので、現在のところでは特にお話するような段階ではないということでお願いいたします。","id":"exchange-028"},{"speaker":"桜井委員","kind":"質問","question":"それから、全体に一時期少なくなってくると、希望者も一定程度来ているというのは、景気の関係なんでしょうか。それから、後段のほうは、これも２月８日以降なんか尋ねました。","respondent":"久保田学務課長","answer":"したがって、なかなか今年の特徴も見えにくいところがあるんですが、やはり昨年と比べるとかなり応募人数も少なくなってきている。この傾向が来年も続くかどうか、まだわからないというような状況です。","id":"exchange-029"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、対象年齢は去年より今年は減っているのかどうか。桜井委員の質問では景気の動向とかおっしゃっていたけれども。","respondent":"久保田学務課長","answer":"子どもの状況について、手元に資料がないので正確なお話はできないんですが、多分そんなには変わっていないというふうに思っております。多分、同じような人数というか、幼児人口になっているのではないかと思います。","id":"exchange-030"},{"speaker":"川西委員","kind":"意見","question":"対象年齢が変わらなくて、幼児人口が変わらなければ、景気の動向で保育園に流れたというのは、それを書いておかないとあれですよね。保育園も締め切りは終わりましたから、ちょっととらえておく必要があるので、参考に把握しておかれるといいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/547087?Template=document&Id=4428#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":29182,"voices":77}},{"id":"h14-20020122-7","meetingId":"h14-cm01","date":"2002年1月22日","dateIso":"2002-01-22","committee":"厚生委員会","time":"午後１時０９分～午後４時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件整理しています。","topics":[{"id":"topic-01","title":"平成１３年請願第１２号、新たな大気汚染公害被害者の救済を求める意見書に関する請願","agenda":"平成１３年請願第１２号、新たな大気汚染公害被害者の救済を求める意見書に関する請願","exchanges":[{"speaker":"伊藤委員","kind":"意見","question":"もう少しこのことについては、うちの会派内では議論をさせていただいて、しばらく時間を置いて調査していきたいと考えています。ちょっとそれは意見として述べしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"８７年のとき、これは毎年どれくらいの人数が新規で登録されているのかということをちょっと経過を追って教えてほしいと求めました。大阪市では、品川区の場合、この学校保健調査でこの推移がどうなっているのかということについて教えてほしいと求めました。","respondent":"田中健康課長","answer":"ちょっと詳細は申しわけありませんが、そんなところです。それから、学校保健の関係につきましては、ちょっとデータを持ちあわせておりません。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３年間でこれは１６６名がなぜ年間３０名というふうになっちゃうのか、これが８７年当時あたりがどういうふうになっているのか、ちょっと説明を求めました。","respondent":"田中健康課長、青山品川区保健センター所長","answer":"大きく変わりましたのが昭和６２年９月、すべての第１地域で環境基準が達成されていたということで、地域指定が解除をされたです。それから総合的な環境保健施策を推進するということで… 例えば平成１１年度ですと１,３２７名、平成１２年度ですと１,３６８名、その中の差が新規と。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そして大阪市以外の府全体でも３倍ぐらいずつ増えているという、東京の都市部でも同じような状況が言えるのではないかなというふうに思うんですね。そういうふうなところでは、そこら辺のところでは、どう考えられているか尋ねました。","respondent":"青山品川区保健センター所長","answer":"動物飼育中の患者が３０％であったり、ダニ対策についてほとんど知らない患者が４７％というような形で、この点についてはさらに充実した指導が行われていくように努めてまいりたいと考えています。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういうふうなことがほんとうに明らかになっているわけですから、これは区の制度としてつくっていくというのはなかなかできないことですから。２％除外値で１番で、２３区の中でも品川区が大気汚染もかなり大変な状況にあるというふうなのが、区としてはどう考えられているんか尋ねました。","respondent":"田中健康課長","answer":"私どもが環境課からちょっともらいましたものでは、平成１１年、１２年については窒素酸化物についても環境基準を達成している。それから浮遊粒子状物質についても１１年と１２年度で八潮測定局で環境基準を達成しているというような評価ということでご報告申し上げました。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"しかし、裁判の判決にもいい影響が出るようなというふうなところでも、品川区議会としてぜひ意見書を上げていっていただきたいというふうに思います。これは２３区の中でも、そこのところの２３区の請願の審査の状況とかがわかったら、最後に教えていただきたいんですが。","respondent":"田中健康課長","answer":"それから、１区は、これはさっき東京の訴訟の問題が出ておりましたが、東京の訴訟に係争中なので却下というところがあったそうです。不採択が２区ほど既にございまして、私どもでいう継続かと思いますが、ほとんどのところがそのような傾向でございました。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私が聞いたほうが後だったのかもしれないんですが、今２３区の中でも北区と中野区が意見書を採択して、もう既に出したということでお聞きしました。どんどん増えてくるんじゃないかなというふうに思うんですが、品川区議会でもぜひ意見書採択ということで賛成していきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須藤委員","kind":"質問","question":"今の発言の中で、この請願を採択すると、裁判にいい影響を及ぼすとかというふうな話があったけれども、そういうことが委員長、この委員会であるんか尋ねました。","respondent":"林（和）委員長","answer":"鈴木委員の考えでしょう。そういうふうには思いませんけれども、鈴木委員自体がそう思っているということで。","id":"exchange-008"},{"speaker":"須藤委員","kind":"意見","question":"委員会の中でそういう発言をされて、品川区議会の方向性がそういう裁判に影響を及ぼすからぜひ上げろというふうな表現でされて、委員会運営自体がいいのかなというような感じがしたので、ちょっと委員長にとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問・要望","question":"多少時間をかけて検討させていただきたいというふうに思っておりますので、結果としては、もう少し時間をとっていただきたいと考えています。それから、確認ですけれども、ほんとうに公平な立場で裁判を進めていただきたいと考えていますということの意見だけ伝えておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鶴副委員長","kind":"意見","question":"でも、今特定できない以上は早急な結論を出すことがいいことなのかどうかとなると、慎重にならざるを得ない。もう少し慎重な審査が必要ではないのかというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"船波委員","kind":"質問","question":"私は、取り扱いをどうするかということを端的に言ってしまえば、採択してほしいという気持ちを持っています。早く何らかの救済方法が確立されてほしいと思いますので、もう既に１回継続審議になったわけですから、これ以上先延ばしにするというよりも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鶴副委員長","kind":"質問","question":"いいじゃないですかと、ここには特に自動車メーカーだとか燃料メーカー等の財源負担、そうなっている。ほかの原因はありませんかと、それだけですかということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"高木委員","kind":"質問","question":"私も不勉強ですけれども、実際には放置できない状態ではなかろうかと思うから、新しい東京都知事も相当の対策に乗り出しているように伺っております。心情的には採択して意見書を提出するということですから、ああだというような、集約できるように計らいをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"鶴副委員長","kind":"質問","question":"でも、そういうところでこの請願の紹介者になっている人に聞かなきゃいけないから、そういうことでいいですかということを。そのためにも継続の扱いになって、今日はよかったなというふうに思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"船波委員","kind":"質問・要望","question":"この公害との関係が関連があると証明できたと言えるのか、あるいは関係ないと言えるのか、それは何なんでしょうか。ですから、継続審議になって、じゃあ次回は何を明らかにしていくのかということを何か示していただきたいと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-02","title":"平成１３年請願第１３号、政府の医療制度改革に対する意見書の提出を求める請願","agenda":"平成１３年請願第１３号、政府の医療制度改革に対する意見書の提出を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"前回の提案が４万２００円だったのが１万２,０００円にということで、この年収が２人世帯で６３０万円あるという世帯がどれくらいなのか、それからあと２６０万円未満の方がどのくらいなのかというところをちょっと説明を求めました。","respondent":"野田口高齢事業課長","answer":"例えば低所得者２の部分につきましては、全国レベルで１５％ということなので、低所得者の部分につきましては品川区でもそれに準拠しているかなと。６３０万円というのは、簡単に出てくるような数字ではございませんので、ちょっと申しわけございません。","id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"この請願が出されたときの９月２５日の試案と、あるいは請願人のほうから、このことについては同じままで残されているんですか。この文書のままに読んでいっちゃうと、違う話をここで審議しなきゃいけないだろうと思うんだけれども、その辺についてはいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"須藤委員","kind":"質問","question":"３、４は一般的な話だから、いかがでしょうか。それから、紹介議員の方から何らかの説明があって、委員長のほうにご説明があって、こういう経緯だけれどもという経過があったか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その(1)番に対しても、結局(2)番のところで書かれているように、老人医療の負担が増えるということは明らかだと思うんですね。８,０００円、４万２００円という形で上がるわけですから、この中身で審査してもいいのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これから国会に提出されようというときですから、低所得者の医療費と保険料の負担をこれ以上増やさないことを求める意見書となっていますので、審議できるんじゃないかなというふうに思うんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"どうしたら守れるんですかと。どういうふうにしたら社会は安定できるのですかということをこの紹介議員の人たちに聞いてみたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"伊藤委員","kind":"提案","question":"だけれども、じゃあ、今の保険制度をどう維持していくんですか。ですから、じゃあ簡単に増やさないことを求める意見書を品川区議会として出していいのかというと、ちょっと待てよとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２５０万円未満までで８２.６４％って、そして昨年の１月からはもう既に１割負担という形で大きく負担が増やされたばかりですから。ちょっとお聞きしたいんですが、ぜひ教えていただきたいんですが、。","respondent":"野田口高齢事業課長","answer":"日経の１２月１９日の部分なんですけれども、例えば一般の方で１万２,０００円が上限ですけれども、これについては高齢者全体の１％弱程度です。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"でも、この請願については、ここの厚生委員会でしか扱わないわけですよね。この審査の中にご答弁いただけるような体制をつくっていただけないかというふうにお願いをしたんですが、その件はどうなったか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その関係する所管の課長とかにここにおいでいただいてご答弁いただくという、そういう仕組みというふうなのはできないということなのでしょうか。事前に調べておくということしか、そういうふうな、方法はないんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その製薬会社は、この不況の中でも不況知らずというふうな状況の利益率を上げているわけですから、そういう利益率を上げている状況ですから。中小企業の方が倒産したり、ほんとうに高齢者の方も次から次へと負担が増えた上に今度の負担増ですから、ぜひ今でも大変な医療制度ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"須藤委員","kind":"意見","question":"国保どうのこうのと言うと、それぞれまた調査してもらわないと長くなっちゃうだろうし、時期が外れてくるので。ちょっと結論を出されたらいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"鶴副委員長","kind":"質問","question":"前年に比べたら多少減っていると言っても、２１１人のお子さんが年末保育の措置にあずかっているわけですが、どういう理由が一番多いですかね。そういう人たちもいろいろいらっしゃると思うんですけれども、理由か何か、そういうのを分析したものはありますか。","respondent":"金子保育課長","answer":"それから、例えば病気等で父親が働いていないとか、あるいは母子家庭のため父親がいないというような場合が２２％というふうな状況になっております。","id":"exchange-029"},{"speaker":"鶴副委員長","kind":"質問","question":"今ここに実施園が限定的なんですが、地域によっては、私たちのほうでもやっていただけないでしょうかというような声はあるのかないのか、その点ちょっとお知らせください。","respondent":"金子保育課長","answer":"あるいは自分の子供が在園しているところで実施して、今回８園しかやっておりませんので、自分の在園のところでできればやってほしいというような声も若干聞かれております。","id":"exchange-030"},{"speaker":"鶴副委員長","kind":"質問","question":"この保育行政に関連してちょっとお伺いしておきたいんですけれども、なかなかいいというような評価も届いたり、最近ではどんなのがありますか。そういうものがありましたら、ちょっとご紹介いただけませんか。","respondent":"金子保育課長","answer":"病後時、こういったものについて拡大して実施してきているわけですので、非常にその点に関して感謝しているといった声が多く寄せられていることは事実です。","id":"exchange-031"},{"speaker":"鶴副委員長","kind":"質問","question":"これは年末保育のときの給食というんでしょうか、これはどうなっているのかなというふうに思うんですね。何かそういう意見は届いているんじゃないか尋ねました。","respondent":"金子保育課長","answer":"実施する前の週、担当する職員数、そして食数というのを出しまして発注するというふうになっております。これが現実ですので、そういう意味では実際に食べている方からの評価というのがその辺にあらわれているというふうに考えているところです。","id":"exchange-032"},{"speaker":"鶴副委員長","kind":"質問","question":"品川区の場合は皆さん意識改革をなさっているから、この年末保育のことについてとやかく言っている保育士の方は皆無だと思いますが、いかがか尋ねました。","respondent":"金子保育課長","answer":"私も当日３日間にわたり各園を回らせていただきましたけれども、そこでは各職員とも意欲的に出勤して仕事に当たっているということがございましたので、私の見る限り、あるいは声としては、委員ご指摘のような心配というのはないというふうに考えております。","id":"exchange-033"},{"speaker":"船波委員","kind":"質問","question":"源氏前でも大井倉田でも預かる子供の数が２なのに、職員の数は３と２になっていますけれども、これはどうしてこうなってしまったんでしょうか。ちょっとその辺お伺いしたいと思います。","respondent":"金子保育課長","answer":"私のほうの説明を省略してわかりにくいところがあったところは申しわけないと考えていますが、実施していないというところです。実施するに当たっては、まず責任者を１人配置するというふうに基本的に考えておりまして、ここでは年齢の差があったがために。","id":"exchange-034"},{"speaker":"船波委員","kind":"質問","question":"それから預かる子供が２人というのでは、その子供たちも、例えば１０人ぐらいして遊ぶよりは２人では何か寂しいような気がしてしまうんですが、希望が少ないところに関しては、例えば今年は違う園にしてみるとか、そういった人数を見て、これからの予定に関して何か変更などは考えられるのか尋ねました。","respondent":"金子保育課長、林（和）委員長","answer":"来年度の実施に関してはいろいろな要素もありますので、慎重に検討して、来年度の実施を考えていきたいというふうに思っております。 ほかにございませんか。ないようですので、これで(1)の平成１３年度年末保育の実施結果についてのご報告を終わります。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問・要望","question":"なぜ中止になったかということとか、もう少し中止になった背景をお知らせいただきたいのと、予定どおりそこにできるんでしょうか。その見通しはわかりますか尋ねました。","respondent":"田中健康課長","answer":"この新聞記事で説明を受ける中でもらったわけなんですが、こちらの説明によりますと、これは全国ベースでございましてという報告でございました。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認をしていただきたいのと、もし病院独自がここにできないということになってくれば、別な政策選択の余地が広がってくるんじゃないですか。でも、その後品川区としてはどうするんですかということをお伺いしたいんですが、答弁はありますか尋ねました。","respondent":"田中健康課長","answer":"向こうからの説明は一切今のところ何も決まっていないという状況です。そういうことですので、品川区としてこれからというところは、私どももまだ現時点では考えておらないです。","id":"exchange-037"},{"speaker":"伊藤委員","kind":"意見","question":"簡単にまとめていきますけれども、病院がなくなるということの考えといいましょうか、その問題は私はすごく深刻にとらえている部分があるんです。もし移転した後、もう少し品川区として都南病院の跡地については検討してくださいということをお願いしたら、答弁いただけますかとの意見を述べました。","respondent":"新美保健高齢事業部長","answer":"平成６年当時からの社会保険庁の病院統合、私どもも区議会のほうにとりあえずこういう状況であるということをご報告する、そういう段階というふうにぜひご認識いただきたいというふうに思います。","id":"exchange-038"},{"speaker":"鶴副委員長","kind":"質問","question":"品川区内には、ここを含めて病院は幾つだったんですかね。","respondent":"田中健康課長","answer":"１２年１２月３１日現在で、診療所の数、病院の数が１５です。","id":"exchange-039"},{"speaker":"鶴副委員長","kind":"質問","question":"へーっと思ったぐらいですが、ちなみに品川区立の病院というのはつくってもらえないんですかというご意見もあるんですよ。そっくりそのまま買い上げて、正式な場で聞いたことはないんですけれども、区立病院はつくってもらえないのですかという意見があるんですが。","respondent":"新美保健高齢事業部長","answer":"２次医療圏、２次医療圏単位で病院は整備するという考え方になっておりまして、こういうのが現時点での制度上の評価になっております。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"なぜ今回高脂血症が入らなかったのかというのを一つお聞きしたいのと、これから６カ月間の間、そういうふうなのはあるのかどうなのかについて説明を求めました。","respondent":"田中健康課長","answer":"実はこの事業をいろいろ進めるに当たりまして、両医師会のほうから代表の先生をお願いいたしまして、５回ほどにわたって準備会を進めてまいりました。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"東京都の補助事業ということなんですが、じゃあ、これは具体的にどれくらいの報酬になるのか、東京都から全額出るのか、それとも区のほうも何割かは出るのか、そこら辺のところもちょっと説明を求めました。","respondent":"田中健康課長","answer":"それから、東京都のほうの補助は２分の１かと思います。東京都のほうが単独で実は補助をモデル的にしておりまして、そういう形で進行する予定です。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"こういう指導ができるというのは、そういうふうな系統的にやられるというのはほんとうにいいことだなというふうに思います。高脂血症というのはかなり影響が強いというふうに思いますので、今後とも入れていただくような方向でぜひご検討いただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"嶋委員","kind":"確認","question":"なぜ自分はこうなってしまったのかという原因がわからないという人が大分多いので大変うれしいと思います。確認、今までは大体要指導の人がどのくらいいて、今回一応どのぐらいの人数を見通しをされていらっしゃるのかお聞きしたいと思います。","respondent":"田中健康課長","answer":"申しわけありません。すみません、今ちょっと予算のほうの数字を持ってきますので、ちょっとお待ちください。","id":"exchange-044"},{"speaker":"鶴副委員長","kind":"質問","question":"ところで、区民健診を受けている人は、今、受診率はどのくらいか尋ねました。","respondent":"田中健康課長","answer":"１２年度の実績で言いますと、区民健康審査１次審査を受けていらっしゃる方が３万５,８７６人あります。それで、４０歳以上の人口がすべて対象にしていますので、１２年度でいきますと、率で２１.５％です。","id":"exchange-045"},{"speaker":"鶴副委員長","kind":"質問","question":"それは何かというと、これは本人の希望があるものを対象というふうになっているじゃないですか、今回のこの改善の。私もやっぱり教えていろいろ相談に乗ってもらって、その点はどういうふうに、そこらあたりをちょっと聞いておきたいんですが。","respondent":"田中健康課長","answer":"今回予定していますのも、先ほどのお答えは申しわけありませんが、実は２けたになるかならないかという件数なんだそうです。ですから、いろいろな形の問題点をこれから積み上げながら、少し研究しながら進めていきたいというふうに考えてあります。","id":"exchange-046"},{"speaker":"嶋委員","kind":"質問・要望","question":"あれなので、積極的に区としては、ぜひ取り組んでほしいと求めました。この６カ月間の効果を、ぜひしっかりと評価が出るようなご指導をいただいて、１人でも健康の増進にお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"このリーフレットを見すると、一番上のところに年齢が４０歳から６９歳の方を対象にということになっているんですが、７０歳を超えた方は、もうこの指導を受けたいというふうに希望しても受けられないのかどうか、説明を求めました。","respondent":"田中健康課長","answer":"いろいろ７０歳を超えていらっしゃる方は、残念ながら併発をされているとか、一定のこういう要素を持っていらっしゃる方が多いのではなかろうか。","id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"モデルをやった後になるのかどうかわからないんですが、ぜひご検討いただきたいなというふうに思うんですが、いかがか尋ねました。","respondent":"田中健康課長","answer":"それから、ほかの区の例も調べさせていただきましたら、東京都の基準の中で、やはり私どもと同じ選択を近隣の２区もしているようです。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さらに充実の方向でぜひご検討ほしいと求めました。","respondent":"林（和）委員長","answer":"ほかにございませんか。ないようですので、これで３番目の生活習慣改善指導推進事業の実施についての報告を終了いたします。","id":"exchange-050"},{"speaker":"嶋委員","kind":"質問・要望","question":"理由が何項目かありましたらちょっと教えていただきたいことと、それと、ショートステイもいろいろな申し込み方法があると思います。たまたまそれがどこかに印がされていなかったということがあったのでお聞きをしている状況がありますので、教えてほしいと求めました。","respondent":"中川原介護保険担当課長、早津高齢福祉課長","answer":"更新時における要介護度変更の中で軽くなった理由ですが、大きくは二つあります。この間確認しましたところ、やはりケアプランのサービス内容でかなり改善ができているケースが多いというような結果が出ているようです。今ご説明申し上げましたように、ショートのほうもかなり人気が高うございまして、満杯に近いような状態ということになっております。","id":"exchange-051"},{"speaker":"嶋委員","kind":"質問・要望","question":"ご本人にとってもすばらしいことなので、ぜひこれを大きくどんどん、軽くなっていく方を一人でも多くぜひ頑張ってほしいと求めました。いわゆるパソコンとかそういうのでネットワークとか、どこが今空いているとかというのは、わかっている状況があるのかちょっと教えていただけますか。","respondent":"早津高齢福祉課長","answer":"パソコン等で予約状況、空き状況というのはほとんど難しいです。いかないはあるんですけれども、かなり人気の高い状態なので、現行の状態で当面推移を見守りたいというふうに考えてあります。","id":"exchange-052"},{"speaker":"鶴副委員長","kind":"質問","question":"それで、その保険料の中で、どういう相談というか、多いんですか。あるいはちょっと高いから払い切れないとか、何とかもう少しならないんでしょうかとかいう、その中身は、主立ったものはどういうことか尋ねました。","respondent":"中川原介護保険担当課長","answer":"自分は申し込んだのにどうなっているんだというような、そういったものが昨年度といいますか、今年の前半は多かったようです。それから手続上のまだ不慣れな部分について、苦情というよりは、お問い合わせ的なものが多いというふうにとらえております。","id":"exchange-053"},{"speaker":"鶴副委員長","kind":"意見","question":"がっかりもしたりすることはあるんですが、それは何かというと、去年の１０月から当初の予定どおり保険料を徴収するようになったじゃありませんか。何本かぐらいはとの意見を述べました。","respondent":"中川原介護保険担当課長","answer":"何件というのは１けたです。１０件の、そういう範囲でございました。","id":"exchange-054"},{"speaker":"鶴副委員長","kind":"質問","question":"それは、だからどういう言い方を皆さんお問い合わせのときに、不満でもいいから、とんでもないという言い方なのか、いや、全然そういう制度上のことを知らなくて、ああそうですかと、そうだったんですかとか、最初からもうとんでもないとか、そういうたぐいのことですよ。","respondent":"中川原介護保険担当課長","answer":"９月の苦情の中では、倍取られるという表現がございました。","id":"exchange-055"},{"speaker":"鶴副委員長","kind":"質問","question":"そのときに、説明したら、ああわかりましたと、それでもけしからんというふうなことなのかどうかということがちょっと知りたいんですね。ああわかりましたと、そういうことですかと言う人も中にはいるんじゃないかなと思うんですよ。","respondent":"中川原介護保険担当課長","answer":"９ページの対応状況のところにもご案内しておりますが、職員が窓口もしくは電話で説明させていただきまして、全件ご了承いただいております。そうですかという感じです。","id":"exchange-056"},{"speaker":"須藤委員","kind":"質問・要望","question":"もっとこの年齢で１２.何％でキープできるような状況があるのかどうかというような、今後の予想についてお知らせほしいと求めました。細かい点については、あとまた勉強しますので。","respondent":"中川原介護保険担当課長","answer":"現段階では、保険年金課に確認しましたところ３６％ということで、年度末には９８％近くまで上る予定であるということでございました。今健康づくりのプラン２１とか、要支援と要介護の方が６割いらっしゃいますので、介護重度化予防について今検討を進めておりますので。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"教えていただきたいんですが、入らなくて何とかしてほしいとかという、ちょっと教えてほしいと求めました。とりあえず、その点について説明を求めました。","respondent":"早津高齢福祉課長、中川原介護保険担当課長","answer":"そうすると、１カ月幾ら予定と。１０６億に対して７０億というと７０％になりますけれども、その予定までの分でいくと８８％ぐらいの執行率であるというのが概況です。 苦情対応票というのがございまして、職員１人１人がそれに記入しまして、部長まで回すような仕組みです。それを集約したのが、この対応状況ということになります。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"サービスセンターのほうからになるんでしょうか、それもなかなか難しい状況だというふうな話をお伺いしたんですけれども、ちょっとどういうふうな状況になっているのかについて教えていただきたいと思うんですが。","respondent":"早津高齢福祉課長","answer":"限られたベッド数の中で適正に運用することに私ども努めておりまして、ご希望に必ずしもすぐにこたえられていないというのは確かに現実ではあります。何とか工夫する中でもってご要望に少しでもこたえられるようにしていきたいというふうに考えてあります。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところでの確保がかなり募集しても、応募がなかなかなくて大変だという、そういう実態というのは実際にあるんでしょうか。そして、なかなか対応できないという状況にあるのかどうか、ちょっと区としてつかんでいるところを説明を求めました。","respondent":"早津高齢福祉課長","answer":"学校の配食については、所管としては地域活動課のほうで担当しているものですから、私ども必ずしも状態がはっきりわかるわけではございません。ご要望があったということをお伝えさせていただきたいと思います。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わかりました。それともう一つお聞きしたいのは、去年の第４回定例会の中で、そのことが実際にいつごろになるのか教えてほしいと求めました。","respondent":"早津高齢福祉課長","answer":"来年早々というふうに当時お答え申し上げたんですが、予算等が公表できるのが２月の８日でしたか、プレス発表というようなことがあります。私どもはそれに前後して予定を考えてありますので、２月の中旬ぐらいかなというふうに考えてあります。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"わかりました。もっと増えるんじゃないかなというふうなうわさをちょっとお聞きしたんですが、そういう計画が区のほうであるのかどうか、説明を求めました。","respondent":"早津高齢福祉課長","answer":"今年度４カ所増設しまして１７になったんですけれども、来年度さらに２カ所を予定しています。要介護高齢者の増加等を背景としまして、あと２カ所増設の方向で検討しています。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"じゃあ、それの決まった段階で、はっきりとまた改めてこちらのほうにご報告いただけるということでよろしいんか尋ねました。","respondent":"早津高齢福祉課長","answer":"３月の厚生委員会でご報告することになろうかというふうに思います。","id":"exchange-063"}]},{"id":"topic-03","title":"行政視察の報告書","agenda":"行政視察の報告書","exchanges":[{"speaker":"伊藤委員","kind":"意見","question":"２７ページ、一番最後のページ。「だと思います」、それだけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"須藤委員","kind":"意見","question":"２０ページからの私の責任分担のところが数字の書き方が漢数字でこうなって、ほかのと合わせて算用数字にしていただくと。その辺お願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"須藤委員","kind":"質問","question":"縦だったから、それで書いたからそういう数字になったと思います。ですから、横にするなら算用数字で書いて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/534819?Template=document&Id=3008#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":50864,"voices":168}},{"id":"h14-20020122-5","meetingId":"h14-cm01","date":"2002年1月22日","dateIso":"2002-01-22","committee":"総務委員会","time":"午後１時０３分～午後４時１６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"裏面に数字があるけど、実際にどういう、要するに表立って見えてくるのかというところは何か考えがありますか。へその曲がったとらえ方もできるわけで、じゃあほんとうに具体的にこれがどういうふうに高まるのかというのは示せるものなんか尋ねました。","respondent":"西島経理課長","answer":"やっぱり６社、７社しか参加してこない場合と、そういうことで変わってくるのではなかろうか。このたびの適正化法の絡みでも、そういう意味では透明性とか客観性というのは高まってくるのではなかろうかというふうに判断しています。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"公募型に参加できる業者と、今度制限付き一般競争入札に参加をしていた業者の差があるんですか、登録する上で。もし登録を希望するなら、２年の登録があっても、今回はこういう制度の改正に伴って臨時的に受けますよというようなことはしなくてもいいんか尋ねました。","respondent":"西島経理課長","answer":"１４年度分の中間登録というのをしていますけども、そこまで登録については今のところ、こういう予定はございません。そこは基準を設けてありますので、今のところ、ここの基準は大きく変更する予定はございません。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"せっかく１４年度からこういう仕組みの中で仕事がとれる、あるいはとりたいという、そういう可能性が出てきたならば広げてあげてほしいなと思う。透明性とか客観性、両面持っていると思うので、ぜひその辺は検討していただきたいなというふうにお願いだけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"塚本委員","kind":"質問","question":"今の質問の続きみたいなことになると思いますけれども、年度中間にもあるということですが、認定に至る一番の要件というものは果たして何であるか。そして、近年の登録業者の推移ですか、どういう傾向にあるのか、傾向だけでもいいので、お尋ねします。","respondent":"西島経理課長","answer":"登録業者の推移ですけれども、ちょっと工事のほうでご説明申し上げますと、９、１０年度の登録が2,５１０社です。それから、１１、１２年度の数ですけれども、2,４３３社、１３、１４年度は2,１２６社ということで、若干減っているかなと考えています。","id":"exchange-004"},{"speaker":"塚本委員","kind":"意見","question":"下請けに入って何かやったときに実績という話になってくると思うんですが、そういうことで新規に登録しにくいという話が聞こえてこないわけではない。","respondent":"西島経理課長","answer":"ただ、発注側が安心をして発注できるという要素も無視できないと思いますので、その辺を加味しながら考えてまいりたいというふうに思ってあります。","id":"exchange-005"},{"speaker":"塚本委員","kind":"質問・要望","question":"こういう事態ですから、今そういう方向で考えているんだということで、わかりました。それで、ここに書いてある業者指名停止のことなんですけれども、指名停止に至る原因の主なるものを一つ、二つ教えていただきたい。","respondent":"西島経理課長","answer":"指名停止になるもので一番大きなものは、やっぱり談合に関するものが圧倒的に多いかなというふうに思います。本店が参加する、こういう形で参加をするということになりますと、当然品川区も指名停止基準に該当しますので処分するという形になります。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"談合は我々の一般市民の利益を損ねるものですから排除しなければいけないんですけれども、それも現実だろうと思います。そして、ペナルティーのことなんですけれども、これも大まかでいいですから、どういうことがペナルティーになるのか教えていただきたい。","respondent":"西島経理課長","answer":"指名停止というお話でしたので、まさに指名停止で、二月あるいは三月、登録している業者でも入札に参加できないという形になります。ただ、その６カ月の間に、また次の事件が起きてしまうとさらに加算されてというケースも現在進行しているところもあります。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"品川に特別付加しているものがあるのかどうかということ。それじゃあ、前の質問だけ。","respondent":"西島経理課長","answer":"指名停止基準ですけれども、これは区で独自に定めてあります。成績不良だとか、あるいは社会的信用を失墜した場合だとかということで、この場合は何カ月の指名停止だよということで指名停止基準を定めてあります。","id":"exchange-008"},{"speaker":"北野委員","kind":"質問・要望","question":"ちょっとわからないんですけれども、指名業者というのはわかるんですけど、申込業者数の中で５５９社というのがありますよね。どういう事業内容というか、指名につながらなかった業者なのかどうなのかというところを、申込業者数ということを教えていただきたい。","respondent":"西島経理課長","answer":"こちらで予定していた指名の業者数がほぼ合えば問題ないんですが、三百万円ぐらいの工事だとしますと、７社ぐらいの募集をかけます。７社プラス２社ぐらいしますので、９社は入札できますけど、残りの６社は参加できない。","id":"exchange-009"},{"speaker":"北野委員","kind":"質問・要望","question":"５番の「金抜き設計書については、これというのは、業者はどこでも書ける様式になっているんですか。それとも、これは品川区独自の書き方になっているんか尋ねました。","respondent":"西島経理課長","answer":"それで、こういう工事をして、こういうところにはこういう部品というんですかね、材料を使ってくださいというものです。それを業者の方に貸与して、業者の方がそれをもとに入札積算をする、そのもととなるものです。","id":"exchange-010"},{"speaker":"北野委員","kind":"質問","question":"これは、特別に指定する店で有償で今度買ってくださいというものですね。それは品川区内の場所として指定するというのは数カ所、品川区内にあるんか尋ねました。","respondent":"西島経理課長","answer":"ただ、実はこれを検討するに当たりまして、紙レベルはそろそろやめようじゃないかという話をちょっと私どもは検討いたしました。ＣＤとかで設計書は入るわけですから、順次様子を見ながら、そういう方向ではいきたいなというふうに考えているところです。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"意見","question":"今のちょっと続きなんですけど、設計図書の区が指定と、今２カ所ぐらいという話だったんですけど、どういう店なのか、基準といいますか、そこのところはどんなものなのかとの意見を述べました。","respondent":"西島経理課長","answer":"図面ですので、どこでもできるという性質のものではございません。区のほうから原稿を持ち込みまして、入札に参加する業者がそこでお買い求めいただくと、こういう形になろうかと思います。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"有償購入というのは、何か発注の額との関係で出てくるんですか、これはどういうふうに、有償というのは値段は幾らぐらいか尋ねました。","respondent":"西島経理課長","answer":"１枚今１００円もしませんし、できるだけ早くそちらに移行できれば、移行したいな。ただ、これは相手のあることですので、状況を見ながら判断してまいりたいというふうに考えてあります。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"今例えば目黒川の工事の件でおっしゃったんですが、今の有償というのは、工事の請け負う金額で決まってくるというんじゃなくて、今のお話だと、コピー代とか、いわゆる実費のところでの有償ということか尋ねました。","respondent":"西島経理課長","answer":"そのとおりでございまして、コピー原価をそちらでお支払いいただくです。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問","question":"質問あったんですけど、私まだちょっとよくわからないところなんですけども、一番の違いというのはどういうものなのか。こういうところが、制限付き一般競争入札のほうに移行できるのかどうなのか、そこのところはどうなんでしょう。","respondent":"西島経理課長","answer":"一般競争入札と指名競争入札、それから随意契約、せり売りと４種類が想定をされてあります。広げていく方向というものは考えられますけども、それを縮小していく方向、制限付きになったことで参加できなくなるというようなことはございません。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"逆の線というのは出てくるということはないんですか。大きなところがどんどん入ってくるという、これによって起きるということはないんですか、そういう心配というのは全くないんか尋ねました。","respondent":"西島経理課長","answer":"現在指名競争入札で実施しておりますけれども、この分については変更する、今のところは予定ございませんので。だんだんほかにも参加するというふうには考えてございませんので、その辺については一定程度配慮して進めてまいりたいというふうに考えております。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問","question":"今の配慮して進めていくというのは何か具体的な基準をつくっていこうということは考えているんか尋ねました。","respondent":"西島経理課長","answer":"公募型に応募してはねられたというんですかね、参加できなかった方が一般競争入札で今度は申し込めばどなたでもさっきの３条件をクリアしていれば参加できますよということですから、条件が広がったというふうにご理解いただいたほうがわかりやすいのではなかろうかと思います。","id":"exchange-017"},{"speaker":"土井副委員長","kind":"確認","question":"要するに、これはアンド条件ですから、少なくとも登録業者の中に何か区切りがどこかにあるんじゃないかということだろうと思うんですね。ということだというふうに理解をするんですが、それで正しいのかどうかということを確認しておきます。","respondent":"西島経理課長","answer":"２点ですけれども、一つは２番目の「本件工事の発注ごとに区が定めた資格を有する者」と、変更後も変更前もすぐに大きく変わるということはないです。","id":"exchange-018"},{"speaker":"土井副委員長","kind":"質問","question":"要するに、区の仕事はどう変わるんですか。ただ、制限付き一般競争入札という言葉の中身とどのように変わるのか。","respondent":"西島経理課長","answer":"端的に申し上げれば、応募されてきた方は皆さん入札に参加できるということになりますので、競争性は高まるというふうに考えております。","id":"exchange-019"},{"speaker":"土井副委員長","kind":"確認","question":"確認だけします。このランクにある人たちだったら、そこから工事をやっていただきますよと、こういう形になりますということでよろしいんですね。","respondent":"西島経理課長","answer":"そのとおりでございまして、区のほうの仕事が何か変わるということではございませんので、参加できる数が増えて、競争性が高まるというふうにご理解いただきたいと思います。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問","question":"清掃に係わる部分では、随意契約で、たしかこの新明和ってコンテナを買った会社ですよね。あれもたしか随意契約だったし、ここしかないんか尋ねました。","respondent":"西島経理課長","answer":"それから同様の施設が、杉並区と新宿西に大型のこういう施設があります。中身は新明和工業製ということで、特許を新明和工業がとっているということで、こうならざるを得ないかなというふうに思っております。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"もちろん妥当かどうかというか、適正かどうかというのを精査されたんだろうと思うんだけど、金額的にはそういうよそとの比較はされているんか尋ねました。","respondent":"西島経理課長","answer":"よそとの比較ですけれども、地方の設備の規模とか、いろんなことがあるので必ずしも比較できないというふうに思っております。こういう時代ですので、当然あちらのほうから数字が出てまいりますけども、これではできないのでということで契約をしています。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"それから、支出科目は出ているんだけど、財源はどこが当たるんですか。それ二つを聞かせてください。","respondent":"市岡企画財政課長、岡田施設課長","answer":"これは、財源は一般財源なんですが、全額財調で、しかもいかに最初の約束どおり実績を態容補正という形で、１対１で見るというものです。 あるいはその期間が非常にほかにも回せるということもありまして、清掃作業所とは細かい打合せをしながら一応やっていくと、こういうことです。","id":"exchange-023"},{"speaker":"林（宏）委員","kind":"質問","question":"財調で見ているということなんで、このたぐいの作業所というのは、２３区の中で幾つあるんですか。それで、今課長がお話しされたよそへも回せるということですが、いわゆる粗大ごみを要するに回す場所というのはどこか確保されているんか尋ねました。","respondent":"西島経理課長","answer":"説明書には２３区というふうに書いてありますが、先ほど言いましたように杉並区とか新宿区のほうに回すということが一応想定はされているです。","id":"exchange-024"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、それぞれの区で同じ財源確保ができているというふうに理解しておいていいんですか。いろいろお話しいただいてはあるんだけど、今言われた四つ五つあるように、同じというふうに理解しておいていいんか尋ねました。","respondent":"市岡企画財政課長","answer":"ちょっと財調のこの考え方をご説明申し上げますと、それまで従前は東京都がやっていたわけですから、基本部分は各区同じです。置かれている施設は２３区一様ではありませんで、どうしても実態を捕捉し切れなくなるということで、こういう仕組みに別建てにしております。","id":"exchange-025"},{"speaker":"土井副委員長","kind":"意見","question":"それからもう１点は、別途会社があって、そういうものをやっているという状況があるのかどうなのか。そして、それとの関連はどうなのかとの意見を述べました。","respondent":"岡田施設課長","answer":"２番目の質問のとおり、メンテ契約をやはり行っておりまして、メンテもここの新明和工業以外にはできないというのが現実問題です。その老朽化ぐあいの報告を受けて、それに基づいて徹底的に対処する、このような感じになりますので、数年ごとにこれを行うです。","id":"exchange-026"},{"speaker":"土井副委員長","kind":"質問","question":"ということは、計量部分については少なくとも２年ごとに一定の点検あるいは検査を受けなきゃならないと。日常的にいろいろやっていながら、それでそれを受けてこういう定期補修とかに合わせてドッと工事をすると、こういう考え方でよろしいか尋ねました。","respondent":"岡田施設課長、本多委員長、南副収入役","answer":"この辺のゴムは劣化が結構あります。そういうことです。質疑を打ち切ります。７、区の出捐団体等への考え方ですが、各団体の具体的なペイオフの対応策は本報告書にまとめたものに準じたことになろうかと思いますが。","id":"exchange-027"},{"speaker":"塚本委員","kind":"質問","question":"一種の危機管理ですから、そういうやり方をしてきたのかなというふうに思うのですが、どうなんですか。つまり金融の専門家、最悪の危機管理の専門家というような、講師あるいはテキストが集められているのかどうかということをちょっと確かめたい。","respondent":"南副収入役","answer":"私は１１月からの参加ですが、このペイオフ対策検討会は、収入役を委員長にして、区の内部の職員で構成をして、外部から講師等を招いてということではなく、関係課長を含めて、必要に応じてオブザーバーも参加し、テーマに合わせて検討してまいったところです。","id":"exchange-028"},{"speaker":"塚本委員","kind":"質問","question":"だんだんちょっとわびしい気がしてきましたけれども。３ページの金融機関調査会、要するにこの二つと同じようなレベルでつくるという考え方のようですが、そういうことでいいんか尋ねました。","respondent":"南副収入役","answer":"その後作業を進めさせていただきまして、金融機関調査会の要綱で設置いたしましたが、それに私どもの区の中からは収入役と企画部長というメンバー構成で考えております。","id":"exchange-029"},{"speaker":"塚本委員","kind":"質問","question":"金融の情勢というのはそんなに変わらないわけですから、信用金庫などを調べようというなら、そういう話はできると思う。それから今言ったように、品川区レベルでそういうことを持つことの実効性といいますか、それをちょっと答えてほしい。","respondent":"中尾根企画部長","answer":"国とそういうことで今後の金融機関、金融情勢の動きの中でしていくという前提のもとで動かざるを得ないということ。やはり国が何を考え、こう考えた結果でございまして、一方でできるものを自分たちなりにやろうとした姿だというふうにご理解いただければと思います。","id":"exchange-030"},{"speaker":"塚本委員","kind":"質問","question":"今そういう心配があるということを知っています。やっぱり公金ですから、そういうことは調べてあったのかないのか、今わかりますか。","respondent":"南副収入役","answer":"ちょっと外国のペイオフ制度についての調査というのは不十分なところ……。","id":"exchange-031"},{"speaker":"塚本委員","kind":"質問","question":"元本が保証されたって間違いなく連座しているわけですから、途中で売り買いしようと思ったって、値段が変わっているわけですからね。国債というものは何なのかということを理解なさっているかどうかお尋ねしたいと思います。","respondent":"南副収入役","answer":"利息が１年に１回ずつ確実に入ってくることと、どの程度の長さの国債を買っていくのかといったような判断も含めて的確にしていく必要があるだろうと考えていますけれど、国債に対する信頼性を持ってこのような判断をすることになったわけです。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問","question":"経済情勢、これはお金をどう安全性を確保するかという話ですから、非常に危険だというのは明らかですね。今の話に対してはどうか尋ねました。","respondent":"市岡企画財政課長","answer":"要するに、各自治体それぞれ自分で考えろというふうに突き放されたわけですね。中期的な経済情勢を考えると、我がスタッフはありませんので、こういう報告書を基礎にさらに次の方策に進んでいきたいと考えております。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"産業の力関係だけで国がやっているわけじゃないですから、そういうことを考えると、国の信用力というのは非常に衰えてきた。それが円が安くなったという調査ですから、それが主要ですからね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"林（宏）委員","kind":"質問","question":"この報告書はだれがどこに出す報告書なんか尋ねました。","respondent":"南副収入役","answer":"これはペイオフ対策検討会での報告書でございまして、ある種プロジェクトチーム的に検討してまいりましたので、その中での決定をいたしまして、その後……。","id":"exchange-035"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、この報告書に基づいて、区長と助役が公金の扱い方を考えていくというふうに考えていいんですか。公金運用の責任は収入役じゃないんか尋ねました。","respondent":"中尾根企画部長","answer":"地方自治法上で公金の日常の管理責任は収入役にありますが、予算編成、ないしは全体の関係から区長にも一定の責任があります。どうこういうことで対応していけばいいのか、乗り切ればいいのかということを検討した結果を自分たちでまとめ、こういう経過です。","id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問","question":"この報告書が庁内で言うと専門、それぞれ専門に近い人たちがやったと。区長は、これを受けて、よしとされて、この方針で１４年度からスタートする、そういうふうにこの報告書を理解していいんか尋ねました。","respondent":"中尾根企画部長","answer":"報告は申し上げましたけれども、これに基づいてどのようにしていくか、新しい平成１４年度についての、まだ指示は具体的に受けとめておりませんし、それから具体的にはこの意見交換を、報告を聞いていただいたという段階ですので、今後の問題だと思います。","id":"exchange-037"},{"speaker":"林（宏）委員","kind":"意見","question":"そういうような会と、この調査会はどういう形で違うところがあるのか、同じような形になるのか。そういうものはどういうふうに与えていくのか、その辺、この調査会についての考え方を聞かせてくださいとの意見を述べました。","respondent":"南副収入役","answer":"過去２回実施いたしましたが、現在実施中でございまして、昨年の１２月に各金融機関、区内に預託している金融機関に調査をしています。したがいまして、金融機関調査会が報告書を提出するというような形の運営ということは今のところ考えておりません。","id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、この２ページの(1)の一番下のほうに「幅広い視点から金融機関の経営状況を把握していく」と書いてあるんだけど、個々の金融機関の把握はしないんか尋ねました。","respondent":"南副収入役、市岡企画財政課長","answer":"私ども正直申し上げまして、職員のレベルでは貸借対照表を読み切れないとか、いろんな問題点があります。それぞれその道のご専門家の方たちの経験豊かなところでのご判断等を含めて… この調査会は、区としていろいろこれからの金融機関の選択等の判断をするときの基本的な情報を専門家の立場からご提供いただくと、そういう場です。","id":"exchange-039"},{"speaker":"林（宏）委員","kind":"質問","question":"ですから、きちんとここは危ないという言い方はどうかわからないけど、区の方は。だから、この調査会というのはどういうものですかと聞いたわけ。","respondent":"南副収入役","answer":"説明不足でございまして、金融機関調査会につきましては、要綱で設置をしてまいります。それから、２月の初めに第１回目を開催していこうということで、そこである程度の分析をしていただくということになってまいります。","id":"exchange-040"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"４月１日からペイオフが実施されるという話をしていて、それに対応して早目に準備をしますから２月にやりますという報告がなぜできないんですか。あれは、相殺の対象にならないわけで、じゃあ区債じゃなくて、借入金にするというのは、法的に自治体としてはできないのか尋ねました。","respondent":"市岡企画財政課長","answer":"これは銀行から借り入れるんですが、このときに、いわゆる証書貸付という１対１でやる。そういう意味では、いろんな条件の中から一番有利なものを選ぶと、今のところこういう起債の形をとるのが一番有利だと思います。","id":"exchange-041"},{"speaker":"林（宏）委員","kind":"意見","question":"あるいは３０年債というそういう債じゃなくて、借入金として２０年というのはできるわけですよね、形としてはね。その相当がどのぐらいかをちょっと、今日じゃなくてよいですが、わかれば今日……との意見を述べました。","respondent":"市岡企画財政課長","answer":"２０年の長期でほんとうにお金を貸すかどうかというのは、２０年後の特別区がどうなっているかとか、これは何とも市場が決めることだろうと思います。区長に聞いた話では、昔、品川区が財政危機のときには、実際に市中銀行からはお金を借りられなかったそうです。","id":"exchange-042"},{"speaker":"林（宏）委員","kind":"質問","question":"まだ、申し込んだというだけだから、どういうことをやるというのが決まったわけじゃないんで、その情報が出てきたら、出てきた段階で教えてください。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから、国との関係というんでしょうか、それはどうとらえていらっしゃるのかというのをお伺いしたい。現状では財政で1,１２４億円の基金５００億円ですか、今後どうしようかということで対策を練られている中で、増える仕組みだと思うんですね。","respondent":"市岡企画財政課長","answer":"そういうことで正確な情報は鼻から私どもはあてにしていないで、だからこそ、自分で情報を整理するしかないと考えています。全体から見ると、これを相殺の材料として使うというのは、あくまで補充的な手法だろうというふうに考えております。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"モフタンといって、それはぜひさまざま幅広く正確な情報を入手いただいて、的確なご判断をしてほしいと求めました。要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"土井副委員長","kind":"質問・要望","question":"したがって、そこら辺はどういう考え方と、どういう人選の方法をとられたのかということをちょっとお聞かせをいただきたいということが一つです。ということを一つ伺っておかないと、少ないときは借金しているんですから、借り入れているんですからないんだろうと思うけども。","respondent":"南副収入役、市岡企画財政課長","answer":"それから、弁護士の方は品川区の区民相談室でずっと区民相談等をやっていただいている長年の経験のある方をお願いしたところです。できるだけ的確なご判断をいただいて… これは５億円ぐらいあるんですが、それらを入れると１日のピークの金額というのはおそらく５０億円、６０億円の規模だろうと思います。","id":"exchange-046"},{"speaker":"土井副委員長","kind":"質問","question":"結局そこの方々から頭の中に入っているものをいろいろ伺って、そこら辺、よろしくお願い──そう言うより仕方がないんで──と思います。それだけのものが動いているというふうには理解できました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、一時借入金は基本的には預けているものに見合った額を借り入れているということになるんですか。そこのところは、ちょっとどういうふうなことをやっているのかというのがわからないんですけど。","respondent":"中尾根企画部長","answer":"そこで、ここにちょっと書いてあるのは、そういうことで、やたらに一時借入金をして、ペイオフ対応のそういう道具にするというわけではありません。もちろん実際に借りるときには、現実的に意味合いにはなるという話ではございませんので、そういう仕組みになっております。","id":"exchange-048"},{"speaker":"宮崎委員","kind":"意見","question":"こういった部分、基本的にはこういうことを考えているとか、そういうところというのは何かありますか。事態が発生した時点ということで、ここのところでは「適切な対応を迅速に」と書いてありますけど、その基本的な考え方はとの意見を述べました。","respondent":"南副収入役","answer":"この危機管理対応策につきましても、これから作成してまいりますけれど、資金管理運用方針のために盛り込んでいこうというふうに考えております。","id":"exchange-049"},{"speaker":"宮崎委員","kind":"質問","question":"じゃあちょっと最後に１点なんですけども、先ほど大阪の知事さんの話もあったんですけど、全国的にはどんな感じの動きになっていのか。自治体のほうからのどんなふうな対応か、大阪の知事さんの動きというのはどうなっているのか、そこら辺のところはどんな感じか尋ねました。","respondent":"南副収入役","answer":"ただ、私ども２３区の副収入役会というような中では、ここまで来ても何か働きかけができることはないかというようなことを検討したりはしております。","id":"exchange-050"},{"speaker":"土井副委員長","kind":"質問","question":"４ページの金融機関に対する一定のガイドラインという部分ですけれども、世間一般で言われているガイドライン的な意味なのかということですね。したがって、これはどういう形のガイドラインなんか尋ねました。","respondent":"南副収入役","answer":"国債業務を営む銀行では自己資本比率８％以上、その他については４％以上とか、さまざまな指標で見ていきなさいというふうに言われております。こういった考え方というのは、金融庁等が示している考え方ですので、品川区独自にということではないです。","id":"exchange-051"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、磁気を使った記録がされたものを、電子計算機が読み取ることができるんですか。だから、国語というか、言葉の問題なんだけど、電磁的というのは、コンピュータという意味じゃないんか尋ねました。","respondent":"木下選挙管理委員会事務局長","answer":"２３区でもいろいろ検討いたしましたが、聞いてみますと、その効果はあまりない。そういう電子的方式か磁気的方式で記録をして、こういうものを供えなさいというのが法律に書いてありまして、そういう新しい定義がされたです。","id":"exchange-052"},{"speaker":"田中委員","kind":"意見","question":"聞き漏らしたかもしれないんですが、どこかの自治体ではこれを検討したところ、費用的に相当高額になるために導入を断念したということを聞いたことがあるんですが、仮に品川区でこれを導入するとしたならば、トータルでどれぐらいの費用がかかるものなのかとの意見を述べました。","respondent":"木下選挙管理委員会事務局長","answer":"まだ使えるレベルのものは１社しかありませんで、まだしかも実際に取り引きされていませんから、価格があってないようなものです。やはり、経費の問題で、今お話があったのは高知市が新聞で報道されておりましたけども、今回は断念をするということは報道されたです。","id":"exchange-053"},{"speaker":"土井副委員長","kind":"質問","question":"結論的な言い方なのかどうかわかりませんけれども、要するにほかの銀行、そこら辺はどのような考え方をしたらよろしいのかということですよね。これを機に、富士銀行じゃないんだから、別だっていいんじゃないのいうのはどう考えたらよろいんか尋ねました。","respondent":"南副収入役","answer":"私ども先ほどペイオフ対策検討会のご報告の中で、他の金融機関につきましては、今後検討したいというような考え方を示しているところがほとんどです。","id":"exchange-054"},{"speaker":"土井副委員長","kind":"質問・要望","question":"なかなか検討ができないんじゃなかろうかなという気もしたものですから、ちょっとお伺いをしたんで、どこまでいったかなというのをお伺いしたんで。そうすることによって、またみずほさんもレベルアップを図るんでしょうから、ぜひそういう形で進めていただきたいというところにとどめておきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"林（宏）委員","kind":"質問","question":"それから、東京都という中で東京都が富士銀行で２３区も富士銀行というつながりというのかな、そういうことで富士銀行がずっとしてきた。そういう、いわゆる都と区の連携というか、しなきゃいけない理由があるんか尋ねました。","respondent":"南副収入役","answer":"地方自治法の規定ですが、実際に指定をしないと、日常の業務が行っていけないというのが実情だろうというふうに思っております。２３区は富士銀行で来ておりますけれど、大正４年ごろからの話にさかのぼってまいりまして、そのときに指定をして以来ずっとという状況です。","id":"exchange-056"},{"speaker":"林（宏）委員","kind":"質問","question":"指定銀行はどこがいいですか、便利ですかって。さっきも副委員長が言われたように、みずほ銀行にしなきゃいけない理由が出てくることが、この書き方だとみずほ銀行になるよという書き方にとれる。","respondent":"中尾根企画部長","answer":"私どももそのころからそういう問題についてはずっと検討してきたんですけども、品川区だけが一つ脱却できないという問題がありました。先ほど言いましたようなことでやっていきたい、これが今の考え方です。","id":"exchange-057"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"選択ということになるわけですから、それはしっかりとしていただいて、きちんと決めていただきたいというふうに思います。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"土井副委員長","kind":"意見","question":"手数料の問題なのか、いろいろあるかもしれませんけども、そういう便宜があったのかなかったのかということと。それから、あったとしたら承継されるのかどうかということの意見を述べました。","respondent":"南副収入役、中尾根企画部長","answer":"ただ、１件２円とか、長い目で見れば決して損はしないけれどというような状況であるというような感じではないかというふうに思っております。ですから、地方自治体の指定金融機関であるがゆえの何らかの便宜的… そういった資金を確実に、しかもそういう集めた、普通は利息をとられるんですけど、何十億円を７日間寝かせているということは。それから、そのように思っておりますが、過去ではそういうことがございました。","id":"exchange-059"},{"speaker":"宮崎委員","kind":"質問","question":"何かいろいろ変わってくるのかななんて思うんですけど、そういう区の業務に対しての影響といいますか、これはどんなものが出てくるのか。これは区民の方の手間というか、影響というのはどんなのが出てくるんですか、そこら辺はどうでしょう。","respondent":"南副収入役","answer":"富士銀行の業務はそっくりみずほ銀行に行きますので、富士銀行の通帳、キャッシュカードですべて決済ができますというお話でした。もし、そのままでよろしければ、そのままでももちろん使えますというようなことをおっしゃっておりました。","id":"exchange-060"},{"speaker":"宮崎委員","kind":"質問","question":"この業務の効果は、例えば振り込み用紙に関して何かそういうものを変えたりとか、そういうものといのは変更があるんか尋ねました。","respondent":"南副収入役","answer":"富士銀行はなくなりますので、富士銀行行きの口座振込依頼書は機能しなくなりますので、それはみずほ銀行あてのものにつくりかえなければならない。","id":"exchange-061"},{"speaker":"宮崎委員","kind":"意見","question":"負担がね、ちょっと納得がいかないところなんですけど、いろいろまた出てきたところで対応をお願いしたい。終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201900?Template=document&Id=1570#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":54944,"voices":158}},{"id":"h14-20020123-13","meetingId":"h14-cm01","date":"2002年1月23日","dateIso":"2002-01-23","committee":"清掃・リサイクル特別委員会","time":"午後１時１４分～午後４時１０分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"４番目の大井町店と旗の台店の関係で、大井町店では大型家具、こっちはこれだということがわかるように記入をしていただきたい。１種類しか見ていませんと、どうせ刷り直しになりますでしょうから、よろしくお願いしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"了解いたします。","id":"exchange-001"},{"speaker":"船波副委員長","kind":"質問","question":"家具などを出品したいときは、大井町店のほうに申し込めば、同じ期間に同一人物が両方のお店に出せるということですよね。今現在は、予約はどちらの登録書でもできるため同一人の二重予約が可能となっているというのと、どう違うんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"説明が不十分だったかと思います。もう１枚、今のところ排斥できないものですから、同じ方が続けて受け付けることができるわけです。","id":"exchange-002"},{"speaker":"船波副委員長","kind":"質問","question":"それは、この受託件数の販売件数の差ということで、１０％足らずということで、それ以外の９割ぐらいは売れるということなんですか。売りたい人のウエイティング期間が伸びるということだけが問題で、そのために今回、こういう措置をするということなわけか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"販売できる件数についてもう少し工夫できないかと、現場の店長、店員のほうとも協議しながら工夫しております。約９割以上は売れるということで、売れ残ってしまうものが出てきますけれども、それはこういうふうに１割以下の件数です。","id":"exchange-003"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"それを一緒にしろとは言わないんですけど、例えば、大井町店のほうで名寄せ管理はしていらっしゃるんですか。１カ月後にさらに同じ名前で申し込んじゃっても、その辺の管理はされているのかどうか、それだけ。","respondent":"中山清掃リサイクル課長","answer":"各店舗においては、そういった台帳上の管理はしてございません。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"ですから、長期化しているということが、どういうところに原因があると区のほうは見ているのか。ちょっとその辺、改めて伺いたいと思います。","respondent":"中山清掃リサイクル課長","answer":"あるいは、実は家族もそうですし、もっと言えば友人の方のカードを使用されて販売されている方もいらっしゃるやに報告をいただいております。複合的な要因の中で、結果として、延びてきてしまったと考えております。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"どこで線を引くかというのが、まずあると思うんです。その辺の考え方を伺ってみたいと思います。","respondent":"中山清掃リサイクル課長","answer":"少なくともそういうことはないという認識はあります、結果として、特定の方が同じ店舗に繰り返しという形になってしまうわけです。そういった意味で基本に戻るというか、適正化を図りたいということになりますので、ご理解いただきたいと思います。","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"ですから、本来の趣旨にきちんともう１回シフトをしていくというところは大事なことですから、やるべきことなのかなという理解はするわけです。現実的に切り替えがどういう効果をもたらすか、区民の方々に趣旨をしっかり伝えていきながら、改めてお願いしておきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"了解いたしました。間口を広げて、リサイクルを進めるという趣旨を進めていきたいと思いますので、今のご意見を踏まえての改善に取り組みたいと思います。","id":"exchange-007"},{"speaker":"林（和）委員","kind":"質問","question":"期間の短縮ということですけれども、先ほどから話を聞いて、登録して一般の方々がどのくらいの期間待機しているのか。それで、さっき言われたように、どのくらいの待機時間があるのかということを、ちょっと説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"長期化というところで、時期によって動きはありますけれども、約半年近くになっております。現状で、６カ月弱とお考えいただければ結構です。","id":"exchange-008"},{"speaker":"堺委員","kind":"質問・要望","question":"確認で教えていただきたい。登録した人が、そしてその品物の展示期間が４週間あるようですけれども、店頭に並ぶまで待っている期間が半年間という意味なんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"実際には、いきなり品物を持って来られても対応できませんので、「電話予約が必要です」と、この資料もお書きしておりますが、電話をいただきます。","id":"exchange-009"},{"speaker":"堺委員","kind":"質問","question":"今度からは有効期限が５年ですから、仮に登録者数が全員が更新する、けれども、随時、登録は受け付けていただけるんですよね。当然、品物も増えてくるということは、余計にどんどん予約から委託販売までの期間が長期化することにはならないんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"基本的なご説明が欠けていたかとも思いますけど、既存のカードを一たん全部回収して、新たな番号でやり直すという形をとらせていただきます。それは別です。","id":"exchange-010"},{"speaker":"堺委員","kind":"意見","question":"例えば旗の台店については１万人、大井町店についても５,０００人とか、随時受け付けていきますという考え方は生きているわけですね。その辺をちょっとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"ただし、そういった受託のことも毎日やっておりますし、あるいは、店舗に来られて、書類が整っている方の受け付けは毎日行います。特に定員を定めることも、当然ございません。","id":"exchange-011"},{"speaker":"堺委員","kind":"質問","question":"やっぱり事業の趣旨に反しているわけですから、登録させないというか、そういう事前の防止策はあるんですか。事前に何らかの形でそうさせないような対策というんですか、これは何か見分ける方法があるんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"当然、どなたも権利があるわけですから、それに順化していただきたい。一定期間でそれをまた新規でやり直すという中で、そういった方は排斥と申しますか、適正な利用にとどめていただくようにするという趣旨です。","id":"exchange-012"},{"speaker":"南委員","kind":"確認","question":"新聞発表もされたということなんですけれども、対策について周知、公募は各区でやっていくのかどうか、その確認。それから、そういうときに、品川区としてはどういう対応を考えられているのか、その辺をちょっと伺いたいと思います。","respondent":"中山清掃リサイクル課長","answer":"資料の表面の４番に、版下が２３区で使えるということになって、２月に２３区でポスターおよびリーフレットの配布はやっていくとなっております。基本的に、各区の施策については各区でやって、区民の方にうったえていくべきものと考えております。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、容器がちゃんと確保されているにもかかわらず散乱せざるを得ない状況というのはあるわけです。そのあたりのことを、ちょっとお願いします。","respondent":"中山清掃リサイクル課長","answer":"出されたごみに対するネット等の守りのことも含めての対応というのは、優先順位をつけて、清掃事務所のほうも専用の体制を組んで回っております。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"一般論で４％程度ですよということじゃなくて、そこは要望にとどめますが、よくお願いしておきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ごみを散らかしたり、そういう被害というのは、やはりこの品川区の中でもかなりまだまだあるんじゃないかなと思ったんです。防鳥ネットや、全然対策がとられていないところが何カ所ぐらいあるかというのを、ちょっと教えていただきたいなと思います。","respondent":"中山清掃リサイクル課長","answer":"昨年度、折り畳み集積所ケースを区で独自に配布し、これは４０カ所程度なんです。もちろん広報なんかもやりながら、地域にあった周知、説明をあわせて効果を上げていきたいと考えています。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"対策をとると、行き場がなくて余計にどう猛になるというか、そうなるということがないかなと思ったんです。子どもなんかが襲われたりしたら怖いなと思いましたけれど、そこら辺のところは、どういうふうになるんか尋ねました。","respondent":"中山清掃リサイクル課長、金井環境課長、山口品川清掃事務所長","answer":"いろいろな会議の場で説明するんですけれど、役割がどうも明確に感じられないというのは、現実の行動の場面がなかなか少ないということがあります。… 行政が全部できませんので、基本的には区民の皆さんが、それぞれ地域ごとにやっていただきたい。そんなところで、ご理解いただきたいと思います。現在も、それは継続してやってあります。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"そういった面で、一つは、生ごみを減らしていく対策について、やっぱり積極的に取り組んでほしいと思うんですが、その点のお考え。そういう話し合う場があったらいいと思うんですけれども、その点について、どうお考えか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"今、以前からやっているコンポスト化容器の助成と、平成１２年度から電気式の生ごみ処理機の助成も開始いたしました。あるいは、どうしても袋で出す場合については、そういう地道なところから対応していただくことがまず一番だという考えでおります。","id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"お知らせをしてほしいと思うのと、行政のところでモデル事業を生かしたコンポスト化を追及するような研究を進めていっていただきたいなと思います。これは要望です、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"中島委員","kind":"質問","question":"質問が重複してしまうんですが、防鳥ネットがありますよね。あれはやはり地元の人が片づけておられるんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"針金、あるいはロープのようなものがあった場合については、そこにちょっと挟んでおく。作業後、通行に支障がないような場所にたたんで置くというところまでは、事務所の職員がやっております。","id":"exchange-020"},{"speaker":"中島委員","kind":"質問","question":"あそこに引っかかったら危ないなと思うような場面を見かけるところがあるんです。だから、そういった問題を含めて、折り畳み式の入れ物をこれからまだ増やす予定があると伺っているんですが、これからどのぐらい。","respondent":"中山清掃リサイクル課長","answer":"要望が非常に高まれば、そういったものも対応していきたいと考えています。支援の仕方、設置場所等を丁寧に説明しないと、今言ったようなペースでやっていきたいと考えております。","id":"exchange-021"},{"speaker":"中島委員","kind":"質問・要望","question":"ですから、１１月末で終わって以来、近所の人たちの実感なんです。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問・要望","question":"中島委員の質問に、「うちはいいです」みたいに言われちゃう、一番の理由がわかれば教えていただきたい。いろいろな陳情とかある場合でも、区の窓口というのは、カラスに関してはすべて清掃リサイクル課でよろしいんか尋ねました。","respondent":"中山清掃リサイクル課長、金井環境課長、山口品川清掃事務所長","answer":"１万カ所すべてに個別の対応というのは、どうしてもＰＲをして、それに対して出していくという形になっております。先ほど言ったように… あるいは襲われたというお話がありますと、一応、すぐに現地は確認します。納得するかしないかは別にして、それ以上のことは… そうでないような形を何とか、私どものほうも、皆さんでお話をいただいてご協力をということでお話を進めてはいるんです。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"推進しているところは、ネットはあまり断られることがないというお話で、ほんとうに安心しました。これは要望なんですけれども、ネットはこれだけ効果がありますよと、ぜひ勧めてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"北野委員","kind":"質問","question":"こういう形で調査を進めながら、防鳥ネットをよりよいものにしていこうとするために、これをしているんですか。ちょっとそのところの現状を、わかったところで構いませんので、伺いたいと思います。","respondent":"中山清掃リサイクル課長","answer":"折り畳み集積所ケースを設置する」、「カラスの模型を設置する」とか、これはというようなものはほとんど出てきておりません。例えば業者なんかが新たに作成する際に、それを生かすかもしれませんけれど、ここはあまり特別なことをやるとお考えいただかなくて結構だと思います。","id":"exchange-025"},{"speaker":"北野委員","kind":"質問","question":"そして、それは清掃事務所に行かなくてはいけないわけですよね。清掃リサイクル課のほうに置いていただいて、取りに行けるような身近な形にしていただけるということはどうなんか尋ねました。","respondent":"後藤荏原清掃事務所長","answer":"高齢者ということで、持ち運び等に相当苦労されるというお話がございましたら、清掃事務所のほうでお届けしているケースも幾つかあります。","id":"exchange-026"},{"speaker":"北野委員","kind":"意見","question":"わかりました。サービスとして、ぜひ、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"ただし、持ち運びはできない」とおっしゃる場合もありまして、こういった場合は、清掃事務所が車で配付するようなこともあります。この辺は、やれる範囲というのはありますけれども、柔軟にやっていきたいと考えています。","id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"場所は中延のほうだと言うんですが、商店街で、収集時間が午後３時ぐらいになるということで、収集時間が一定程度変更した部分があるのかどうか。収集時間が変更した部分が一部あるのかどうか、どういうふうに対応していただいているのかを、ちょっと伺いたいと思います。","respondent":"後藤荏原清掃事務所長、山口品川清掃事務所長","answer":"変更になっているのかどうかということなんですけれども、見直し等を行いましたので、そのときに変更しておる可能性はあります。変更につきましての周知については、３時の収集の場合には１２時という表示になりますが… 万が一そういうようなことがあれば、その日でもご一報いただければ、それなりの対応はします。私ども、すぐに調査をいたしますし、それなりの手立てはしたいと考えています。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと確認なんですが、１２時と看板に明示してあるところは３時だということですが、改めて確認なんです。そういうお話、説明をしていただいたのかどうか、ちょっとその辺の確認をしたいと思います。","respondent":"後藤荏原清掃事務所長","answer":"３種類ということでありますので、収集時間がおよそ３時ごろになる集積所につきましては、１２時という表示になります。１２時までにお出しくださいという表示になります。","id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"出される量とかもありますので、大幅におくれることはあり得るけれども、収集が３時ぐらいまでかかるという状況だととらえていいんでしょうか。日常的に３時ぐらいまで収集場所にごみがあるという話を伺っているので、ちょっとそのあたりは。","respondent":"後藤荏原清掃事務所長","answer":"ですから、３時ごろになるというところでしたら、おそらく６回目ぐらいであろうかと思います。３時前後という時間に収集の順番になっている集積所かと思います。","id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"では、もう少し場所の設定、あるいは状況も調査しまして、個別にお話を伺っていただきますので、その節はよろしくお願いします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"だから数字が若干変わるのはあり得ることですからあれなんですけど、どういうふうにとらえていいのかというのが、自分自身で不安になったんです。非常に大事な基本的なベースですから、あるいは減っていくととらえていくのか、基本的なスタンスをちょっとまず伺いたいなと思います。","respondent":"中山清掃リサイクル課長","answer":"２３区も、平成１２年度をもって、集積所による回収を進めたからどんどん落ちるということはなかなか難しいという面があります。今、２３区でオーソライズされているわけではないんですけれども、論議を進めていくための材料になる数値であるという認識ではあります。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"他区がもっと拡大していくように、双方が働きかけていくというんでしょうか、そういうことも必要かなと思います。ですから、具体的な調査、それから、信頼されるデータに基づく予測というのを、ほんとうにシビアに見ていく必要があるかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"土井委員","kind":"質問・要望","question":"五年で整備を一たんやろうとしているわけですから、ある意味では、信頼性が極めて乏しいわけです。その中で、品川区はどう主張していくのかというところが重要だと思うんで、ちょっとその辺についての思いなり、見解なりをお聞かせいただきたい。","respondent":"中山清掃リサイクル課長","answer":"いろいろな業者がいろいろな地域を回っているから、こういう地域処理の検討と最初から別枠だという論議はないだろうという主張を、既にしています。そこから始めなければいけないというのが、少なくとも、清掃リサイクル課の考えです。","id":"exchange-034"},{"speaker":"土井委員","kind":"質問","question":"やっぱりそこは、この話は進まないようですから、私はそういうふうに思っています。発電所の要素もあるわけですから、そういうものをどうするのかということを、こんなふうにも思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"中島委員","kind":"質問","question":"今、私たちはお知らせをいただいて、廃棄物減量推進委員の方には、研修をやる。それ以外の一般の区民の方には、どのように周知されているんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"さらに言えば、自分がたまたまご都合が悪くてご欠席でも、地域の方を２人は誘っていただきたいというお願いはしています。そのほか、ポスター、ＣＡＴＶ、インターネット、ホームページを含めて、私どもが持っているメディアについては、すべて広報を行ったです。","id":"exchange-036"},{"speaker":"中島委員","kind":"質問","question":"きゅりあんの８階の大ホールだけの基調講演なんでしょうか。それは次回の参考にと思うんで、予定はどうか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"説明がちょっと抜けたんですが、実際にこういうものが出されていますというのを展示して、ご希望の方には抽選で持って帰っていただくということです。","id":"exchange-037"},{"speaker":"中島委員","kind":"意見","question":"先ほども、カラス対策のところでちらって出ておりましたけれど、ほんとうにこうしたシンポジウム、いろいろな展示、区民の方たちにごみをいかに減らしていくかという知恵をアドバイスできるような催し物というのは、今後もぜひまたお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"北野委員","kind":"質問","question":"それから、問い合わせ先は品川区の清掃リサイクル課になっているんですけれども、主催はリサイクル課の主催ということなんでしょうか。その２点だけ。","respondent":"中山清掃リサイクル課長","answer":"区の主催事業ですので、所管、窓口は清掃リサイクル課ですので、私どもで実施する事業です。その反応も含めて、できるだけ継続をしていきたい、来年以降もやっていきたいとは考えております。","id":"exchange-039"},{"speaker":"北野委員","kind":"質問","question":"そういうお考えは、今のところないんでしょうか。今後のこととしても、ちょっとお伺いしたいんです。","respondent":"中山清掃リサイクル課長","answer":"今後の進め方については、より関心を持たれるようなやり方として、今、ご提案があったようなことも含めたやり方については、検討していきたいと思います。","id":"exchange-040"},{"speaker":"北野委員","kind":"質問・要望","question":"というのは、やはり、推進委員は公募の方もいらっしゃったわけで、いろいろ意欲を持っていらっしゃる方ですから、自主的に参加できるような機会もより多くつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"南委員","kind":"質問","question":"７時から８時の間、第２駐車場に、そこで乗り込んで収集活動に行くというスタイルをとりたいということなんですか。もうとっているということなんですね。","respondent":"中山清掃リサイクル課長","answer":"事務所から２６号線まで約１００ｍあるんでしょうか、ちょうどこの辺がマッチングするような形で、２６号線で乗り込んでいくということです。２６号線での待機の時間は短くなっているです。","id":"exchange-042"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"２３区の実績の中にも、今後、区としてはどういうふうに考えているのか。今の段階での検討状況を教えていただけないか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"明確な新年度契約は２月下旬ぐらいにならないと、各区の意向ということで認識しているということがありますので、また一定改善されると思います。したがって、今の１３台という割合については、４月以降、減ってくると認識しておる次第です。","id":"exchange-043"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"第３ブロックの中の雇上車両の数が足りないというのは、当然雇上の費用も、近ければ安くなるんじゃないかなと思うんです。今、近くても、遠くても、雇上の費用は変わらないんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"わかりやすく言えばハイヤー的に、基本があって、１日当たりの走行距離に応じて料金を加算するという仕組みになっております。いずれ、明確に清掃一部事務組合のありようと並行するような形になろうかと思うんですが、この契約を論議していくという形になろうかと考えています。","id":"exchange-044"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"最後に、ちょっと要望だけ。今、お話がありましたように、なるべく経費のかからないような形でやっていってほしいと求めましたので、それだけ要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"土井委員","kind":"提案","question":"清掃一部事務組合に係わる問題はまだしばらく続きまして、その方向性というのはなかなか難しいものですから、それが当然あるだろう。次回にお持ち寄りをいただいてやらないと、いかがなものかということで、ちょっと提案をさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"南委員","kind":"質問","question":"開くことは反対じゃなくて、必要なときに開催するというのは、原則の立場だと思うんですけれども、そのときに、私たちが調査、審査する内容というのは、今、土井委員がまとめておっしゃった部分を議題に供したいということで受けとめればいいわけか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"南委員","kind":"質問","question":"よろしいでしょうかという提起だから、いいとか、悪いとかと、できればみんなのいるところで決めたいということですよね。今、答えろと言われてもちょっと困っちゃうで、どうしたらいいんか尋ねました。","respondent":"高木委員長","answer":"なお、お困りだと思いますので、おおむねそういう……。","id":"exchange-048"},{"speaker":"南委員","kind":"確認","question":"だから、手帳を持ってきて、確認して、早く決めたいと思うんですけれども。〔「第１案、第２案ぐらいにして」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"南委員","kind":"確認","question":"もう１回、再確認ですけど、２月１５日に私たちが参加する思いというのは、当委員会の調査事項全般にわたってということでいいわけですよね。今、委員長がおっしゃったのは、そういうことでいいんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=5654#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":50873,"voices":133}},{"id":"h14-20020123-16","meetingId":"h14-cm01","date":"2002年1月23日","dateIso":"2002-01-23","committee":"街づくり特別委員会","time":"午後１時０８分～午後４時０１分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"三確認したいんですが、あれば、少し教えてほしいと求めました。組合の参加率と、そこら辺の数値的なところはどうなっているか、少し教えてほしいと求めました。","respondent":"南雲都市開発課長","answer":"変更がありまして、これから進めるということで、特にその後変わったということはございません。基本的には再開発に参加して権利床を取りたいというふうに考えておりますが、現状では全権利者に基本的に再開発の了解を得ております。","id":"exchange-001"},{"speaker":"上山委員","kind":"質問","question":"もう１点お伺いしたいんですけれども、前の決算特別委員会などでお尋ねしたときは、１００億円近いお金が権利者に投入されるというふうに伺いました。そこはどういうふうに、そこがよくわからないんですけれども、そこら辺はどうなんか尋ねました。","respondent":"南雲都市開発課長","answer":"さらに整備も行っていくということで、区の基本的な方針で掲げている方向に沿って、公共施設の整備も組合が行っていくです。この土地の高度利用を促進するということと、周辺の公共基盤を整備を行うということで、行政としてもいろいろな点で推進していくです。","id":"exchange-002"},{"speaker":"上山委員","kind":"質問・要望","question":"区民の要望でも、そんなに開発してくれ、してくれという要望はあまり多くはないんです。区営とか、そういう方向で考えるべきではないかと思うんですけれども、これは意見だけ表明します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"川西委員","kind":"質問","question":"歩行者専用道路、通路、これの説明をもう一回、さっき伺いましたけれども、よくわからなかった。歩行者の部分、もう一回お願いいたします。","respondent":"南雲都市開発課長","answer":"ＯＨＰで説明をさせていただきたいと思います。ここで環状６号線の陸橋がありますので、こちらに人工地盤がありますけれども、そこに上がって来るというような形になります。","id":"exchange-004"},{"speaker":"川西委員","kind":"質問・要望","question":"それから、御成橋に通じて開発をする第２地区へ、ソニー通りに通ずる道へ流れていくということですか。もう一つ、関連で、東五反田二丁目の分譲棟とか、賃貸の入居状況を把握していらっしゃったら教えてほしいと求めました。","respondent":"南雲都市開発課長","answer":"分譲住宅につきましては、あと１棟か２棟キャンセルが出たということがあるということですが、基本的には全部完売という状況になっております。若干出入りはあると思いますが、基本的には分譲、賃貸とも全住戸が入居しているという状況に聞いております。","id":"exchange-005"},{"speaker":"石田委員","kind":"質問","question":"ＪＲ側のことをちょっとお聞きしたいんですが、９ページに、これだけきれいになっている。そこに電車をこさせたりいろいろしているみたいですから、そういうのを含めたＪＲとの話というのはどこまでしていらっしゃるのか。","respondent":"南雲都市開発課長","answer":"この中で赤枠が方針区域ですが、陸橋より左上のほうにちょっと出っ張ったところがあると思います。下のほうに保線作業に入るという、この部分のＪＲの用地と付け替えを行って、ＪＲの作業の出入り口を確保しているです。","id":"exchange-006"},{"speaker":"石田委員","kind":"質問","question":"この用地を今の出入り口に持ってくるということなんでしょうけれども、これは都市計画のほかになっているから、ＪＲのほうで費用は全部出してくれるということでいいんか尋ねました。","respondent":"南雲都市開発課長","answer":"細かいところについては、今ＪＲのほうと協議を行っておりまして、まだ確定しておりません。基本的には組合が負担するということになると思います。","id":"exchange-007"},{"speaker":"石田委員","kind":"質問","question":"この境界のところは基本的に段差は残ったままになるのか尋ねました。","respondent":"南雲都市開発課長","answer":"線路の部分につきましては、今の段差は残るです。","id":"exchange-008"},{"speaker":"本田委員","kind":"確認","question":"それから、全体合計も１万7,０８８m2の後ろに０がついているけれども、１７万８８０m2でしょう。その確認をもう一度。","respondent":"南雲都市開発課長","answer":"合計につきましては１７万８８０m2ということで、０が一つ落ちております。訂正させていただきたいと思います。","id":"exchange-009"},{"speaker":"本田委員","kind":"質問","question":"今後の日程で、都市計画の決定が平成１４年７月となっていますが、区計審はいつの日程になっているんか尋ねました。","respondent":"南雲都市開発課長","answer":"平成１４年７月に都市計画の決定の告知を予定しておりますが、それまでのスケジュールとしましては、その後２月１９日に区計審が予定されております。その後３月と４月で都市計画法に基づきます縦覧の手続きを行いまして、７月に決定の告知という予定になってあります。","id":"exchange-010"},{"speaker":"本田委員","kind":"質問・要望","question":"そうであれば、１点だけお尋ねしておきたいんですが、報告がなかったものですから。ここの報告が今全然なかったんですけれども、どうなっているのかということをお聞かせほしいと求めました。","respondent":"南雲都市開発課長","answer":"それから、注水なども使いまして、水道、上水の利用を抑制する。それから、区域内につきましてはなるべく緑化を進めまして、環境にも配慮するということで、計画を進めているです。","id":"exchange-011"},{"speaker":"本田委員","kind":"質問","question":"それから、省エネ対策をやっていくとか、貯水量とか、先ほども公園の話も出ましたけれども、緑化を進めると。細々とした関係が区の詳細については、区の都市計画審議会のときに出てくるんか尋ねました。","respondent":"南雲都市開発課長","answer":"方向としては定期的にいろいろな機関と協議を進めていくということでございまして、できる限りの省エネルギーの対策を行っていくということで、現在も協議を進めているです。","id":"exchange-012"},{"speaker":"築舘委員","kind":"質問・要望","question":"目黒川沿いですから、特にそういうことをきちっとしておいたほうがいいかなと。そうしますと、どういうような教育、まちづくりの一環としての教育の施設のあり方みたいなものが分かれば教えてほしいと求めました。","respondent":"南雲都市開発課長","answer":"住宅の居住者の増ということですが、高齢者の方で郊外の１戸建てから移られるような方もおられるということですが、基本的には若い年齢層の方が多い。","id":"exchange-013"},{"speaker":"築舘委員","kind":"質問・要望","question":"教育施設は、そういう意味では若いお母さん方は特に関心もあるし、そういう点でしっかりと計画をしていただきたい。ですから、一家に３台ぐらいあるような状況ですから、そこはしっかりと今後のまちづくりに定めておいてもらいたいということを要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"横山委員","kind":"質問","question":"最高の高さ９９ｍ、それの新旧の差というものを教えてほしいのと、ちなみに品川区で一番高い建物はどれを想像したらいいのか。分かれば説明を求めました。","respondent":"南雲都市開発課長","answer":"現在都市公団が取得するという予定になっておりまして、その都市公団が低層部の利用法を、そういうニーズも含めて検討をしているです。（「区で一番高い建物は」と呼ぶ者あり）品川駅の東口で今工事をしておりますのが１００ｍを超える予定です。","id":"exchange-015"},{"speaker":"横山委員","kind":"意見","question":"こういった部分での対応というのを今から併せて考えていかなければいけないというか、そういったものが係わりがあると思うんです。急にそれだけの数の流れがあると窓口が狭くなるというか、そういった部分がありますので、配慮しながらやってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"藤田委員","kind":"質問","question":"もし災害があった場合に、線路と川でどん詰まりですから、五反田公園からこちらに入ってくる橋がありますね。山本橋の幅員と、山手線の狭い幅員はどれくらいあるんか尋ねました。","respondent":"南雲都市開発課長","answer":"山本橋の架け替えも行いまして、現在１２ｍ幅員の道路をつくっておりますので、五反田方面からのアクセスも十分に改善が図られるです。山手線の下のところも幅員が3.５ｍから４ｍ程度の通路があります。","id":"exchange-017"},{"speaker":"藤田委員","kind":"質問","question":"これは一番近道ですから。ここに一番近い住宅棟が左側にあるわけですから、どちらに買い物に行くかとなれば、やはり五反田に皆さんは行くと思うんです。","respondent":"南雲都市開発課長","answer":"歩行者の専用通路で川沿いにも遊歩道が整備されます。雰囲気はあまりよくありませんで、壁面の美化作用も含めまして、今後組合とも協議していきたいというふうに考えてあります。","id":"exchange-018"},{"speaker":"藤田委員","kind":"質問・要望","question":"緊急車両が通れるぐらいの道路の幅員を考えて、私は現地を見ていないから言うんですけれども、これはＪＲとの掛け合いになるんでしょうか。こういうように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"意見","question":"ペデストリアンウエーの件で、これはすでに大臣承認も受けたという報告があったかと思うんですけれども、その計画はどうなったか。今回入っていないので、そういうことを初めに聞きたいんですとの意見を述べました。","respondent":"南雲都市開発課長","answer":"過去の東五反田地区の方針計画の中では、それから、目黒川のところにも横断するのがいいと。過去の構想として幾つかルートが挙げられておりましたが、実際に今回整備されますのは、大崎駅からのルートです。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"質問","question":"今の組合は必要ないと考えていると。区のほうはどうか尋ねました。","respondent":"南雲都市開発課長","answer":"線路の西側にも現在大崎のような橋もありますので、ここの部分については規模といいますか、幅員としては歩行者の交通量を十分はかせるというシミュレーションの結果が出ております。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"それだと何か住宅のほうをウェートを置いた気持ちで考えているのかなと、ちょっと疑問なんですけれども、これはこれでちょっと疑問だと思います。そうすると、ここは将来的にもそういう橋とかはつくらないということで、この計画で決まりということか尋ねました。","respondent":"南雲都市開発課長","answer":"将来どうなるかははっきりしませんが、現状では第３地区に関係する道路などの整備ということでは、同じ場所を拡幅するということだけを想定しております。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"質問","question":"今回も４棟がオフィスになっているんですけれども、この辺のオフィスの需要の見通しはどういうふうに考えておられますか。東五反田二丁目第１地区は過去に大幅に変更している経過もあるので、その辺の見通しを改めて聞いておきたいと思います。","respondent":"南雲都市開発課長","answer":"オフィス棟がもう少し細長い棟が２棟だったんですけれども、それを１棟に変えまして、ワンフロアの面積が広い住宅に設計の変更を行っております。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"質問・要望","question":"どこの調査なのかというのを、分かったら、参考に教えてほしいと求めました。こっちは需要があるというふうに見込んでいるんか尋ねました。","respondent":"南雲都市開発課長","answer":"従来２棟だったものを、１棟にしたほうがより将来性が高くなるという結果から、設計を行ったです。変更をしてきているですが、立地としては東五反田地区については、他の地域に比べますと高い評価をされているというふうに聞いております。","id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問","question":"オーバルコートのときのオフィスの計画よりもこっちのほうが上なんだというものというのは、内容でどのぐらいの違いがあるんですか。オーバルコートのほうは、こっちのほうだったら十分売れるという、そういう何か違いがあるんですかということを聞いたんです。","respondent":"南雲都市開発課長","answer":"従来からイメージが示されておりますし、立地と規模という点では、オーバルコートについても今後も需要としても成り立つというふうに考えております。","id":"exchange-025"},{"speaker":"宮崎委員","kind":"意見","question":"補助金の名目というか、目的というか、それも併せてお願いしたいと思いますとの意見を述べました。","respondent":"南雲都市開発課長","answer":"一般の不特定多数の人が利用するような部分を整備する費用については補助金の対象にしようということで、基本的には一般の人にも関係する、施設の中でもこういう部分が補助対象になっているです。","id":"exchange-026"},{"speaker":"本間委員","kind":"質問・要望","question":"1,０００m2から2,０００m2規模になるくらいかもわかりませんけれども、働き、出入りするというふうな想定をなされているのか。もし試算等がありますれば、教えてほしいと求めました。","respondent":"南雲都市開発課長","answer":"それから、昼間人口ということで、将来このオフィスに勤める方が概ね3,２００人ぐらいを予定しております。来外者ですが、これについてはまだ詳しい数値は出ておりませんけれども、昼間人口の３倍程度が来外者として訪れて来るという想定をしております。","id":"exchange-027"},{"speaker":"本間委員","kind":"質問","question":"特に全体として配慮をしてほしいというお話も、自転車の問題とか、いろいろ出ておりました。大崎にも近い、一等地のところに業務棟なり住宅ができてくるわけですけれども、特に交通面に配慮したというような部分は何かおありか尋ねました。","respondent":"南雲都市開発課長","answer":"歩行者が駅ビルから第３地区に行くまでスムーズに安全に行き来できるということを考えまして、駅を降りたらペデストリアンデッキを延ばしていきます。","id":"exchange-028"},{"speaker":"本間委員","kind":"質問","question":"３２０戸ということでありますが、この部分ではおよそ考えられる部分で何通りぐらいの、どんなタイプの住居が予定されているのか。先ほど全部入居済みだという話もありましたけれども、単身者用の部分が含んでいるのかどうか、説明を求めました。","respondent":"南雲都市開発課長","answer":"今のところ都市公団の賃貸住宅を予定しておりますが、基本的にはファミリータイプということで、単身者向けについては考えていないということです。ただ、基本的にはファミリータイプということで、間取りとしては２ＬＤＫから３ＬＤＫの住宅を想定しているです。","id":"exchange-029"},{"speaker":"三上委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、認定住宅１６戸という言い方というのをもう少し詳しく説明していただけませんでしょうか。残りの１６戸というのは、地主を含めた、そういった人たちが自分の持ち分として取得するという考え方でいいんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"２つ欲しいとかといった場合がありますから、５０m2に満たないわけですから、認定住宅にならないです。ですから、あくまでも認定というのは公募できる数というふうになります。","id":"exchange-030"},{"speaker":"三上委員","kind":"質問","question":"もうちょっと突っ込むと、公募できるということは、すべてその１６戸についてというのは分譲するという考え方か尋ねました。","respondent":"浜脇住環境整備課長","answer":"今回の場合の予定では分譲する予定ででき上がるというふうになっております。その中で自分が好きなところを取っていただいて、例えばぶつかれば抽選とか、そういった形、それを公募というふうに言ってあります。","id":"exchange-031"},{"speaker":"三上委員","kind":"質問","question":"地権者数５名の中で、借地権者、借家人という方が入っているということか尋ねました。","respondent":"浜脇住環境整備課長","answer":"中に入っているテナントとか、借家の方、それがアパートだったらばアパートの方は権利者に入ってございません。４棟がありましたから、それぞれに住居があったり、事務所があったりして、借家人の方は９名ほどいらっしゃいました。","id":"exchange-032"},{"speaker":"三上委員","kind":"質問","question":"借家権者の人たちについての補償とかということは、事業者である水上さんがやるということでいいんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"１件だけ、それ以外の方は今のところ合意しておりますが、１件だけが違った方が残っているというふうになってあります。","id":"exchange-033"},{"speaker":"横山委員","kind":"確認","question":"平成１４年１月に建築確認ということですから、説明会の内容等を踏まえて、地域ではある程度の了解を得てここまできているのかなと思うんです。あまりにも差異があるので、そこら辺のところはどういう経過を把握していらっしゃるか、ちょっと説明を求めました。","respondent":"浜脇住環境整備課長","answer":"５棟の方々に対して、連絡を密にして説明を行った結果、それがご理解いただいたというふうになってあります。平成１３年１０月５日の説明会１回でございまして、若干近所で紛争があると聞きますけれども、これはうまくいっているというふうに思われます。","id":"exchange-034"},{"speaker":"川西委員","kind":"意見","question":"それと、１６戸を分譲すると、総事業費をほとんどクリアしてしまうというふうに見ると、品川区でこれは初めてですよね。そういうモデルになるのかどうかとの意見を述べました。","respondent":"浜脇住環境整備課長","answer":"都心共同住宅供給事業協議会の場合これまで変更した例はございません。中には、変更してもいいんじゃないかというふうに思われる物件もあるんですが、そこまでしなくてもいいということで、いまはそうなっております。","id":"exchange-035"},{"speaker":"三上委員","kind":"意見","question":"２６号線の通りに面しているだけに、何がゆえのものかということに終わってしまうということになりかねないんですね。どうしても自分の家の周りに止めた場合ということでは、３２台ということで許可されたということについて、どういうふうに感じていらっしゃいますかとの意見を述べました。","respondent":"浜脇住環境整備課長","answer":"駐輪場の台数ですが、これは開発指導上の最低限ということは事実です。実施計画とか、今回の場合は、こういう商業地の中で増やすということができなかったというのが実情です。","id":"exchange-036"},{"speaker":"三上委員","kind":"質問","question":"これは私、前から２６号線の通りについては言っていますけれども、むしろ多過ぎて問題になるということはあり得ないですよね。地域に合った住宅の提供ということについては、品川区の考え方がどこにどういうような考え方があるのか、このあたりどうなんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"４００m2ぐらいの敷地の中で、駐輪場を１階なりどこかにつくると、そういった意味では駐輪場の台数が少なかったというのが現実です。今後、場所に応じてやっていく必要があるでしょうけれども、私ども今の事業を進める中にも指導要綱を守るのが精いっぱいということです。","id":"exchange-037"},{"speaker":"三上委員","kind":"意見","question":"自分のところに来るお客様も含めて、歩道上に止める駐輪については、止めて結構ですよというふうにして開放してくれるならいいですよ。そういったお話もされていないんでしょうとの意見を述べました。","respondent":"浜脇住環境整備課長","answer":"店舗が２６号線沿いに顔を見せないと店舗としてのあれがなくなってしまいますので、奥のほうに駐輪場の数を確保した、３２台がそういうふうになったです。","id":"exchange-038"},{"speaker":"三上委員","kind":"意見","question":"そこらあたり全部２６号線通りセットバックしてくださいというような形で、こういうふうにいいものができますよと言ったって、何の意味もない。そういうような補助金の使い方だと、私はおかしいんじゃありませんかということを言っているだけですとの意見を述べました。","respondent":"浜脇住環境整備課長","answer":"これも実を言うと、これ以上１階に駐輪場をつくるというのは厳しい状況であると考えたものですから、これでよしというふうにしたわけでございません。一般の方が歩道上に１時間、この４００m2の中には今からしようとするのは難しいというふうに考えてあります。","id":"exchange-039"},{"speaker":"石田委員","kind":"質問・要望","question":"こういうビルの中でよくやったなと思うのが１点なんです。ここら辺は指導をされたのか、向こうが言ってきたのか、それだけちょっと教えてほしいと求めました。","respondent":"浜脇住環境整備課長","answer":"そういったことで、私どもはなるべく補助をするときは、まず屋上緑化を指導してみるというふうに考えまして、指導をしたものです。そういう区民や議会のご意見を生かしていただき、ありがたく思っているというのが、今の実情です。","id":"exchange-040"},{"speaker":"石田委員","kind":"質問・要望","question":"そこに対する維持管理、ランニングコストは必ずかかっていくわけですから、それについての方法論というのは今は多分ないと思うんです。そこら辺のことも含めて考えていただきたいというか、お考えがあれば、そこら辺の点についてお答えがあればお聞きしたいと思います。","respondent":"浜脇住環境整備課長","answer":"５年先、１０年先ぐらいのランニングコストで、そういう新しい対象事業にするようにということを要望を出していきたいというふうに考えてあります。","id":"exchange-041"},{"speaker":"石田委員","kind":"質問・要望","question":"今のお話はご努力ほしいと求めましたし、いろいろな物事の考え方はあるでしょうけれども、それをぜひ進めていただきたいということだけ要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"川西委員","kind":"提案","question":"せっかく委員長が提案してくださったんですけれども、次の委員会は２月１５日とおっしゃったとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"川西委員","kind":"質問","question":"そのこととか、進捗状況の中で問題点をある程度たたき台をつくっていただいて、我々が補足するというのはだめでしょうか。ですから、たたき台みたいなものをもうちょっと、スケジュール表だけつくっていただいても、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"石田委員","kind":"意見","question":"品川区ではどうにもできないもの、各会派の人たちがそれを提出してきたほうが、私はより良いものができてくるのではないかなと思います。都の問題だとか、おのずとそこから出てくるわけで、そういうまとめ方をしていったほうがいいのではないかなと思うんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"本田委員","kind":"質問","question":"今ある法律の中でどういう手法をとったらいいかとかという議論になるとまた別の問題なものですから、特別委員会をつくって１年間議論をしてきて。ですから、大きい会派の３人の正副委員長がいるわけですから、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"宮崎委員","kind":"提案","question":"今の委員長の提案でいいんじゃないかと思うんです。今の正副委員長の提案で私はいいんじゃないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"藤田委員","kind":"提案","question":"私は委員長提案でも結構ですし、また川西委員提案でもいいと思います。ですから、これまで検討してきた問題をまとめるという方向で、それは構わないと私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"本間委員","kind":"提案","question":"委員長の提案には従っていきます。取りまとめてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"三上委員","kind":"意見","question":"２月も日程に入っていません。そういう中にあって、急遽取りまとめをどうしようかという話が、あと確実に決まっているのは３月６日の委員会だけですよねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"三上委員","kind":"質問・要望","question":"どういうふうに持っていこうかということが、本来であれば１２月の時点できちっとそういうような方向性が考えられてくるのがいいんじゃないのか。この事業について進めていただきたいというふうに、どういうまとめ方をすると言っても、２回で果たしてまとめられるのかという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"横山委員","kind":"質問","question":"そこに絞ってやってきたわけですから、そこに対しての要請行動というか、そういった道を踏めばいいんだと思うんです。それをどうつづっていったらいいかということだと私は思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"本田委員","kind":"確認","question":"そういうことをお互いに確認しながら、委員会をやってきているわけですから、進んでいない。行政サイドでしっかりやってもらえばいいとも思いますけれども、こういう状態ですから、そういう決議みたいな形をとったらどうかなとも思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"藤田委員","kind":"質問","question":"ですから、幾ら小さい品川区が国・東京都に働きかけても、あまり効果がないんじゃないかと思うんです。ですから、品川区は品川区の事情があるわけですけれども、そんなに大きなあれがないんじゃないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"石田委員","kind":"質問","question":"ですから、まず第１稿というか、東京都へ出していこうとかというふうになっていくのではないのかなと私は思っています。１稿の中から、この１年間にどういう形の問題点があったのか、私はまとまるのも逆に早いんじゃないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"横山委員","kind":"質問","question":"ですから、これをやっていこうという、その部分が一番大切だと思うんです。それには品川区も犠牲を払って、いい意味での補助というか、何かそういったものがあってほしかったと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"本田委員","kind":"意見","question":"みんなに渡してもらって、もう一回２月１５日の委員会でまとめの方向をつくって、３月６日には方向が出くるでしょう。そういう協力はしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"石田委員","kind":"質問","question":"とりあえず２年４カ月の間にみんな蓋がかかっているし、夜間工事をやっているわけですから、本当に何もないんです。現状と変わっていないんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"山路副委員長","kind":"意見","question":"どの辺で、どう掘っているのか。その辺のことがわからないとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"川西委員","kind":"意見","question":"今日の大崎第３地区ですけれども、都市開発としては有効に、私は昔あそこの辺に勤めていたから思うんです。そういう点では、わざわざ行く機会がなければ、何かのときにあそこは見ておいたほうがいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"三上委員","kind":"質問","question":"ラフォーレの屋上から結構外が見られるような場所ってあるんですか。アンダーパスも含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/690912?Template=document&Id=6222#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":45710,"voices":151}},{"id":"h14-20020124-14","meetingId":"h14-cm01","date":"2002年1月24日","dateIso":"2002-01-24","committee":"行財政改革特別委員会","time":"午後１時１０分～午後３時３５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"提案","question":"モニター集会での意見といったときに、実績の５４％というのは提案ですね。しかし、内容的には重要な提案があって反映できたとか、そういう考え方もありますねとの意見を述べました。","respondent":"榎本行財政改革担当課長、市岡企画財政課長","answer":"やはりこの指標がなかなか今回事務事業を実施するにあたって、その進め方としてはかなり職員の意識改革という面では難しい面がございました。継続する事業、「今後の実施方向」の説明ということで、Ｄをつけるです。それから、コストをかけていいということは言っているわけではありませんで、過大な負担を住民に課すことがないように原則を定めているです。","id":"exchange-001"},{"speaker":"桜井委員","kind":"質問・要望","question":"そのときどきの関心事というのでしょうか、そのことも含めて公表するときの工夫というんですか、これは要望で結構です。こういうものの整合性というのはどういうふうに考えているんか尋ねました。","respondent":"市岡企画財政課長、榎本行財政改革担当課長","answer":"１点だけ、コストはかからなければかからないほどいいとは考えておりませんし、事務事業評価の基本的な考え方もそうではないと思います。行政サービスというのは、そういう意味では区民の負担ができるだけ少なくて… この評価については１３年度の評価結果として出したという評価の仕組みの中での結果だという形での出し方にならざるを得ないのかなと思います。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問","question":"しかもこれに載っている問題について、そういうふうにどんどん先行して進めていくというのは、区民の生活に係わる部分ですから非常に危惧します。直接係わる利用者に対して、どういうふうにその事業の評価なり、そしてまた区民サービスが拡充される部分も非常に福祉の面は大事ですから。","respondent":"榎本行財政改革担当課長","answer":"１１０番の高齢福祉課の紙おむつ支給助成のところで、今後の実施方向に「平成１３年度、対象者要件に要介護度を加える見直しを行った。評価したものと実際に実施にあたっては、きちんと議論を踏まえて実施していくというところは分けていく必要があると考えております。","id":"exchange-003"},{"speaker":"鶴委員","kind":"質問・要望","question":"公平性、上位項目の６項目に得点をつけたということで、大変な作業だということは事実だと思うんです。それに対するご意見というのはどういう形で集約していくのか、どういう手法で皆さんから意見を聴取していくのかという点を説明していただきたい。","respondent":"榎本行財政改革担当課長","answer":"最初につきましては、やはり１回企画財政課のほうで受けて、その内容を所管とある程度調整しながらやっていったほうが混乱がないかなと。","id":"exchange-004"},{"speaker":"鶴委員","kind":"質問","question":"区民に公表するということは、例えば広報「しながわ」で公表するという場合もあるじゃないですか、それで公表したんだというような場合もある。その冊子というのはカラーで、あるいはこういうモノクロでやるんですよ、どういうことになるのか。","respondent":"榎本行財政改革担当課長","answer":"は全体を見るにはどこにありますという形で、全事業を入れたインターネットでの掲載が一つと、パターンとしてはそういう形で考えております。あれの次の版という形で事務事業評価レポートみたいな形で、簡略的な冊子はお配りするような形で考えていきたいと考えています。","id":"exchange-005"},{"speaker":"鶴委員","kind":"質問","question":"ちなみに、２１２事業のうち、今回Ａ、Ｂ、Ｃ、Ｄで、Ａは幾つ、Ｂが幾つ、Ｃが幾つ、Ｄは幾つあるんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"それぞれ評価指標の最終評価の部分につきましては、Ａが２９、Ｂが１２４、Ｃが５０、Ｄが９あります。合わせて２１２です。","id":"exchange-006"},{"speaker":"鶴委員","kind":"質問","question":"Ｄの廃止と中止の意味はどう違うのか。何か特段な意味があって、廃止と中止というのは、こういう表現になっているんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"５ページのところで、大きく分けて廃止と中止の区別が今回の中でははっきりしていない部分もあります。それが本当に廃止になるのか、もう少し検討したほうがいいので、時系列的に並ぶような形での廃止・中止というような形で考えております。","id":"exchange-007"},{"speaker":"鶴委員","kind":"意見","question":"中止と廃止を説明していないから印象的によくわからないので、どう違うのだろうと最初から思っていたわけです。「ご意見のある方は品川区の企画財政課にお寄せください」と、こういうふうな親切さがあっていいのではないかというふうに思うんですとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"委員おっしゃるとおり意見の寄せ先は、電話番号、ＦＡＸ、インターネットのアドレス等をきちんと明記していきたいと思います。次の実施する段階で、どういうような表現がいいのかとかまだ議論の余地がありますけれども、その辺も含めて次年度の改善に努めていく必要があります。","id":"exchange-008"},{"speaker":"鶴委員","kind":"質問","question":"それにはどう答えるんですか。聞きっぱなしでどこかで集約するだけだと、こういうことになるのか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"それぞれある程度返事を出す形で、今も確かインターネットで来た場合につきましても、同じ対応を使わせていただきたいと考えております。見直しの方法もその要望を入れた上での検討をしていかなければいけなくなるのかなというふうに考えております。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問・要望","question":"これらは私たちにはっきり数字が出るものですから、平成１２年度コストというのが１億３,５５６万円、実績が１事業。これはミスプリというわけではないのでしょうが、このとらえ方を説明してほしいと求めました。","respondent":"榎本行財政改革担当課長、中尾根企画部長","answer":"何人参加したというのは、それが年間増えていくような形でのところを大きくとらえて指標として考えたという形です。１３を合わせると１３事業という形になりますので、全体で１ではなくて、１３地区で１３事業と形になります。この事業だけで１年間やっている係が５人いて、人件費掛ける５で、これが非常に実は難しいんです。","id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"これもまたインターネットのホームページですべてを見られるようにするということなんですけれども、意見の集約ということが一つあるんです。世論調査みたいな形でやるときもあるんですから、その辺の考え方、そういうことをする考えがあるかどうか。","respondent":"榎本行財政改革担当課長","answer":"世論調査につきましては、これ以外のいろいろ成果指標の部分で実績のデータを取らなければいけない指標も幾つかございまして、いろんな形での世論調査の活用というのは必要なのかなというふうに思っております。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、莫大な費用がかかるものですから、どういう形で意見を積極的に集約していくのかという方法論みたいなものは考えていますか。それとも、ただ「意見をお寄せください」だけでいいものだというふうに考えているんですか、その辺はどうか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"やはりある程度積極的にいろんな意見を寄せてもらいたいと考えていますけれども、やはり区政モニターですとかＥメールモニターですとかそういう形も活用して、いろんな意見を集約していきたいと思います。","id":"exchange-012"},{"speaker":"金高委員","kind":"意見","question":"この数字の１がどの辺のものを指すのか、あるいは５は一番上ですけれども、それの基準というのがあるのかどうか。それから、加点評価の加点する数字というものがどういう形を指しているのか、その辺のところをお知らせ願いたいと思いますとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"引き続き継続維持することが必要というのが４点、必要性の度合いを５ランクに分けて、それぞれ比率に応じた評点という形での説明をしております。","id":"exchange-013"},{"speaker":"金高委員","kind":"質問","question":"１回目の自己評価のほうは大体わかりますけれども、評価がＣなりＤになるという形になってくると、挑戦加点評価によって相当基準値が変わってくるというふうな見方でよろしいんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"自己評価につきましては今の６基準プラス挑戦加点評価の基準三つを総合的に判断してＡ、Ｃ、Ｄがついているという形です。Ｃ、その辺は実際に点数は足していませんけれども、中身を見てそれぞれの今後の評価に結びついているという形になります。","id":"exchange-014"},{"speaker":"辻副委員長","kind":"確認","question":"最初に確認しておきたいのは、これは去年だしたもので、この中にもメールあるいはファックスでやって下さいとありますが、行政評価レポートを出したときに実際にどれぐらい来ましたか。","respondent":"榎本行財政改革担当課長","answer":"実際にファクスで来たもの、それから区民の声で来たもの、メールで来たものというのがございました。数的には何件というのは困難ですけれども……。","id":"exchange-015"},{"speaker":"辻副委員長","kind":"質問","question":"それをどう生かしていくかということをどういうように考えているのか、ひとつお聞かせください。いやこれはこういう取り方をしたほうがいいのではないかという、この辺をどう次の形に結びつけていくか、その辺についてお聞きしたい。","respondent":"榎本行財政改革担当課長","answer":"やはりこの指標が今までの参加人数ですとか実績ですと、新たな成果というものの部分でどうとらえるかというのが難しくなる部分があります。やはり区民が見たときには、やはりその辺は少し精査した上で、わかりやすい形での指標のだし方をしていったらいいかと思います。","id":"exchange-016"},{"speaker":"辻副委員長","kind":"質問","question":"この事業指標でもう１回いくのか、あるいはどういう指標でいくのかということを、経年的にずっとやっていかなきゃいけない。あるいはボランティアでやってやるという見直しも十分あるわけですから、その辺は意見に近かったので、何かコメントがありましたらお願いします。","respondent":"榎本行財政改革担当課長","answer":"do、そこの部分は難しいんですけれども、継続的にデータを取っていくというのは続けていきたいというふうに考えております。意見の求め方についてどんな手法が取れるのかというのは、またこれからの検討課題にさせていただきたいと思います。","id":"exchange-017"},{"speaker":"桜井委員","kind":"質問・要望","question":"これは所管のところとまたあるかもしれないけれども、さっき言ったのをちょっと私の意見を加えておいてほしいと求めました。了承はちょっとできないと思います。","respondent":"市岡企画財政課長、塚本委員長、榎本行財政改革担当課長","answer":"紙おむつの支給が本当に必要な方に的確に届くような仕組みになっているかどうかということを、いろいろ検証する中であり方を考えようということです。… コストとは何かということの説明が１２ページの「注」に記してあるだけで、先ほど口頭で説明したほどの中身が書いていないということで。… 説明不足なところがございまして、コストの説明ですと、こういう形でやっていますという形での説明を今後出させていただきたいと思います。","id":"exchange-018"},{"speaker":"鶴委員","kind":"質問","question":"今ご説明があったようにただ単に要求するのみではなくて、ここをこう改善したからこの予算は認めてほしいというふうな、新しい予算書になるのか。そういうふうに一目瞭然として、前年度の予算に比べてどう改善が加わっているのかということがわかる予算書になるのか尋ねました。","respondent":"市岡企画財政課長","answer":"私の気持ちとしては、例えば予算書も事業部別に組んでみるということも考えてみたんですが、記述の中で工夫をしたいと思います。例えばいろいろ新規の施策の説明資料もご説明用につくっておりますが、こういう整理の仕方をした上でご提供申し上げたいなと思います。","id":"exchange-019"},{"speaker":"鶴委員","kind":"質問","question":"もう１点、４月から事業部制がスタートしたことによって、その点はどうか尋ねました。","respondent":"市岡企画財政課長","answer":"所管は要求をして歩留りを考えればいいというのに対して、積極的にアドバイスするという役割に変わってきたと思います。こういうような新しい動きがございましたので、ご報告申し上げます。","id":"exchange-020"},{"speaker":"桜井委員","kind":"質問","question":"その辺の調整機能というんですか、全区的に見てどうなのかと。だから、こういうところはどうなのかとか、逆に心配な部分を強調した嫌いがありますけれども説明を求めました。","respondent":"市岡企画財政課長","answer":"そのほうが変化に対応できるだろうというのがありましたが、事業部間でその間の調整をしたものを挙げていただくというふうにいたしました。","id":"exchange-021"},{"speaker":"桜井委員","kind":"意見","question":"だから、ある面では今の事業部のとらえ方というか、そこに大くくりの基本方針というのは成果というものもある。経常経費の部分をどう削減するかというふうに、文章には１０％シーリングとならないけれども、そういうことを申し上げておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"辻副委員長","kind":"質問","question":"まさしく、それがなければただ単に切れ切れという話になってしまうわけですから、これを切るという工夫をして編み出したものがこう生まれたかという。それは企画財政のほうが専門的に考えてどうだろうかとなったわけですけれども、今回の予算編成の中であったのかどうか。","respondent":"市岡企画財政課長","answer":"必ずつくという事業が随分ありまして、それは１４年度当初予算だけではなくて、今度補正予算のほうで最終補正のご説明を申し上げますけれども。そんなようなことで、予算説明のときに申し上げますけれども、そういう成果がたくさんあったです。","id":"exchange-023"},{"speaker":"辻副委員長","kind":"質問","question":"最終的に来たときに、それはおまけとして事業部の翌年度にどういう形で、プレミアみたいな形でプラスになっていくんですか。年度途中の中でいろいろ工夫したりした中で残った部分についてのものは、どういう生かし方をするんか尋ねました。","respondent":"市岡企画財政課長","answer":"先ほどの説明の中でも、やっと１年目ですし、これが一つの改善点かなと思います。継続することによって、今はそういう時代ではありませんので、先ほどの話ではないですが業績評価の一つとしてお返しすると。","id":"exchange-024"},{"speaker":"辻副委員長","kind":"質問・要望","question":"ある部分の一つの行程の中で、この辺が法的にも問題なしにやれるのかどうか、これが新方式の中でどの辺の課題というのが残っているのか。それは品川区だけではなくて、自治体の問題として考えなければいけないというような課題も含まれてくるのかどうか、ちょっとお聞かせいただきたい。","respondent":"市岡企画財政課長","answer":"２年、３年とだんだんかかっていきますから、そういう嫌いがあって単年度に使い切ってしまおうというのがありました。そのようなことを考えているんですが、いずれにしても少し全体的な整理をする中でやっていきたいと考えています。","id":"exchange-025"},{"speaker":"辻副委員長","kind":"質問・要望","question":"どういうものか見たときに、よく言われている公共事業の補てん枠ですね、道路財源が偏っているとか。その辺のものが、今回の行政評価と合わせてうまく動いていく一つのモデルになってもらいたいなということを、要望として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"私の理解が間違っていたら指摘していただきたいんですが、今までは議会のチェックがありましたけれども、今回は議会のチェックというのはどういう形で係わってくるのか。","respondent":"市岡企画財政課長","answer":"私の説明が舌足らずだったんですが、例えば１４年度当初予算の中で大きく経常経費と臨時的・政策的経費があります。これは非常に説得力がありまして、現に今回の予算ではそういう計画もの、より政策的なものにつなげる経費というのが幾つか例がございました。","id":"exchange-027"},{"speaker":"塚本委員長","kind":"提案","question":"次回に向けて各会派の方々から文書で、前の審議を踏まえて要望すべきことのご意見をいただきたいと思うんですけれども、いかがでございましょうか。次回は、２月１５日を予定しておりますが、事務方の整理の都合で２月５日までに意見の集約をお願いしたいと思いますけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"桜井委員","kind":"質問・要望","question":"要望というのは、例えば今年行政評価の問題をずっと審査しました。あるいは全くフリーに、それについての一つ一つの党の見解みたいな形になっていくのか、委員長のほうでお考えがあったら聞かせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"桜井委員","kind":"質問","question":"そうすると、行政評価システムが平成１３年度に行われて、その報告をいただいたことについての意見というふうになるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"桜井委員","kind":"質問","question":"質問があるんですが、いいですか。今回、新たな政策評価に向けての動きがあれば参考までに聞いておきたいと思っているんですけれども。","respondent":"榎本行財政改革担当課長","answer":"外部評価委員を募集しました、ある程度の目鼻がついてあります。政策評価の中身につきましては、もう少し中身を検討した段階でのご報告をしたいと思いますけれども、その辺につきましてはご報告したいと思います。","id":"exchange-031"},{"speaker":"桜井委員","kind":"質問","question":"では、私どもの任期の中でいただくということなんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"その中でご報告したいと思います。","id":"exchange-032"},{"speaker":"松澤委員","kind":"意見","question":"ちょうど今日の午前１０時から、もう４回目になるんですけれども、それに対する報告の検討会というようなことも行っております。あるいは５人ぐらいしかいないとか、詳しくは報告書に載りますけれども、勉強をしてまいりましたということを報告しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/373656?Template=document&Id=5698#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":41829,"voices":95}},{"id":"h14-20020215-13","meetingId":"h14-cm02","date":"2002年2月15日","dateIso":"2002-02-15","committee":"清掃・リサイクル特別委員会","time":"午後１時１０分～午後３時１６分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"北野委員","kind":"質問・要望","question":"「あなたの満足度調査」というところで、「その他」が１５％と出ていますよね。不満だったというところを差し引いたのが大体１５％ということですが、どういう状況があるのか、教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"満足か、不満であったかということでシートをつくってお聞きした関係上、そうではないというところがその他になるということです。どちらでもいいというお答えも２割ぐらいあるということを考えますと、このこと自体が、従前に比べてそれほど大きな変化と認識しないというのが。","id":"exchange-001"},{"speaker":"北野委員","kind":"質問","question":"アンケートですから、きっと匿名だと思うんですけれども、やっぱりその他のところには、「どちらとも言えない」という項目も入っていて、あとは全然丸もつけないで、判断に困ったような場合もあったのか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"今、７番の「望ましい収集方式」のほうに若干お答えを書かせてもらっているんですが、１割ぐらいの中にいるのかなとは思っております。ですから、あくまでも、満足でもない、不満でもないという方は「その他」に答えてくださいということで出てきた数値ということです。","id":"exchange-002"},{"speaker":"北野委員","kind":"質問・要望","question":"どういうふうにうまく職員がローテーションを組みながら収集したかとか、そういうのがあると思うんですけれども、どういう方法でされていたのか。それが今後の工夫にもつながっていくのではないかなと思うので、お伺いしたいと思います。","respondent":"後藤荏原清掃事務所長","answer":"清掃車の収集の職員は２名体制でやっております。車の出入りできる集積所でごみを取るより、路地奥まで入ってまいりますので、時間としてはかかるということになります。","id":"exchange-003"},{"speaker":"北野委員","kind":"質問","question":"車が回るコースって決まっていますよね。そのときに、１人の職員ばかりじゃなくて、やっぱり平均に回るような工夫というのはされたんか尋ねました。","respondent":"後藤荏原清掃事務所長","answer":"左右ということで４等分するような形にせざるを得ませんので、車から下りて、比較的少ない組というのは出ました。受け持ちの面積、戸数を少なくするといいますか、そういうことで対応しておりました。","id":"exchange-004"},{"speaker":"北野委員","kind":"質問・要望","question":"これからまた予算のほうになってきますけれども、各戸収集というのが始まってきますよね。やっぱりどういうのがいいのかというのが、市民の方の利便性も考えながら、ぜひ進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"モデルの実施状況がどのように区民の方々に反映されて、ご意見とか、これからやっていく方向を求めるのにどういうふうに生かされていくのか。その三つ、伺います。","respondent":"後藤荏原清掃事務所長、山口品川清掃事務所長、中山清掃リサイクル課長","answer":"一部、２回目の収集作業に入ったところがありますので、９時半から１０時程度に入った組もございました。すべて… それから、もう一つの組については、早いところは、１台目が８時ごろからというような形での時間で収集をさせました。一部集積所利用もありますので… カラスの被害といったものを分析しながら、エリアの順位をつけながら、その年度の体制の中で実施可能な地区を請け負うという考え方にあるところです。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"当然そういう話は行っているわけですから、意識を啓発するのであれば、さらに一歩踏み込んだ工夫が必要なんじゃないかと私は思うんです。ちょっとその点について、改めて、見解を伺いたい。","respondent":"中山清掃リサイクル課長","answer":"実施して、協力の回答としてのフィードバックよりは、個別に対応するとなると。エリア的なこういう対応とは別のこととして、今後、個別の対応として考えていきたいと考えている次第です。","id":"exchange-007"},{"speaker":"堺委員","kind":"質問・要望","question":"モデル実施をされましたが、改めてまた日にちを選んで、ほかの地域でのモデル実施というのは考えられているんですか。参考までにちょっと教えていただきたいんですが。","respondent":"中山清掃リサイクル課長","answer":"先ほど、今後の優先順位をつけていくということを申し上げたんですが、まだ明確なエリア、規模を、現段階で定めているわけではございません。このエリアにこだわらず、区内の中で、これを踏まえて優先順位をつけながら段階的に実施していきたいと考えております。","id":"exchange-008"},{"speaker":"堺委員","kind":"質問","question":"そうすると、何回かやりながら、最終的には品川区全体で各戸収集にもっていくという理解をしていいんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"基本的には、今後、一定期間かかるかとは思いますが、今回のモデル事業を踏まえて、現段階で考えておりますのは、各戸収集を収集の基本にしていきたいと考えております。","id":"exchange-009"},{"speaker":"堺委員","kind":"質問","question":"どちらでもいいという人が２５％ですから、４１％の人は、各戸収集を望まないと言っていいんでしょうか。これを見る限りでは、そんな形にならざるを得ないのかなと思うんですが、その辺はどうお考えか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"基本は各戸収集という考え方でまず進めたいと申し上げましたけれど、個別に説明しても、やむを得ず集積所方式の形が残ったということもあります。片やこういったものを進めていきながら、例外なく個別収集にするというのも、施策上非常に困難を来すということもあります。","id":"exchange-010"},{"speaker":"堺委員","kind":"確認","question":"あるいは、時間は増えるけれども、人件費、手当て的なものについては変化がないんですよということなんでしょうか。その辺はどういうことなんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"清掃事務所のほうで工夫しながら実施したということがありますので、経費としては、基本的に新たにかかっているものはございません。それを単純に、拡大していく際には、私どもが考えていく一つのポイントになるのかなと考えています。","id":"exchange-011"},{"speaker":"堺委員","kind":"質問","question":"よく我々がいろいろな質問をすると、理事者の人は、費用対効果という表現でおっしゃいますよね。今、いろいろなご努力をしていただきながら、区民の身近なサービスの一環として事業の成功を推進していただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"不燃ごみ、可燃ごみのほうから資源ごみとして出したために、こういう形でごみが減ったということが考えられているんでしょうか。組成の分析もされたということなので、そこら辺のところが、どういうふうに分別されていったのかというところを教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"もう一つ考えられることとしては、もらわないということまで、意識が高まったと考えられるのかなと。減の内訳までは明確ではないですけれども、両方の要素があろうかと思っています。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで、特に区として意識の高揚を図るための説明会を開くとか、そういうことをしたというわけではないんでしょうか。この２,６００世帯がモデルになったということなんですけれど、実施のお知らせなんかはどういう形でされたかについて、ちょっと教えていただきたい。","respondent":"後藤荏原清掃事務所長","answer":"説明といたしましては、７月から８月にかけまして、ごみの袋を持って収集職員が１軒１軒訪問をいたしました。職員が実際に顔を会わせてご説明するという中で、一層の意識というものが高まったのではないか、そういう部分もあるかなと考えています。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"啓蒙するみたいな、町会ごとにそういうふうな形でされるということも考えられたらどうなのかなと、私は生ごみのときも思ったんです。意識の啓発というところで、そういう方向というところではいかがか尋ねました。","respondent":"後藤荏原清掃事務所長","answer":"昨年の９月に私どもがやった二葉二丁目につきましては、そういうふうな人を集めての説明会というものはやっておりません。ただ、今年、また指定をする際には、そういうことももちろん申し上げますし、また集めてということも考えて行いたいと思っています。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"いろいろ集まって、いろいろな意見を聞きながら自分のところも考えるということで、意識も図られるというところもあると思いますので、そういうやり方をご検討いただけるということなので、ぜひよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"土井委員","kind":"質問・要望","question":"ですから、どっちがどうかというのはわかりませんけれども、その辺を何かの機会でぜひお聞き取りをいただきたいものだなと思ってもいるんです。その辺の分析に発展させていただいて、またお聞かせをいただければ幸いだと思うんで、その辺どうなのかということでお話しください。","respondent":"中山清掃リサイクル課長、後藤荏原清掃事務所長","answer":"両清掃事務所において、これから新たな展開という中で検討していく中で、既に係わった職員から出てこようかと考えています。サービスの向上も図り、それをオープンにして… 職員の声をというところで、つけ加えてご説明します。各戸収集の実施に向けましてプロジェクトチーム的ものを組んでおりまして、既に３回、夜にかけてやっております。","id":"exchange-017"},{"speaker":"土井委員","kind":"提案","question":"全体の了解として進めて、全区個別というのが全体のコンセンサスなんだということでやっちまえば、それはそれでそれも一つの提案です。こういう形でいったら、経費等がどうなんだろうかということの予測みたいなものは、その辺のことをお聞きして終わりますとの意見を述べました。","respondent":"野本環境清掃事業部長","answer":"来年度も、基本的には、本格実施に向けての第一歩を踏み出す予定です。そういうつもりでやらせていただきたいと考えています。","id":"exchange-018"},{"speaker":"土井委員","kind":"意見","question":"まさしくそういうことだと思いますので、一挙に無理して拡大をするというやり方というのは、その意味では、議論を後からやることになりかねないということもありますので、よろしくご配慮ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"中島委員","kind":"質問","question":"土井委員の質問とも重なる部分があるんですが、その方は、いつも現場を回収に回られている方ですか。それともほかの方たちでつくられるんか尋ねました。","respondent":"後藤荏原清掃事務所長","answer":"プロジェクトを組ませております１０人余りの職員の中で、大半は収集に回っておる現場の職員です。住民への対応とか、職員の指導をする職員が３名入って、ほかは現場を回っている職員で構成しています。","id":"exchange-020"},{"speaker":"中島委員","kind":"質問・要望","question":"１カ所で車に移すときにこぼれたりとか、いろいろな問題が起きるんじゃないかなと感じたものですから、その点が１点ありました。やはり意識の啓発というのは常にやっていかなくちゃいけないんじゃないかと感じたものですから、今後、私はここで意見だけ述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"須藤委員","kind":"質問","question":"このときのアンケートで、満足したという人に、「有料でもその方向でいいですか」というのを一言加えておいてもらえばよかったなと。品川清掃事務所は今までも９４％だったのか、そこはデータの取り方が違っちゃったのか、その辺はちょっと教えてくれますか。","respondent":"中山清掃リサイクル課長","answer":"１点目の、そういう方針決定を明確にしているわけでございませんから、アンケートでは入れなかったんです。やはり、なかなか１００％という理想には必ずしも近づいていないという認識はしておりますので、そういう認識を持っているということです。","id":"exchange-022"},{"speaker":"須藤委員","kind":"意見","question":"さっき、この間のシンポジウムでアンケートの答えが出てきたというのを集計したみたいだけれど、特に個別収集についての意見はどうであったのか。１００％に近づいていくのは当然だと思うんで、後でいろいろな点がどうだこうだと、それはどうだったのかとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"シンポジウムのときのアンケートの中で、個別収集の意向はお聞きしなかったです。この辺は、委員ご指摘のようなリンクした形での意見を聞くというものも必要になってこようかと思いますので、よろしくお願いします。","id":"exchange-023"},{"speaker":"須藤委員","kind":"質問","question":"きょう出してということなんで、それでいいですから、どんどんやっちゃいます。そういうことは、きょうやるんですか、それをきょう言っていいんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"須藤委員","kind":"質問","question":"ちょっとここへ来て、それぞれみんな努力してきているところも見ないというわけにはいかないだろうと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"そこの具体的なところを、ちょっと出し合ったほうがいいんでしょうかね、委員長に伺いたいんですけど。一つ一つの柱の到達や、それぞれの会派の問題意識がどこにかあるかと表明というか、紹介をしていったほうがいいということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"それはそういうことで２３区で共同してシステムをつくっているわけですから、平成１７年度まではそういうふうにいくと。やっぱりごみ減量はもう共通認識ですから、やっぱりみんなで意識を高めながら、体制を充実させていけばいいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"堺委員","kind":"確認","question":"先般、今後協議すべき主要５課題における確認について、最重要関心に進めていかなければならないようになるというふうに我々は認識をしております。区民が実質ケアというんですか、その辺のところを一つのくくりとしたとらえ方も一つな重要な柱であろうかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"中島委員","kind":"質問・要望","question":"そうしたときに、ほんとうのごみ減量というのはどうことなのかという、その辺のところの疑問というのも実際に出てきているわけです。そういう意見も、もしできたら入れてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"北野委員","kind":"質問・要望","question":"やはり東京２３区清掃一部事務組合が平成１７年度末までということですから、やっぱりきちんと何らかの整理がされるべきではないかということ。地域の中に広げていくとか、そういうような身近なところでできる範囲の活動で市民に協力を求めるということは必要じゃないかなということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"土井委員","kind":"質問","question":"それは影響ありません、向こうがやるのですから勝手ですというのではないはずだと思いますので、そこら辺の議論も必要なのではないか。全体の問題ですから、議会のどこかできちんと体系的に議論をされる形をつくっていかなければいけないのではないか、などと話しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"藤原委員","kind":"意見","question":"ただ一つだけ、一番話の中に出たのが、やはり東京２３区清掃一部事務組合のことでございました。平成１７年度に解散するというのが規約の中に入っておりましたが、これからも議論をしていかないといけないし、うちの会派の一番の意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"船波副委員長","kind":"質問・要望","question":"もっと事業者が考えて、個人だけの努力を求める有料化のほうへ走って行ってしまうのは、あまりにも個人個人が気の毒な状況に置かれると思うんです。どうもそっちのほうにいっているような気がするんですけれど、その前に、ごみを減らす方向への発信などもきちっとやっていってほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国に対しての意見書を上げていくことが委員会としてできないかということを、ぜひ、検討もしていただきたいということが要望なんです。そこら辺のところを意見書として上げていくということで、ぜひ、検討していっていただきたいという要望をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"意見","question":"前に１回言ったけれども、今ある欠点をどう補っていけるのかというところ、自治体でほんとうに知恵を出し合えると思うんです。だから、そういう論議をもっともっとしていけたらなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"６階で、どうしても、日常生活の中でそういうのがいっぱいあるんですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"林（和）委員","kind":"意見","question":"先ほど、我が党の須藤委員が発言したとおりですけれども、うちの鈴木副委員長が、３日前に風邪で３９度も出して寝込んでいるんです。後ほどまた３人で話し合いまして、それにつけ加えるところがありましたら、副委員長を通して委員長にご報告をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"須藤委員","kind":"提案","question":"それを１回、我々もしっかりしたものが委員長に伝わると思うんで、そういう方向に委員会を運営をしていただきたく要望します。私の提案ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"中島委員","kind":"意見","question":"今ここでは時間の制限もあるし、１人が何回も発言しては思う部分もあったりで、ここで発表しきれないところもあります。ほんとうに努力していることも言えないとか、いろいろ思いがありますので、各会派でまとめさせていただけたらありがたいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"須藤委員","kind":"意見","question":"だから、議事録を整理して文章をどうのこうのするんじゃなくて、逆に我々が、きょうお話ししたことを委員長に出したほうが、各会派がどうだって、事務方が議事録を一つ一つ細かく整理していってまとめるというのは、かなりの事務量があるんですよ、大変だと思うんですとの意見を述べました。","respondent":"高木委員長","answer":"議事録は議事録で、できてきますね。皆様に、次回の委員会でご提示申し上げて、またご議論をいただくことになるかもわかりません。","id":"exchange-040"},{"speaker":"須藤委員","kind":"提案","question":"あるいは、提案したりという形をとっていますので、そうされたほうがいいんじゃないだろうかというご提案をしているんです。委員長がおっしゃるけれども、皆さんも必要ないというのなら、それで構わないですけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"南委員","kind":"提案","question":"どこの会派もきちんとした文書で出したらどうですかというご提案なんだけれども、委員長のご意志は別に拒んでいるというわけじゃないわけですから。できるだけ、文書で出していったほうが、須藤委員のご配慮もきちんと担保されるわけですから、それでいいんじゃないかと思いますとの意見を述べました。","respondent":"高木委員長","answer":"ご意見をいただくと正副委員長で話をしまして、本日は、こういうふうに進めさせていただいたわけです。十分、集約の中に入れさせていただけると思いますから、ひとつご了承をお願いをいたします。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=5656#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":37628,"voices":87}},{"id":"h14-20020215-14","meetingId":"h14-cm02","date":"2002年2月15日","dateIso":"2002-02-15","committee":"行財政改革特別委員会","time":"午後１時０７分～午後３時１５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査事項に入ります。行政評価に関すること","agenda":"特定事件調査事項に入ります。行政評価に関すること","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"１年、２年というふうにはならないかもしれませんけれども、どうもよく結びつきにくい。だから、事業の内容によって評価の仕方も違うのかなというふうに感じるんですけれども、その辺の矛盾というのはあまりないんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"要は、今までずっと長年実施してきている事業一つ一つを、まず原点を見直してもらうという形での目的のとらえ方をしていくというのがあります。","id":"exchange-001"},{"speaker":"桜井委員","kind":"意見","question":"それがどうだったのかという評価の仕方について、見直しのＣに至った経過を見ると、必要性のところは４がついているけれども。私もよりよいものにしてほしいと思うんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"しかし全体に平成１３年度事務事業評価という形で出た場合、どうしてもコストと人数、これではやはりわかりにくいですよね。表に出たときの、評価結果一覧に作るときの数値としては工夫が要るんじゃないかなと思うんですけれども、その辺はどうか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"その部分の形ですと、その辺は説明を加えて入れていかないと、そこはちょっと難しいかなとは確かに思っております。実際には事業実績が一番わかりやすいので事業実績と指標を並べるとか、少し工夫をした形での出し方を検討したいと思います。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"今年度の評価がこういう状況で、一つの成果としてどういう成果が上がったのかというものも、こういう仕組みの中にぜひ入れていただきたいなと。それがどういうふうに生かされて、仕組みの中にぜひ入れていただきたいと思うんですが、その辺はどうか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"平成１２年度の実績を踏まえまして来年度の予算につきましては、ある程度簡素化に向けた全体的な枠組みを見直ししています。ただ、単年度は単年度で方向性が出ますし、公表する部分のやり方はかなり工夫していかないと流れが短くなってしまうというふうに見ているところです。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう意味では、先ほどの実績の理解の仕方といいますか、そういう意味で工夫をぜひしていただきたいのと、また時系列的に見てこれだけの成果が上がったんだというのがもし示せれば、それも大きな区民の方の理解を深めていただく内容になると思いますので、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"佐藤委員","kind":"意見","question":"事務事業評価を拝見して、内部評価の初年度ということなので、こういうふうな形になるのでしょうが、小学校、中学校が外部評価を採用すると。","respondent":"榎本行財政改革担当課長","answer":"参加者なりのアンケートで対応していくとか、実際上世論調査みたいな形で対応していくとかという形での対応がある程度できます。この後ご説明するんですけれども、政策評価のほうで事業、なかなかそういう仕組みに結びつけられるかどうかというのは難しいかなと考えています。","id":"exchange-006"},{"speaker":"佐藤委員","kind":"質問・要望","question":"例えば成人式にしても、区民まつりにしても、地域住民の協力がないと遂行できない事業というのはたくさんあるんです。ですから、それぐらいのものは外部評価を導入していく検討をしてほしいと求めましたので、ひとつご検討をくださるよう要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"金高委員","kind":"質問・要望","question":"確認だけさせていただきたいんですが、８番の挑戦加点評価項目に自己評価がありますけれども、５点法で足していくという形でしょうか。７番のところで６項目ですから３０点満点という形で、３５点満点でのＡ、Ｃの評価ということでいいんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"今段階では基本評価の３０点満点を基本に考えておりまして、６点から１２点がＤという形でのおおむねの基準を定めております。Ｃ、Ｄをある程度加味するときの基準ということで、特に点数を両方足すというような形でのとらえ方は今回の場合には取っておりません。","id":"exchange-008"},{"speaker":"辻副委員長","kind":"確認","question":"区民に対する公表の形で出たときに、この表というのはどういう形で一般区民の方が見れるのか見れないのか。もうちょっと詳しいものを見たいといったときに、どこに行けば見れるんですかということを確認したい。","respondent":"榎本行財政改革担当課長","answer":"まだ初年度ということで実際上は公表できるまでの成熟度を持っていませんので、そこは今のところ公表する予定はない考え方です。今年度は５００事業をやる中で、どういう形でデータを広げてわかりやすく組み立てられるかという形でのやり方を検討していきたいと考えています。","id":"exchange-009"},{"speaker":"辻副委員長","kind":"確認","question":"もう一つ確認しておきたいのは、全事業は大体７００ちょっとあるんですね。そのときに事業成果指標というのは、その都度動くわけですね、その辺はどうなんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"その指標につきましては、一応動くのを前提で考えております。よりよい指標が出てくれば、事業の本当の目的はこうじゃないかということが出てきますので、その部分は検討の余地があると思います。","id":"exchange-010"},{"speaker":"辻副委員長","kind":"質問・要望","question":"来年は１４人が２０人になったら、私は要望書のほうにも触れておきましたけれども、マイナスの場合もある。内部ですから内部の事業評価はこういう形で担当の皆さん方はそういう評価をし、一つずつをチェックしているんだなということを。","respondent":"榎本行財政改革担当課長、塚本委員長","answer":"その辺がまだなかなかでき上がりが出ていないところがあるんですけれども、その辺も含めて今後の指標の取り方等も研究をしていきたいと考えています。報告をもう１件受けたいと思います。政策評価の実施について、報告願います。外部評価委員会は第１回目が来週の月曜日に開かれる予定でございまして、実施スケジュールとしましては２年間ということを考えております。","id":"exchange-011"},{"speaker":"佐藤委員","kind":"質問","question":"出されたものを、まるっきり品川区の実態から離れてしまって、一般論的なものが出てこないとも限らない。学識経験者の住所は全部品川区内居住者か尋ねました。","respondent":"榎本行財政改革担当課長","answer":"実際に区の現状についての説明をかなり長い時間かけて、今まで長期計画でやってきた事業についての説明をしたいと考えています。分科会等の設置の部分なんですけれども、または区民からのいろいろな要望等を勘案して検討はしてまいりたいと思うんですけれども。","id":"exchange-012"},{"speaker":"佐藤委員","kind":"質問・要望","question":"徹底した情報開示がないと外部評価委員は評価する材料を持たないわけですから、こういうふうな要望に対する答えは出しかねると思うんです。したがって、情報開示というのは、どの辺まで具体的におやりになるつもりなのか、その辺を聞かせてください。","respondent":"榎本行財政改革担当課長","answer":"要は「過去１０年こういう形で進んできました」と、なるべく資料作成等をいたしまして出せるような形で情報としては考えております。","id":"exchange-013"},{"speaker":"佐藤委員","kind":"質問・要望","question":"恐縮なんですが、個別の情報を請求された場合、町会長が「個人的にこれに使うので、こういう情報をいただきたい」と言って、万が一、申請人が要求しているところまでは出せませんというような事態が起きることはないと考えていいんでしょうね。","respondent":"榎本行財政改革担当課長","answer":"今まで品川区がいろいろまちづくりをしてきた中の大きな流れの部分をとらえて議論していくというのを前提で考えているんですけれども、その辺でどの範囲まで出せるかということですけれども、なるべく出せるものは資料としてきちんとまとめて出していきたいと考えています。","id":"exchange-014"},{"speaker":"本多委員","kind":"確認","question":"品川区の政策評価ということですから、主要政策、重点政策ということで確認されてあるんですけれども、やはりおおむね第三次長期基本計画が対象なんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"その中の七つのプランというか、重点プランが今後の主要政策なり重点政策として位置づけて実施しておりますので、それが入ってくると思います。ただ、平成１３年度からの長期計画にどう反映されてきているのかという部分も含めて、評価の対象としていきたいという考えでおります。","id":"exchange-015"},{"speaker":"本多委員","kind":"質問・要望","question":"今、その評価というものをしっかりやっていただきたいと思うんですけれども、そういった部分の非常に評価を出しずらいところとかもあると思うんです。見解というか、その辺の公開の考え方を出していただければありがたいなと思いますので、その辺について見解を聞きたいと思います。","respondent":"榎本行財政改革担当課長","answer":"まだどこまで検討の対象とするかというのは、実際上、その辺は外部評価委員会の中である程度研究して詰めていきたいとは思っております。ただ、十分東京都ですとか、国のほうの政策も合わせた上での評価ができるような仕組みづくりに入っていきたいと考えています。","id":"exchange-016"},{"speaker":"桜井委員","kind":"質問・要望","question":"それから、具体的には審議の内容も含めて委員会の公開はどうなんでしょうか。任期は２年と伺ったんですけれども、この機関の代表という形で位置づけているんでしょうか、それを確認したいんです。","respondent":"榎本行財政改革担当課長","answer":"ある程度事前に検討して、やはり議論して仕組みをつくっていく中で、そういう形での評価の仕組みを考えていきたいなというふうには思っております。","id":"exchange-017"},{"speaker":"桜井委員","kind":"質問","question":"あるいは意見というか、そこのところというのは非常に重視してほしいというのが、多分のほかの委員も共通だと思うんです。品川区に住んでいて、暮らしに役立つような区政にしてほしいという、その辺のところというのは強く出ていると思うんです。","respondent":"榎本行財政改革担当課長","answer":"品川区がだんだん自治意識が高まっているのがわかるとかというとらえ方ができないかとか、そのような形も考えられるかなと考えています。関係者の声を聞くという中では、やはりアンケート等を活用できれば、その辺の部分がある程度進むのかなと考えています。","id":"exchange-018"},{"speaker":"嶋委員","kind":"意見","question":"いろんな状況から見て４名をということなんですが、１５名の中でなぜ男性２名、女性２名になって４名という数が出てきたのかということ。もちろん学識経験者ですばらしい方たちだと思うんですけれども、そういう意味でちょっと不安もあるんですがとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"そういう点からも１名増やしまして、男性２名、女性２名という形での選択をいたしました。それから、民間団体でもかなりいろんなところへ参加している方を中心に選んでおりますので、いろんな幅広い意見が出てくるものと考えています。","id":"exchange-019"},{"speaker":"嶋委員","kind":"質問","question":"委員は合計１１名ということなんですが、現品川区行政側からは企画部企画財政課ということでありますので、ここがリーダーシップを取っていかれると思うんですけれども、区のほうのメンバーはどういう方が出席をされているのか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"区のほうもメンバーは事務局といたしまして企画部長、企画財政課長、政策担当課長、行財政改革担当課長ということで、あとは事務局のメンバーとして企画のほうのメンバーが入るという形で考えております。","id":"exchange-020"},{"speaker":"松澤委員","kind":"意見","question":"この外部評価委員会、２年間の間に前期・後期を分けるということですけれども、私たち議会に対する報告というものはいつ頃されるのかということ。","respondent":"榎本行財政改革担当課長","answer":"こういう形でいきたいというような、ある程度まとめができれば、その段階での報告を考えております。メンバーの活動経歴なんですけれども、地域の防災組織の人とか、住んでいる地域の取りまとめの役員をやっている方とかという方がやっております。","id":"exchange-021"},{"speaker":"辻副委員長","kind":"確認","question":"ちょっと確認をしておきたいんですが、位置づけというのはどういう形なんですか、要するに審議会──はっきりしないんですよ。重点政策について、一つ一つ答申を出すための委員会なんですか、それとも仕組みづくりをまずつくってくださいというためのものなのか。","respondent":"榎本行財政改革担当課長","answer":"位置づけなんですけれども、要網設置の私的諮問機関という形になりますので、ある程度の結論を出してもらうことを考えております。実際に何を検討してもらうかという形なんですけれども、その２点を考えております。","id":"exchange-022"},{"speaker":"辻副委員長","kind":"意見","question":"こういう分野について制度がどうだとか、ああだとかという論議があるでしょうけれども、指標について討議していくというのが１年間続くわけですね。成人式についてどうかといったときに、これはどうしましょうとかという、これは整理が大変だと思うんだけれどもどうなんだろうとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"いろんな実績が上がってきているものですから、それと合わせてそういう実績等も見てもらいながら、ある程度研究を重ねていきたいと考えています。評価を出したものが区民にとってわかりやすくて、そこの目標を２年間でやっていきたいというふうに考えているところです。","id":"exchange-023"},{"speaker":"辻副委員長","kind":"質問","question":"2)、1)の内容が「長期計画で実施してきた主要政策および重点政策の計画に対する達成の状況」というものを、基準が違うんだから。事務局として引っ張っていくというのは大変ですよというのは、老婆心でしょうか、ちょっと。","respondent":"中尾根企画部長","answer":"この委員の中に品川区なりの分析の手法はどういうものがいいとお考えなのか、そのことをまず検討していただいて、これが全体のストーリーと目的です。検討内容の部分が順不同といいますか、品川区なりのものを今回の委員の中にお願いしたいと、こういうことで進めてまいるです。","id":"exchange-024"},{"speaker":"辻副委員長","kind":"質問・要望","question":"個々の次のステップの話をどんと出してしまうと、私はめちゃめちゃになってしまうんじゃないですかということ言っているわけです。そしてプラン・ドウ・シーという形でやっていくわけですから、そのための評価の物差しというものを今回やっていただく委員会なんだと。","respondent":"中尾根企画部長","answer":"設置するにあたっていろいろ議論があったわけですけれども、私の認識とすれば、そういうことで出発させていただきたいと思います。そのときの付属機関に位置づけても遅くはないかなと、このような考え方で進めしますので、どうぞよろしくお願いしたいと思います。","id":"exchange-025"},{"speaker":"辻副委員長","kind":"意見","question":"品川区でも富士山が見える箇所があるでしょうけれども、区役所の５階から見えますよね。ちょっと長くなりましたけれども、ひとつとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"桜井委員","kind":"確認","question":"確認ですけれども、議会への報告の関係で漏れたんですけれども、例えば委員会が２カ月に１回ペースですよね。その委員会が終わった段階で、あるいは次の委員会のテーマとかというのも含めて、毎回議会には報告をするというふうな理解でいいのか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"こうなって、こうなりましたという一つの節目ができた段階でのご報告にさせていただきたいと、今のところは考えております。","id":"exchange-027"},{"speaker":"松澤委員","kind":"質問・要望","question":"自民党は５点要望したんですが、そうすると分類に分けた６点を読んだほうがよろしいですか、それでは分類したほうで。説明責任を果たすことが求められているので、区民にとって事務事業の状況や推移がわかりやすいように、数値を用いた指標で示していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"嶋委員","kind":"意見","question":"将来的に事務事業評価制度が定着する中で、区民のそれぞれの事業に対する満足度がどうかをつかむ必要も出てくると考える。満足度を評価するメルクマールの設定など、将来の満足度調査に向けた研究を希望するとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"桜井委員","kind":"意見","question":"３番目に書いていないんですけれども、実は１１番目に事業の見直しについてということで、それを補足しておきます。３番に加えていただいても結構ということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"桜井委員","kind":"質問・要望","question":"「公平性」については、受益者負担を適正に行うとして区民の負担増を求めている。事務事業評価の結果が予算編成に反映されているが、内容についての説明を求めたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"佐藤委員","kind":"質問・要望","question":"合同としては３点，要望をいたしました。なお、廃止された事業について区民の要望等があった場合は、別途公表していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"金高委員","kind":"質問・要望","question":"５番、公表と情報提供について。行政評価の結果については、細かな内容とともに各種の情報媒体を使って情報提供を行い、区民の区政に対する理解を得られるようにしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"１３番、予算編成について。予算編成前に議会側から要望する仕組みづくりをお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"桜井委員","kind":"質問・要望","question":"もともと公益法人ですから、なぜそういうことが行われたのかという、手続だけの問題にならない本質的な問題にも係わると思うんです。その問題について、そして是正を求めることはしていくというのが今日的な課題ではないかというふうに思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"桜井委員","kind":"確認","question":"そういう委員長の仕切りで了としますけれども、１点だけ区の対応なんですけれども、ここで詳しく論議するつもりはありませんけれども、この問題についての区の基本的な対応だけ確認しておきたいんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/373656?Template=document&Id=5700#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":39016,"voices":86}},{"id":"h14-20020215-16","meetingId":"h14-cm02","date":"2002年2月15日","dateIso":"2002-02-15","committee":"街づくり特別委員会","time":"午後１時０７分～午後３時２３分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問","question":"ちょっと二つばかりお尋ねしたいんですが、東光電気さんかどうかというのはわかりませんけど、少し教えていただければなと思ったのが一つです。９億円ぐらいでしたか、予定のところはそういうことも予定されているのか１点と、そこを３点お願いします。","respondent":"南雲都市開発課長","answer":"解散をするということで、その後に工事に着手するということで、事業者のほうからはそのように聞いております。民間の事業者の単独の開発ですので、区の予算も計上しておりません。","id":"exchange-001"},{"speaker":"石田委員","kind":"確認","question":"１点だけ、ちょっと事実関係だけ教えてください。将来ここにはこういう建物が建ちますよという、後でもめる原因だと思うんだけど、その辺のはちゃんと入っているのを確認しているんか尋ねました。","respondent":"南雲都市開発課長","answer":"それは想定されて、大まかな形状については、計画の中に入っています。この分譲棟の分譲いたします購入希望者の方への重要事項説明の中では、それについては説明がなされているというふうに聞いております。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"今状況が進んでいないのをどういう形で進めていくには、昨年もそういうことがありましたが、総論的な物事でしていくのでは進まないのではないか。そういうところを何で１区１地区なんだというところも含めて、もしそういう要望なり、そこら辺の意見の集約をしていただければありがたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"上山委員","kind":"質問・要望","question":"拡充するとか、それと、例えば私のほうもそれについては住宅手当だとか助成対象だとかについて増額の要望をしているわけです。ここのところ、共産党としてはそういうところを出して、他の会派さんとも例えば共通しているようなところがあるかなと私も思っているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田委員","kind":"提案","question":"今個々の話というのが出たんだけれども、密集事業を、もし私も提案しなさいと言われたら、密集地域があって、密集事業をやっている。だから、あの密集地域の密集事業自体も進まないんじゃないですかということで、必ず絡んでくるということだけは理解していただきたいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"川西委員","kind":"質問・要望","question":"要望文にも入れましたように、各党の皆さんが出してくださったのは、ほんとうにそれぞれ意見には同意できる部分があります。この各党の要望を出していただいたというのは、どういうふうなまとめ、お任せしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"横山委員","kind":"質問・要望","question":"ですから、ちょっとここになっておりますよね。委員長のほうでまとめてほしいという要望の趣旨というか、内容からこういうような内容で提出させていただいたということなんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"藤田委員","kind":"質問","question":"そうなると、当然こことこことここぐらいの数えられるぐらいの一つの町会ですから、大体対象者はここだなというのがわかると思うんです。ですから、うちとしては、広げないで、あくまでも地区で限定して、物を申したほうがいいのかなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"本田委員","kind":"質問・要望","question":"これはいろいろな手法を使ってどうこの問題を解決していくかと、その３地区だけじゃなく、それは同感です。区にこうしてほしいという要望が一番多いんですけれども、正副でまとめていただいて、じゃあ国に対して要望書として出すかどうかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"本田委員","kind":"質問","question":"出すかどうか、もうちょっとその上で議論したらどうかなという格好で、この委員会も役割をまとめたらどうかなというふうに思うんですがね、難しいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"本間委員","kind":"質問・要望","question":"あるいは立会道路のわきの大井新地街のあそこの１世帯はどうなんだねとかいう話も実は出ましたが、まとめさせていただいたわけです。大変自助的な部分もあったことをおわびしたいと思いますが、そのようなことを述べさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"石田委員","kind":"質問・要望","question":"いろいろ要望だとか、そこの過程の中で正副でお考えいただいた中で、区の方がそれに対して今事業を進めている。そういう点をお考えほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"確認","question":"ちょっと確認したいんですけど、ちょっとそこら辺のことをそうなのか、ちょっと……。","respondent":"浜脇住環境整備課長","answer":"地元も負担にならない、区側も負担にならない方法を、事業手法を探しているというふうに考えているところです。まだ、事業手法ははっきりと申しておりません。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"意見","question":"そういうことをどうするんだという話だったんですけど、この事業、三つの地区の事業に限ってという感じはするんですけどね。いろいろ意見もそんな感じなのかなと思ったんで、いろいろ意見はあると思うんですけど、おっしゃるとおりだなというふうには思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"石田委員","kind":"意見","question":"それを密集住宅整備促進事業の事業という１個だけをとらえると、それにはいろいろ意見がある。だけど、ほかの手法もかみ合わせていかないと無理でしょうと言っているとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、この密集住宅市街地整備促進事業全体だということであれば、それはそれでいろいろ考えなきゃいけない。そこのところをはっきりしないと、そういう議論にならないんじゃないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"本田委員","kind":"質問","question":"さらに今言ったような宮崎委員がこういう点の問題もあるんではないですかというふうに出しているのは、ただ。問題点がちょっとずれてきたわけですから、何か靴の上からかくようなことばかりやったってしようがないから、我々として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"石田委員","kind":"質問","question":"これを今１区１地区なわけですから、密集地区に今の絵でも３地区に当てはめてもらえば、それで戸建て政策はできたわけですよ。それを当てちゃえばいいんだから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/690912?Template=document&Id=6224#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":21402,"voices":52}},{"id":"h14-20020301-3","meetingId":"h14-c-budget","date":"2002年3月1日","dateIso":"2002-03-01","committee":"予算特別委員会","time":"午後４時５０分～午後５時００分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/799186?Template=document&Id=782#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":2625,"voices":20}},{"id":"h14-20020304-6","meetingId":"h14-cm03","date":"2002年3月4日","dateIso":"2002-03-04","committee":"区民委員会","time":"午前１０時０６分～午後１時５６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"原委員","kind":"質問・要望","question":"この業種に限って１０人を２０人にしているというところに、いろいろな意見が出てくるのではないかと思うので、その理由を説明していただきたい。区長が別に指定する中小企業者ですけれども、「区長が別に指定する」ということはどういうことなのかなということを説明をお願いいたします。","respondent":"市川産業振興課長","answer":"年末の緊急資金を実施して、自分たちが１０人という、緊急資金の実施の際に相談員に寄せられていた経過があります。一律製造業等で２０人以下、卸売業等で１０人以下と、実施内容に応じて決めさせていただきたいという趣旨です。","id":"exchange-001"},{"speaker":"原委員","kind":"質問・要望","question":"いずれにしても、限度額増ですけれども、いろいろな意味で状況は非常に厳しい経済状況の中で、むしろ拡大をしていくというのは非常に結構なことですけれども、状況に合わせた形で対応をされていくように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"１０人以下を２０人以下に拡大したということですけれども、拡大した結果、対象となる企業はどのぐらい増えるのか尋ねました。","respondent":"市川産業振興課長","answer":"これはあくまで数字の上での推定ですけれども、大体１割５分程度の利用される方がマックスで増えるというふうに計算をしています。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"１点だけお聞きしておきたいんですけれども、商店街活性化資金を１億円にアップをすると。大井サンピア商店街の方からお聞きしたんですが、この辺の問題というのは何か出てきていないんか尋ねました。","respondent":"市川産業振興課長","answer":"その際に、それについては専門のコンサルタントを付けまして、資金計画に無理のないよう事業ができるように対応をさせていただいてあります。これは国庫事業、それから、区の補助事業いかんに係わらず実施をしています。","id":"exchange-004"},{"speaker":"堺委員","kind":"質問・要望","question":"確認する意味で何点か教えていただきたいんですけれども、あるいは１番目も２番目も一切なくて、これについてはこういうふうに拡大していこう。そういうものなのかどうか、その辺の考え方を教えてほしいと求めました。","respondent":"市川産業振興課長","answer":"私の説明のニュアンスといいますか、正確にお伝えできなかったところがあります。区で国庫事業を使うということはめったにありませんことで、せめて制度融資の面で支援ということで配慮してくれないかというお話がございました。","id":"exchange-005"},{"speaker":"堺委員","kind":"確認","question":"桁が違うので、確認でちょっと教えていただいたことです。そういうところから事前の相談等があれば、配慮しなければならない点が出てくれば、条例改正という形ででも対応していくお考えはあるんか尋ねました。","respondent":"市川産業振興課長","answer":"単に商店街がこういう事業を行いたいというだけではなかなか指定されませんので、実は手続きの中で、そういった事前の手続きが入ってまいります。今後のケースについても、そういった事例に即して、私どもとしてはできる限り商店街を支援していきたいというふうに考えてあります。","id":"exchange-006"},{"speaker":"堺委員","kind":"確認","question":"その上で、こんなようにも思いましたので、その辺について確認で教えていただきました。今申し上げた、ほかのところですね、限度額、率、そういうところは従来どおりということになるんか尋ねました。","respondent":"市川産業振興課長","answer":"今ご指摘のございました小規模企業特別事業資金、俗に小特資金と呼んですけれども、小特資金については、経常的に実施をしておる事業ですので、従来どおりの要件ということでやらせていただきたいと考えています。","id":"exchange-007"},{"speaker":"堺委員","kind":"質問","question":"そうすると、従来、卸売業、小売業１０人以下だったのが、２０人以下にすることによって、対象となる店舗数はどのぐらい増えてくるんですか。当然、対象が増える、区の負担が増えるということは積算されているんだろうと思いますが、その辺のところの予測はどういうふうに立てておられるのか。","respondent":"市川産業振興課長","answer":"今回の改正によりまして、最大限度で約１割５分程度の利用増が見込まれるというふうに考えてあります。今後の実施に当たりましては、今回の改正を受けた若干の費用増ということを見込んでいかなければいけないものというふうに考えてあります。","id":"exchange-008"},{"speaker":"堺委員","kind":"質問","question":"今の段階ではまだ金額は、おおよその金額は出ていないということですか。一応、店舗数、対象者は１割５分は増えるであろうということか尋ねました。","respondent":"市川産業振興課長","answer":"一般的に１割５分増えるということで計算しています。緊急資金の実施時によりまして、１年間の融資の動きによって大分違ってまいりますので、先ほど説明をさせていただきました。","id":"exchange-009"},{"speaker":"堺委員","kind":"質問","question":"１９億２，８９０万円ですか、貸付が成立したのが３３７件、約１２０件が不成立になっております。１３億２，３００万円某が出ておりますけれども、こういうところも当然１割５分増しという形になるという想定はしてありますということか尋ねました。","respondent":"市川産業振興課長","answer":"今ご紹介いただいたときは、大体見込みとしては、当時５００件という融資実行の見込みをしてございました。５００件を見込んだときに、大体５５０件前後の見込みを立てて、いろいろな経費の見込みも併せて立てていく。","id":"exchange-010"},{"speaker":"金高委員","kind":"質問","question":"金額が高いですから、多分１０年とか、商店街に加盟する各店舗の方々の負担金というのは非常に厳しくなってくる。商店街として、例えば償還期限を延ばしてくれとか、そういう救済措置というのはあるんか尋ねました。","respondent":"市川産業振興課長","answer":"大体今までの実施事例を見ていますと、ある程度の積立資金というのがございまして、それをもとにまたさらなる追加資金ということで考えてまいります。","id":"exchange-011"},{"speaker":"金高委員","kind":"質問","question":"限度額１億円を借りるとなったときに、万が一個々の商店のところに負担がなってしまって、返済というものが非常に厳しくなる。当然経済変動も違いますから、過去の事例も含めてその辺のところをお聞きしたいと思います。","respondent":"市川産業振興課長","answer":"ただ、今までケースはございませんが、不幸にして事故が起きる、つまりこういうものですから、こげ付きが起きる可能性もあり得ます。その場合には、当然のことながら信用保証が付いておりますので、信用保証によって処理されるということになります。","id":"exchange-012"},{"speaker":"本田委員","kind":"意見","question":"１点だけお尋ねします。今後の見通しについてお尋ねをしておきたいと思いますとの意見を述べました。","respondent":"市川産業振興課長","answer":"今後の対応につきましては、これから一定の年数が経過いたしますと、そういったものを経年劣化がある程度まとまって出てくることが推測できます。これは直近の一つの大きな検討課題であるというふうに私どもは認識をしています。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"半分もいっていないです。もうちょっと返し方の工夫をしてみたらどうですかとか、そこだけで終わらずに、もう一つ踏み込んだご指導みたいなものもしたんか尋ねました。","respondent":"市川産業振興課長","answer":"住宅という、こういった特別な意味の場合には、融資の限度額を上げて対応している。今後その辺を配慮してはというような今のご指摘、改めて今回の廃止に伴って、私どもでどういうことができるか検討をさせていただきたいと思います。","id":"exchange-014"},{"speaker":"原委員","kind":"質問・要望","question":"２点お伺いしたいんですけれども、一つは、平成１０年と平成１１年のところから、平成１１年、平成１２年、平成１３年と極端に半減しているわけです。返済期限が４年以内、４年で皆さんは返されているということだろうと思うんですが、その状況を教えてほしいと求めました。","respondent":"市川産業振興課長","answer":"これまで貸し付けてまいりましたもの、この４年の中で、その信用保証を事故なく返済を終了しています。特に利用者の方から返済期間の延長をといったことも、これまで声としては特に私どものほうには届いてございません。","id":"exchange-015"},{"speaker":"原委員","kind":"質問","question":"区の現行制度があった中で、東京都のほうの融資制度を併せて利用するように勧めたという事例はあるんか尋ねました。","respondent":"市川産業振興課長","answer":"特に窓口にいらしたお客さんに具体的に区の制度が使えなければ、東京都の制度をというようなご案内の仕方はしてございません。都の制度を使える方は区の制度をおそらくご利用になれるというような、そういう関係が背景にあります。","id":"exchange-016"},{"speaker":"金高委員","kind":"質問","question":"例えば商店主の方々が生活資金として申し込みたいといった場合には、この対象になるんでしょうか。その辺をお聞きしたいんです。","respondent":"市川産業振興課長","answer":"原則は事業の経営者の方は該当になりません。私どもの制度でもそうですけれども、経営者の方につきましては、事業資金と生活資金の区別が非常に困難であるということが背景にあります。","id":"exchange-017"},{"speaker":"金高委員","kind":"質問","question":"これはどうしても必要なお金なので、生活資金としてとなったときに、ただ単に書類の審査上でだめになってしまう。そういう方々に対しての融資は現状ではないというような感じを受けるんですけれども、その辺はどうなんか尋ねました。","respondent":"市川産業振興課長","answer":"いわゆる小規模事業所の家族従業員は対象になるということで、そういうケースを取り扱ったこともあるということは東京都のほうから聞いてあります。ただ、一般的に、区の制度融資の中で、事業主が申し込まれるというケースはほとんどございません。","id":"exchange-018"},{"speaker":"菊地委員","kind":"質問・要望","question":"幾つかお聞きしたいんですけれども、今回の廃止の最大の理由になるのかどうか、ちょっとその辺はよくわからないので教えてほしいと求めました。ここでは書いてないので、利用条件の違いを教えてほしいと求めました。","respondent":"市川産業振興課長","answer":"２点目の、利用条件ですが、利用条件についてはほぼ変わりございません。区の制度融資とほぼ同様ないしは有利な条件ということでお考えいただければと思います。","id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"利用実績がガクンと落ちた時点からの利用が上がるような手だてをとられたのかどうか、改善を行ったのかどうか、この辺をお聞きしたいと思います。","respondent":"市川産業振興課長","answer":"まだ数字が横ばい状態であった平成１０年度から、しながわ産業ニュースには毎号このご案内を出すようにいたしました。以前に比べてＰＲの回数というようなことは増やしてきたにもかかわらず、件数が上がらない、こういった経緯がございました。","id":"exchange-020"},{"speaker":"菊地委員","kind":"質問","question":"ここで言う、逆に多重債務者そのものは増えていっているわけですから、多分区内で働いていらっしゃる方の中でも随分いらっしゃるんだと思うんです。利用実績にしても、どこかに広報の仕方として矛盾があるのではないかなというような気がするんですけれども、その辺ではどうか尋ねました。","respondent":"市川産業振興課長","answer":"平成９年、平成１０年、こういったことがはっきりしてございました。であるからこそ多重債務者の方が残ったという傾向が、どちらかというと私どもとしては強いというふうに受け止めてあります。","id":"exchange-021"},{"speaker":"本田委員","kind":"質問・要望","question":"本来、福祉が十分行き届いていないところがいまだにあるわけですから、東京都も品川区より若干条件がいいような格好で同様の制度がある。１０年などと比べると半分近く減っているんですけれども、そういう見通しはどうなのかなと思うんですけれども、どうなんか尋ねました。","respondent":"市川産業振興課長","answer":"それに基づいて制度の存続、継続いかん、それについてかなりシビアな検討を行っているということを、昨年の秋ぐらいから情報交換をしています。","id":"exchange-022"},{"speaker":"本田委員","kind":"質問","question":"労働行政が地方自治によっては都道府県、東京都が労働行政に責任を持っているということですから。同時に、将来的に全くそういうことがないというふうには言えないと思うんですが、その辺はどうなんか尋ねました。","respondent":"市川産業振興課長","answer":"東京都の類似制度があるということを大きなウェートを持ったものとして考えてあります。したがいまして、今後、委員がご指摘のように、状況が変わったときには、その時点で改めて検討をする必要も出てこようかというふうに考えてあります。","id":"exchange-023"},{"speaker":"本田委員","kind":"質問・要望","question":"要望にしておきますけれども、品川区は中小企業が圧倒的に多い地域ですから、実態はそうなっていないですね。万が一東京都が廃止などというときには、区が独自の制度を立ち上げるということも考慮していただきたいというふうに要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"堺委員","kind":"質問","question":"参考までに、借りている人たちの返済状況をつかんでおりましたらお聞きしたいと思います。融資を受けられた人がきちっと返済していれば一番いいんですけれども、その辺の状況を何かつかんでおられましたら、お聞きしたいと思います。","respondent":"市川産業振興課長","answer":"先ほど他の委員のご質問の中で触れさせていただきましたけれども、その信用保証についてこげつき、代弁済が起きたということは一事例もございません。現在、これまでの貸付件数６件の貸付が残ってありますが、いずれも滞りなく返済をしているという状況です。","id":"exchange-025"},{"speaker":"堺委員","kind":"質問","question":"全体でまだ２２件残っているということで想定しますと、その部分の今日まで区が負担をしてきた利子補給というのは年間どのくらいなんですか。例えば平成１２年度の利子補給がどの程度区が負担してきたのか。","respondent":"市川産業振興課長","answer":"年間その１％について利子補給をしている。このようなことですので、ちょっと数字のずれはありますけれども、１０万円前後の実績です。","id":"exchange-026"},{"speaker":"堺委員","kind":"質問・要望","question":"ですから、区が責任を持って利子補給をしている間は２，０００万円の基金の取り崩しはできるんですか、できないんですか。利子補給はしばらく、ですから、返済期間は４年以内ですから、場合によっては４年間利子補給を続けていく。","respondent":"市川産業振興課長","answer":"大前提は、すでに融資のあっ旋をした方については、その返済が終わるまで従来どおり利子補給は区から行います。この年度末をもってそれぞれ預託してある金額を引き揚げさせていただきたいということで、最終的に金融機関のほうは了解をしています。","id":"exchange-027"},{"speaker":"堺委員","kind":"質問・要望","question":"向こうも了解したということですから、ほかにも例があるのかどうか、どうしても銀行側に立って考えると担保として何か欲しいなという気がするんです。今金額的には年間２２件の残高ですから、１０万円前後ということですから、その辺のところをちょっと教えていただきたい。","respondent":"市川産業振興課長","answer":"１点目ですが、まさに件数が少ないので、金融機関のほうもあえて基金は残さなくて結構ですです。２番目の都の制度のＰＲ、周知の徹底ということにつきましては、ご提言を受けまして、きちんと対応をしますので、よろしくお願いいたします。","id":"exchange-028"},{"speaker":"菊地委員","kind":"質問","question":"制度の改善を含めて、この事業というのは残しておくべきものだというふうに思います。ですから、今回の条例については、私どもは反対ということになります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"本田委員","kind":"質問・要望","question":"先ほど要望を言いましたけれども、万一東京都も激減したなどの理由で制度がなくなるというような事態が生じたときには、私は強く要望しておきたい。ＰＲ等を徹底していただいて、より一層活用していただくということで、本条例については賛成の態度を表明します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"原委員","kind":"提案","question":"その２，０００万円をある意味の有効的に使うということも必要な部分だろうと思います。そういう意味では、今回の提案に賛成をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"金高委員","kind":"質問・要望","question":"そういう自己責任の範囲の中において多重債務を救うということもいかがなものかという面も若干あるという気がいたします。同じように東京都で実施している融資制度があるわけですから、ＰＲについては、賛成のほうにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"堺委員","kind":"意見","question":"利用条件の良い東京都の類似制度があるですので、東京都が廃止になれば話は別ですけれども、我々としては廃止をするという原案に賛成です。ただ、さっき申し上げたような、きちっとした周知の方法だけはお願いしておきたいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"金高委員","kind":"質問","question":"ああいう場所ですから、今まで利用していた方、特に定期的に使っていた団体の方々の活動の場がなくなってしまうということであります。その３点をお伺いしたいと思います。","respondent":"市川産業振興課長","answer":"８月、９月の２カ月を工事期間に充て、１０月から新しい展示コーナーをオープンできるよう日程調整を進めてまいりたいと考えています。先ほど冒頭の説明で申し上げましたが、なおかつ受注が増えていただければ、これは幸いだというふうに考えてあります。","id":"exchange-034"},{"speaker":"原委員","kind":"質問","question":"今、区民ギャラリーの話が出てきましたけれども、所管は違うかもしれませんが、区民ギャラリーはどのぐらい利用されているんでしょうか。区民の方々に利用していただくという意味では、利用できるんじゃないかなと思うんですが、その辺の考え方はどうか尋ねました。","respondent":"上山総務部副参事、辻田防災課長","answer":"加えて２点ほどご説明をさせていただきたいんですけれども、これまでの展示室の利用の状態等を勘案しまして、２点ほど変更をさせていただきました。具体的には、７万２，０００円にいたしまして… そういう中で、展示施設も含めまして、どのような使い方をしていかなければならないかということを検討しなさいということで考えているところです。","id":"exchange-035"},{"speaker":"原委員","kind":"質問・要望","question":"いろいろこれから検討をされるということですから、一般の方々の展示も、検討をしてほしいと求めました。ほとんど同じぐらいになるのか、それとも多少は違ってきますよというのか、その辺を説明を求めました。","respondent":"上山総務部副参事","answer":"区民ギャラリーが１万２，０００円ですので、金額的には１．６４倍になるかと思います。平米といたしましては、区民ギャラリーのほうは２００m2でありますので、床面積的には展示がしやすくなるかなというふうに考えてあります。","id":"exchange-036"},{"speaker":"菊地委員","kind":"質問","question":"観光地に行くと、子どもたちにも分かりやすく知らせていくというようなことまで含めて考えていらっしゃるのかどうか、そこをお聞きしたいと思います。それと、この辺、今実際利用している２０団体の皆さんが使えるような感じの検討ができるのかどうかというのをお聞かせ願いたいと思います。","respondent":"市川産業振興課長、辻田防災課長","answer":"１点目の、小学生が来館した際の対応に関することですけれども、そういった仕掛けを取り入れていくことを考えてあります。２点目に関連して、私どものほうから説明をしますが、内容はそれぞれ多様です。 そういう中で検討をしていくということを基本的には考えてあります。どういう形で広げていくか、そういうことを基本的なスタンスで考えて検討してまいりたいというふうに考えてあります。","id":"exchange-037"},{"speaker":"菊地委員","kind":"質問・要望","question":"１点だけ、今の展示室が７，３００円で、区民ギャラリーが１万２，０００円は相当な負担になりますよね。これで二、三日使うとなると１万円近くなるということですけれども、展示室並みの値段に落としていくというのは考えられないか尋ねました。","respondent":"上山総務部副参事","answer":"金額自体は確かに１．６４倍ですけれども、平米数でいたしますと、現在の展示室よりは単価的には落ちております。ですから、平米との関係を考えますと、現行での１万２，０００円ということでの判断をさせていただきました。","id":"exchange-038"},{"speaker":"菊地委員","kind":"質問","question":"中を区切って、半分半分で使用させるとか、そういう形というのはとれないものですか。それで利用料を半分ぐらいにしちゃうとか。","respondent":"小栗区民生活事業部長","answer":"産業振興課長、上山総務部副参事のほうでご説明したとおり、今１１３m2です。こういう中で、先ほど上山総務部副参事のほうからご説明したとおり、平米単価でいくと、むしろ下がっているんですね。","id":"exchange-039"},{"speaker":"菊地委員","kind":"意見","question":"述べておきたいんですけれども、先ほど２０団体の皆さんと十分話し合いをしていくということでありましたので、納得いくかどうかは別としても、十分そうした団体の皆さんと論議をして方向性を決めていっていただければというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"本田委員","kind":"提案","question":"部分的には本条例提案前に利用者と話がされているのかなと思うんですけれども、事前の相談といいますか、その辺はどういう掌握をされているのか。事前の利用者の意向掌握というのがされているのかどうなのか、もう一度お尋ねしたいと思いますとの意見を述べました。","respondent":"市川産業振興課長","answer":"これまで展示室を利用いただいてまいりました各利用団体の方に直接事情を説明して、それぞれの意向を聞くということはしてございません。そのようなことで、本委員会の審議を踏まえまして、早速２０団体の皆様方に事情を説明してまいりたいというふうに考えてあります。","id":"exchange-041"},{"speaker":"本田委員","kind":"提案","question":"区民の皆さんにもっとＰＲをしたらどうですかというご提案をしたこともありますけれども、今回、より一層中小企業振興に供したいということですから。","respondent":"市川産業振興課長","answer":"今後利用団体の方に展示室の廃止の趣旨を説明させていただきながら、一方で、代替案についてできる限り説明をする。このようなふうに考えてあります。","id":"exchange-042"},{"speaker":"本田委員","kind":"質問・要望","question":"伝統産業の商品、技術、あと映像でやっておりました。ぜひそういう意味では拠点にふさわしい、中小企業の発信拠点として充実していただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"堺委員","kind":"質問・要望","question":"かなり共通した要望、意見が出ておりますので、私もそのとおりであると思います。利用可能と思われる他の施設も区内にはあるわけですから、中小企業センターは下神明駅の近くですから、ご利用されていた方がなるべくそこのところ。","respondent":"市川産業振興課長","answer":"約２，１００万円計上しています。","id":"exchange-044"},{"speaker":"堺委員","kind":"質問・要望","question":"必要な場所、必要な施設というふうに、私は個人的には思います。重ねて誠意を持って対応していただきたいということを要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]},{"id":"topic-02","title":"第２１号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第２１号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"本田委員","kind":"質問・要望","question":"第１号被保険者が１７％、そうすると、この割合はどうなるんですか。要するに、今の品川区の５段階の保険料はどうなっているのかなというふうにちょっと思ったもので、そこの関係をご説明ほしいと求めました。","respondent":"太田保険年金課長","answer":"１年１年国のほうで給付総額の見込額を決めて、自己負担を除いて、給付総額の３３％に相当する額を第２号被保険者の負担という部分で算出をします。","id":"exchange-046"},{"speaker":"本田委員","kind":"意見","question":"３年間、介護保険のほうの若干のあれは出てきても、介護保険はいじらないと。３年後に見直しをやるということで、第１号被保険者にもそれが影響してくるのかなというふうに思うんですけれどもとの意見を述べました。","respondent":"太田保険年金課長","answer":"そうしますと、平成１２年度の国が見込んだ実績よりも給付実績が全国で８５％ぐらいだというふうになっていて、その分の清算が今年入ってくる。それから、保険料の部分、第１号被保険者については、各介護保険者がそれぞれの給付実績を見込んで算定をしているです。","id":"exchange-047"},{"speaker":"菊地委員","kind":"質問・要望","question":"もう１点は、資料の５ページにある、所得不明世帯というのは、具体的にどういうものか。ちょっと事例を挙げていただければ、どういう世帯なのかということを教えてほしいと求めました。","respondent":"太田保険年金課長","answer":"それから、資格証のほうですが、現在の数でいきますと、正確な数字は忘れたんですが、三十四、三十五件だと思います。約１万５，０００世帯、この滞納世帯という理解は、１期でも履行期限を遅れた方々ということで理解をしております。","id":"exchange-048"},{"speaker":"菊地委員","kind":"質問","question":"滞納世帯１万５，０００ぐらいという、払えなくて、短期証になったのかな。１００万円ぐらいの料金を請求されて、こういうような事例というのは区のほうに何か届いているとか、相談があったとかというのはないか尋ねました。","respondent":"太田保険年金課長","answer":"通常、資格証を出す前に、何回か滞納されている方に対して通知というものを差し上げてあります。生活状況等のご相談すべき内容があれば、こちらのほうへお電話なり、来庁なりしていただければということでの部分の通知を差し上げているところです。","id":"exchange-049"}]},{"id":"topic-03","title":"第２６号議案、品川区地球環境リサイクル基金条例の一部を改正する条例","agenda":"第２６号議案、品川区地球環境リサイクル基金条例の一部を改正する条例","exchanges":[{"speaker":"金高委員","kind":"質問","question":"３月２０日ということですから、それをどういう形で運用益をさらに活用していくのか、活用の内容等を具体的にお話しほしいと求めました。","respondent":"金井環境課長","answer":"これで国債を買っておりますけれども、同様に国債を買う予定という状況になってあります。したがいまして、５００万円の運用益金が見込まれるという状況にあります。","id":"exchange-050"},{"speaker":"原委員","kind":"質問","question":"どこから１０億円が出てきたんですか。要は、１億円がなぜ１０億円になったんか尋ねました。","respondent":"金井環境課長","answer":"どのぐらいなら来年度の中で地球環境リサイクル分に充てられるかというような中から１０億円という形が出てきたというふうに考えております。０．５％、０．６％ということもあるようですが、現在の見込みでは０．５％という見込みだというふうに聞いてあります。","id":"exchange-051"},{"speaker":"原委員","kind":"質問・要望","question":"多分そういう意味では、運用益を逆算して、事業量がこのぐらいあるからと概算するのがおそらく１０億円だろうという話だと思うんです。０．５％の高いほうの利息ですからね、厳しい内容なのかなと考えていますけれども、全体に頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"菊地委員","kind":"質問","question":"例えば来年度ノーレジ袋運動を新たにやるということです。事業に対する５００万円という予算の組み方でもいいような気がするんですけれども、ノーレジ袋運動をやるという、どうか尋ねました。","respondent":"金井環境課長","answer":"これは毎年度本当に必要かどうかチェックをしてまいりますので、安定的とは言えないわけです。皆さんの承認を得ないと変更できませんので、安定的に確保してまいりますよという、そういうふうにご理解をいただければと思います。","id":"exchange-053"},{"speaker":"金高委員","kind":"質問・要望","question":"それにプラスすることの運用益が入ってくるわけですから、なおかつそれを入れた上での総合的な環境予算という形でもって予算編成を組むのか。それの枠組みを教えてほしいと求めました。","respondent":"金井環境課長","answer":"私どもの予算の中に財産運用という形で入ってまいります。そういう形で環境課の予算のところに入ってくるという形になってあります。","id":"exchange-054"},{"speaker":"堺委員","kind":"質問","question":"当初１億円の積み立ては平成４年３月ですか、それ以降１０年近くなかったのに、ここへきて９億円を積み立てて１０億円と。さっきのどなたかの質問と似通っているかもしれないんですが、その辺はどうしても、それが強いのでということになってくるんか尋ねました。","respondent":"金井環境課長","answer":"平成４年ですので、地球環境リサイクル基金を増額するというチャンスといいますか、考え方は全くないわけではなかったと思います。そういったタイミング的に今が一番適切な時期ではないかなということで、今回９億円を増額するです。","id":"exchange-055"},{"speaker":"堺委員","kind":"質問","question":"使われ方が、先ほどのお話のことだけになるんですか。それなりの事業の拡大というのも可能になってくると思いますが、その辺はどうか尋ねました。","respondent":"金井環境課長","answer":"私ども予算は５００万円では足りませんで、特にこうした運用益金はＰＲ事業に主に使ってまいりたいと思います。あるいはそういったものの事業にもまだ満たない額ですので、大きな拡大の原資というようなものまではいっていないです。","id":"exchange-056"},{"speaker":"堺委員","kind":"質問","question":"仮にこれが５年、１０年と続けていく事業というふうになった場合、３，２００万円というのを常時していかなければならない。ようやくここまでプラスで１０億円までこぎつけたのを、あと１０万円プラスするとか、１０億円でいいんだとする理由を説明を求めました。","respondent":"金井環境課長","answer":"原資が５０億円でもあって、それは区の全体の財政状況と、環境だけがすべて重要政策でございません。それはどこの部でもそういう思いはあると思いますが、そういうことでご理解いただきたいと思います。","id":"exchange-057"},{"speaker":"本田委員","kind":"質問・要望","question":"代表質問で今のお話を伺ったわけですが、それから、限られた予算の中で思い切った手を打ったというふうに私は理解しているんです。ですから、５０億円とか、また政治姿勢として今後担保できるような努力もしていっていただきたいというふうに思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"菊地委員","kind":"質問","question":"私のほうは、一般質問でもちょっと伺ったんですけれども、区内地域の金融機関の状況というのはこの１年間で物凄く変化をしていると思うんです。この３点ぐらいが私としては聞きたいところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"原委員","kind":"質問","question":"ＩＴについては、工業の活性化の中では述べられている話ですから、それは聞いてもよろしいではないかというふうに思います。大型店のところも、絞っていただいて、その中でのお話のほうがいいんじゃないかというのが私の意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"南委員長","kind":"質問","question":"私も個人的には非常に関心を持ち、伺っておきたいというふうに思っておりましたので、そこはぜひ項目に載せていきたいというふうに思っております。課長のほうからというふうに、そういう運びにして、締めくくっていいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/345074?Template=document&Id=2318#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":45261,"voices":144}},{"id":"h14-20020304-7","meetingId":"h14-cm03","date":"2002年3月4日","dateIso":"2002-03-04","committee":"厚生委員会","time":"午前１０時０６分～午後２時１９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件整理しています。","topics":[{"id":"topic-01","title":"第２２号議案、品川区生業資金貸付条例および品川区応急小口資金貸付条例の廃止に伴う貸付金債権に係る償還金等の減免等に関する条例を廃止する条例","agenda":"第２２号議案、品川区生業資金貸付条例および品川区応急小口資金貸付条例の廃止に伴う貸付金債権に係る償還金等の減免等に関する条例を廃止する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっとお聞きしたいんですが、現在これにかわるような制度というのがどういうものがあるのか、ちょっと教えていただきたいんですが。","respondent":"黒田生活福祉課長","answer":"それで、現在その制度について詳しいものをこちらのほうでつかんでございませんけれども、それにかかわるものについて、受け皿は用意しています。低所得者等、一部が中小企業のほうの制度に移行したですので、低所得者に対する制度については受け入れがされていると考えています。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここのところに、世帯更生資金制度というのが受け皿としてあるのでということで書かれているんですが、これは今でも実際にこの制度というのはどうなっているのか、ちょっと教えていただきたいんですが。","respondent":"黒田生活福祉課長","answer":"世帯更生資金というのが社会福祉協議会で、その当時は世帯更生資金でございましたが、現在はそれが生活福祉資金と一本化されてあります。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その廃止された後も中小の方からは５０万円あれば何とか助かるというふうなところで生業資金復活という要望がずっと長い間出されてきたと思うんです…もう既に条例そのものが廃止されているというところですので反対するものではありませんけれども、そのことだけ述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"２番目の第２３号議案、品川区母子生活支援施設条例の一部を改正する条例","agenda":"２番目の第２３号議案、品川区母子生活支援施設条例の一部を改正する条例","exchanges":[{"speaker":"鶴副委員長","kind":"質問","question":"そこに入所している人ということではなくて、違うわけですけれども、何かアドバイスというか注文をつけることが可能なのですか。その点をお聞きしたいんですが。","respondent":"谷田部児童課長","answer":"委託契約です。それにつきましては、雇用している福栄会のほうが、その辺の職員の処遇についていろいろ考えていくというふうな関係になろうかと思います。","id":"exchange-004"},{"speaker":"鶴副委員長","kind":"質問","question":"そうすると、この施設のありよう、例えばそのあんしんセンターにしても、本体の母子生活支援施設の事業も含めて、この社会福祉法人がその任に当たる、こういうことになるわけか尋ねました。","respondent":"谷田部児童課長","answer":"４月１日に仮施設の運営を先行してまず委託をする。それから９月には新しい施設ができますので、今回４月１日から仮施設の運営を先行して委託するです。","id":"exchange-005"},{"speaker":"鶴副委員長","kind":"質問","question":"即に短絡的というんでしょうか、サービスの低下につながるんだとかいう論調が必ずと言っていいほど起きてくるんですね。そういうことのないようにお伺いしておきたいというふうに思います。","respondent":"谷田部児童課長","answer":"現在、私ども母子生活支援施設ひまわり荘での運営といいますのは、夜の処遇について対応が十分できていなかった。これはあくまでも母子の自立を支援する施設ですから、既に区内の社会福祉法人、職員体制につきましても柔軟な対応がとれるというような観点から。","id":"exchange-006"},{"speaker":"鶴副委員長","kind":"質問","question":"そういういろいろ機能が違うんですけれども、でも、すべてのことについてはこの社会福祉法人に委託するんですよということになるのでしょうか。そこらあたりのことの進め方というのはどういうふうになるんか尋ねました。","respondent":"谷田部児童課長","answer":"母子保護の実施というのが児童福祉法第２３条ですけれども、これは母子相談員、児童課に置いてあります。ですから、母子保護の実施後すべてを福栄会の委託ではなくて、これは、法律上、福祉事務所が入所を決定するという手続は当然私どもが担っていくです。","id":"exchange-007"},{"speaker":"鶴副委員長","kind":"質問","question":"管理運営ですから。これは老婆心に終わればいいがなというふうには思っているんですが、いかがか尋ねました。","respondent":"谷田部児童課長","answer":"そういう中でいかに自立に向けた支援がこの施設の中でできるかどうか。これは私どもも通常の指導を通じながら、福栄会のほうにその辺のないような形で指導していきたいというふうに思ってあります。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"要するに福栄会が委託をされて、収入をどこから福栄会として得て、当然運営していくわけですから、お金をどこかからもらわなきゃいけない。それがどういう項目で福栄会のほうにお金が行くのかということと、あと、委託方法について教えてほしいと求めましたので。","respondent":"谷田部児童課長","answer":"今年度中に１４年度を通した基本協定を結びまして、福栄会のほうも定款変更等、それをもとに福栄会のほうでは準備に入っていく。事細かに規定した契約書、それから仕様書を作成いたしまして、契約書を締結するという段階で今現在準備をしているです。","id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問","question":"だから、直営でやるのも委託料の数字も出てくるわけじゃないですか。となれば、その差額がどれぐらいでしょうかということも、もしわかれば教えてくださいということです。","respondent":"谷田部児童課長","answer":"それで、仮施設から９月以降をにらんで、私ども職員配置というのは国の最低基準、いわゆる国が支弁費として区のほうに来る算定で私どもは組んです。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回、なぜ福栄会という社会福祉法人なのかということを１点お聞かせいただきたいんですが、１点お聞かせほしいと求めました。区のほうで福祉事務所とかがかかわるというふうなのは先ほどの説明でわかったんですが、ここのところについて一つ教えてほしいと求めました。","respondent":"谷田部児童課長","answer":"やはり複数の施設相互間で横断的連携がこの運営の成否を左右するのではないかということと、２点目といたしましては、そういう能力があるかどうか。そういう意味では職員の配置も柔軟に対応できる、それから新たなニーズに対応できるというのが、効率的な運営ができるです。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この児童虐待、児童虐待等防止連絡協議会の設置をしてネットワークもつくっていくということも、子育て支援センターの中には入っていますよね。本当に専門家のいろいろと支援というか、ここら辺のところについてはどうなっていくのかというところをちょっとお聞かせいただきたいんですが。","respondent":"谷田部児童課長","answer":"品川区子育て支援センターの一つの仕事として、児童虐待等防止連絡協議会、これを設置する予定です。それから私どもが今のところ考えていますのは、それから主任児童委員、そのような協議会を構成していくということで現在準備をしているです。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当にさまざまなノウハウが求められるところだと思うんですが、ほかの２３区の中でも直営でやっているところが多いというふうにお聞きしたんですが、ちょっと２３区の状況をつかんでいるところがあったら教えていただきたいんですが。","respondent":"谷田部児童課長","answer":"母子生活支援施設での直営、参考までに母子生活支援施設はどういう状況で運営されているかどうか、公立公営で行っていますのは４カ所です。それから民立民営、これは１６カ所ということでなってございまして、公立公営というのは極端に少ないです。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは全体の家庭あんしんセンターの施設概要の５事業がすべて福栄会に委託されるということでの条例というふうなことではないんでしょうか。改めて、ほかのところはほかのところで条例という形で出てくるのかどうか、ちょっと教えていただきたいんですが。","respondent":"谷田部児童課長","answer":"今回条例改正をお願いしていますのは、品川区母子生活支援施設条例というのが西五反田の仮施設のことを指しています。これは地方自治法上の規定がありますので、その地方自治法の規定に基づきまして、今回条例改正案をお願いしているです。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それ以外のところは、また新たに条例という形で出てくるんか尋ねました。","respondent":"谷田部児童課長","answer":"新しい施設がたくさんまた９月に入るということで、新施設の新たな条例というのは第２回定例会でご提案申し上げるべく、ご理解のほどをお願いいたします。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ちょっと私はこれ全体のかなというふうなところで勘違いをしていた部分がありましたので、その点についてはわかりました。この体制が、福栄会になったときに職員体制がどういうふうになるのかということについて、説明を求めました。","respondent":"谷田部児童課長","answer":"それから少年指導員兼事務員が１人、それから調理員等で１人、それで嘱託医を１人置くということで５人で体制を組む。これは国の支弁費の計算による職員体制で行っていくです。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"現在は５人職員がいるというふうに思っていたんですが、現在の体制と今度の体制の違いについて、ちょっと説明を求めました。","respondent":"谷田部児童課長","answer":"現在、嘱託医を除きまして６人で担当しています。ただし、そのうちの１人はですね、新施設の改築担当ということで別途つけてありますので、実質的には同じ数だです。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、嘱託医を含めて５人なんですか。嘱託医以外に５人ということでお聞きしたと思うんですが、私はやはり直営で引き続きやるというのが必要なんじゃないかなというふうに思っています。","respondent":"谷田部児童課長","answer":"２０世帯の今度、加算分というのが出てまいりますので、そのときにはまた人数が変わってまいります。参考までに申し上げますと、平塚に戻った場合には２０世帯の定員になりますので、嘱託医を除きまして７人での運営です。","id":"exchange-018"},{"speaker":"須藤委員","kind":"意見","question":"第２回定例会でまたぴしんといろいろ含めますと言うんだけれども、母子支援という言葉を使わないといろいろ補助金とかその辺がおりてこないのかどうか、その辺のお考えを聞かせてくださいとの意見を述べました。","respondent":"谷田部児童課長","answer":"今のご質問ですけれども、今回は、これは児童福祉法に基づく母子生活支援施設ですので、その名称をそのまま条例に持ってきてあります。今年の９月に新たに設置するのは品川区家庭あんしんセンター子ども未来館ということで考えてございまして、そのような名称を考えているです。","id":"exchange-019"},{"speaker":"須藤委員","kind":"質問・要望","question":"やはりこういう時代ですから、僕らがいろいろな相談を受けるときに、現在ではいろいろな手当の仕様がなかなか今ないんですね。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"嶋委員","kind":"質問・要望","question":"それとも２４時間体制、緊急時２４時間体制にどういうふうにこれが生かされていくのかということと、期間を教えていただきたいことと。母と子が一緒でなくてはだめなのか、別々でもオーケーなのか、その辺をちょっとお聞きをしたいと思います。","respondent":"谷田部児童課長","answer":"私どもその辺は役所の開庁時間外にそういうような状況があった場合にも対応せざるを得ない状況には来ているというふうに思ってありますので。","id":"exchange-021"},{"speaker":"嶋委員","kind":"質問・要望","question":"今まで報告をいただいた児童虐待を含めたあらゆる相談を２４時間ということで、そうじゃないことが今わかりましたので、ありがとうございました。短期と言いますが、区側としては短期はどのぐらいの目安として考えていらっしゃるのか、およその目安を教えてほしいと求めました。","respondent":"谷田部児童課長","answer":"三日ぐらいで考えて、いわゆる代替処遇しているというのが、これまでの経験です。１週間、１カ月、いろいろその方に応じた処遇方針というのを考えていくという関係になろうかと思います。","id":"exchange-022"},{"speaker":"船波委員","kind":"質問","question":"母と子が別々の場合は別のところでというような感じのご説明がありましたけれども、それではドメスティックバイオレンス対応はどうなるんでしょうか。そういった方への相談であるとか、そういった機能はないというか、ほかになるんか尋ねました。","respondent":"谷田部児童課長","answer":"いわゆるシェルターのほうをご案内したり、それから私ども民間の施設も借り上げていますので、そういうところで現在対応しているです。ただ、子どもを連れていることによって、子どもの健全育成が損なわれるからこういう施設があるんだということでご理解いただきたいと思います。","id":"exchange-023"}]},{"id":"topic-03","title":"３番目、第２４号議案、品川区立児童センター条例の一部を改正する条例","agenda":"３番目、第２４号議案、品川区立児童センター条例の一部を改正する条例","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"ということは、現在はここに子どもは行っていないんでしょうかということが一つ。ちょっと議員としてどうなのかなという素直な思いもありますので、その辺の見通しとか考え方について、教えてほしいと求めました。","respondent":"谷田部児童課長","answer":"これは、いわゆる３月末までかかる予定ですが、ただ３月には八潮北学童保育クラブの中で卒会式を行ってほしいという要望を受けてあります。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だからといって、そういう立ち入り許可という名目で、じゃあ議会の先にそういうふうなことをしていいんでしょうかという疑問はついて回りますので。こうしてほしい、ああしてほしいとか、それからいろいろ中には残してほしいという方もいるかもしれませんけれども。","respondent":"谷田部児童課長","answer":"それから、１０月に行いました八潮と八潮北学童での合同の保護者会です。その後は子どもの数に応じてクラス編成は私どもがしたいというお話をしましたら、それに対して特段ご意見がなかったということが実態です。","id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問・要望","question":"先ほど副委員長も質問していましたけれども、十分そういうふうなそごがないように、十二分な説明をお願いしたいと思います。いろんな、そんなことも含めて大きな視野で検討していってくださいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"嶋委員","kind":"質問・要望","question":"先ほどの今の流れの中で北の名前を残してほしいという意見があったようですが、この４月からの新しい統合した後のネームは決まったんでしょうか。もし決まったら教えてほしいと求めました。","respondent":"谷田部児童課長","answer":"本体そのものの名称は変更する考えはございませんが。４月以降のクラスの名前につきましては、それからシリウスということではなくて、どういう形にするかは今現在考えているです。","id":"exchange-027"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう意味では、地域的にはちょっと子どもさんの安全を心配している方もいらっしゃるので、そういう点はどのように考えていらっしゃるかお聞かせほしいと求めました。","respondent":"谷田部児童課長","answer":"統合したから特別にこういうことをしろということは特段指示はしてございませんが、基本的には子どもの安全確保が第一ですよということは当初から言ってありますので、今現在まで大きな問題にはなっていないです。","id":"exchange-028"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"この跡地の約５００平米の施設と品川総合福祉センターとの関係はどういう形になるのでしょうか。貸与するとしたら有償なのか無償なのかを含めまして、どういう関係になるのか、まずお聞かせいただきたいというふうに思います。","respondent":"日下部障害者福祉課長","answer":"これを受けまして、品川総合福祉センターがこの新施設の設置運営の主体になる。簡単に言いますと、民設民営の施設としてこれから運営をしていく、こういう内容です。","id":"exchange-029"},{"speaker":"鶴副委員長","kind":"意見","question":"この更生施設は、これは否定しませんが、品川区のこれは要するに行政サイドから見ましたこういった知的障害者の通所更生施設ですね。","respondent":"日下部障害者福祉課長","answer":"この品川総合福祉センターの施設については、基本的にすべて設置運営の主体が品川総合福祉センターです。こちらに入所者、まずは２０名で出発いたしますけれども、現行の品川総合福祉センターが持っているほかの障害者施設と同じような形になっております。","id":"exchange-030"},{"speaker":"鶴副委員長","kind":"質問","question":"そうすると、今まではですね、品川区が最初建てた施設ですから、水道、光熱等の配線も一体となっているんじゃないかと思うんですよ。どういう条件がつけられているのか、無償貸与の条件がどんなのが今現在つけているのか、あるいはつけていないのかですね。","respondent":"日下部障害者福祉課長","answer":"１点目の光熱水費の関係につきましては、今回の改修工事にあわせて、今までは一緒でしたが別メーターということで工事を一緒にやってまいります。基本的には３０年程度、この辺が目安になるんではないか、このように考えております。","id":"exchange-031"},{"speaker":"鶴副委員長","kind":"質問","question":"ちゃんと公有財産ですから戻してくださいよというようなことをやっぱり覚書なら覚書、無償貸与の契約条件というか、こういう点を一つ思うんですね。この点どうか尋ねました。","respondent":"日下部障害者福祉課長","answer":"ただ、必ず契約の場合、見直しといいますか、更新についての条項を必ず盛り込んでまいります。しっかりその時点で検証した上で見直しをしていく、それを更新条項として盛り込んでいく、そのような形になってまいります。","id":"exchange-032"},{"speaker":"鶴副委員長","kind":"確認","question":"この措置という言葉を使っていいのでしょうか、選択ということになるんでしょうか、窓口ですね。担当する課が行うんですよ、こういうことに、どういうふうな仕組みに流れがなるんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"それで、開設から１年間は、少なくとも従来どおりの措置制度ということで進めてまいります。それから、そういうことで１５年の４月以降はそれぞれ利用者の選択制度ということで変わってはまいります。","id":"exchange-033"},{"speaker":"船波委員","kind":"質問","question":"は、その子どもたちを見る職員の方々はどうなっているんでしょうか。八潮北でその子どもたちの対応していた方が、今度からは八潮学童勤務になるということなんか尋ねました。","respondent":"谷田部児童課長","answer":"職員の数で言えば、八潮北の職員を、数はそのまま八潮のほうに移して、一定程度安定的になるまで私どもはその人数は確保して、１４年度は運営するように準備しているです。","id":"exchange-034"},{"speaker":"船波委員","kind":"質問","question":"１５年度以降は、その八潮学童の子どもの数に応じてというふうになるんか尋ねました。","respondent":"谷田部児童課長","answer":"１５年度以降の人員体制というのは１４年度の状況を見ながらやっていくわけですので、その辺はまたその年度年度のお子さんの状況を見ながら、私ども職員体制は確保していくです。","id":"exchange-035"}]},{"id":"topic-04","title":"４番目の第２５号議案、品川区プールの管理に関する条例の一部を改正する条例","agenda":"４番目の第２５号議案、品川区プールの管理に関する条例の一部を改正する条例","exchanges":[{"speaker":"鶴副委員長","kind":"質問","question":"現在ですね、品川区には称するところのプールというのは何カ所あるんですか。民間が幾らで区営、直営が幾らというふうに。","respondent":"田中健康課長","answer":"いわゆる許可を必要とする民間プールは１８カ所、それから学校プールは６７カ所、合わせまして８５カ所が区内にあるこの対象となるプールの数です。そのようにご理解いただきたいと思います。","id":"exchange-036"},{"speaker":"鶴副委員長","kind":"質問","question":"それで、今までにこういった経営者がかわるとか、あるいは相続をしたというような事例は起きたんですか。起きていなかった、あるいはこれからは起きる可能性があるという前提に立って、こういう詳細な条項を３条の２として加えた、こういうことか尋ねました。","respondent":"田中健康課長","answer":"分割というのは、平成１２年の商法改正によりまして、地位の承継がいろいろな事業について行われるというような内容で起こった事象です。それが商法の改正等によりまして、こういうプールの経営につきましても届け出で承継ができるという内容になったものです。","id":"exchange-037"},{"speaker":"鶴副委員長","kind":"質問","question":"ちょっと関連してお尋ねしておきたいんですが、これは厚生労働省令ですか、現状ですね。ちゃんとそれぞれの区営のプールはやっていると思うけれども、民間を含めてどういう事情なのかと、ちょっとお知らせいただけませんか。","respondent":"大沢品川区保健センター衛生課長","answer":"それで、水質基準については５項目ばかりあります。いわゆる経営者はこれを毎月１回やるものとか、こちらでも監視をしている、そういうところです。","id":"exchange-038"},{"speaker":"鶴副委員長","kind":"質問","question":"これは後で資料でその５項目等についてもいただければありがたいなと思うんですが、耳ぐらいに入るんでしょうか、毛穴からはなかなか。というようなことが起きたというような報告があるんか尋ねました。","respondent":"青山品川区保健センター所長","answer":"感染症一般ではなく、プールを介して伝染するような疾患については、これを禁止するということに改めたものです。したがって、主としてプール熱と言われる咽頭結膜熱の問題になってまいります。","id":"exchange-039"},{"speaker":"鶴副委員長","kind":"意見","question":"その水質、そのプールの水に含まれる薬品が原因で消毒等をやりますね。薬品でそういう結膜熱になるのか、要するに疾病というか疾患、それが起こる原因は何なのかということなんですねとの意見を述べました。","respondent":"青山品川区保健センター所長","answer":"病原体による感染によって起こるものですので、水質その他ではございません。病原体があって、それでここで遊泳を通じて感染のおそれのある感染症というものを禁じているところです。","id":"exchange-040"},{"speaker":"鶴副委員長","kind":"質問・要望","question":"もう１点お伺いします。そういう仕組みにはまたなっていないということか尋ねました。","respondent":"青山品川区保健センター所長","answer":"次の各号に掲げる措置を講じなければならないというのが第５条にございまして、その中で、その他を入場させないこととなっております。特に責を求められる、あるいはプールの先ほど申しました水質基準を守っている限りにおいては、責を問われるということはございません。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"実際、高齢者の方々が食うものも食わずに貯金をせざるを得ないという厳しい実態を考えて５００万円というふうに提案するものです。予算については予算特別委員会で提案をしますので、その場でご審議をいただければと思うんですが、考え方だけ説明をさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"伊藤委員","kind":"確認","question":"何点かお伺いしたいんですが、当然なさったと思いますが、その区側の説明はどうだったのかということをお聞かせをください。確認したいのは、予算額の全体とか対象人数をここでは説明しなくて、ただ条例だけを通してくださいという考え方なんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"理事者との調整ということですけれども、これは２月２０日でしたけれども、区長のほうに申し入れを行い、助役に対応をしていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"伊藤委員","kind":"質問・要望","question":"私が聞きましたのは、区長に申し入れをして、どういうことだったでしょうか。そのことを教えていただきたいのと、こういう全体の予算はこうですよと、それから対象人数がこうですよと説明があったんでしたら話は別ですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"こういうふうにこういう条例を提案をいたしますという、そういうふうなことを出しますという、そういうふうな申し入れで行いました。そこの中で詳しくはやってほしいと求めましたが、介護給付費準備積立金という名前だったと思うんですが、その減額で十分可能だということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"伊藤委員","kind":"質問","question":"その総額とか人数がわからない条例を今審査しろという話ですから、それはちょっと理解できないということを意見を述べします。むしろいろいろ条例案ではなくて、具体的な社会経済情勢の変化に十分に対応できると思っているんですけれども、そのことについていかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"規則を変えるというふうなところでは、議員の規則改正の提案権というふうなのはありませんので、議員の提案権というふうなところで条例にかえるということで、こういうふうに今回の条例提案になったものですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"伊藤委員","kind":"質問","question":"数字を変えるだけですから。だから、それをわざわざ条例ではなくて、理事者と共産党の話し合いの中で変えなかったんでしょうかということをお伺いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そのことについては、共産党がこういうふうな提案をしたから、理事者が、じゃあわかりました、即やりましょうということになるという問題ではなかったために、議員提案ということで今回の条例提案になったわけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"伊藤委員","kind":"提案","question":"今日の提案の趣旨としては、この条例を各会派の同意で可決をしていただいて、それをもって規則の改正を改めてお願いするという形なんですね。もしそれが難しければ、はじめから一人でやったほうがいいのではないかという意見を最後に述べしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"須藤委員","kind":"質問","question":"介護保険の意義というのは、どういう意義で介護保険制度が発足したんでしょうか。いわゆる市区町村にいろいろな通達、こうしたほうがいいというようなお話があったと思うんですが、その辺についてお聞かせ願いたいと思います。","respondent":"早津高齢福祉課長","answer":"それから、収入のみによって一律に判断をしないようにというのが２点目です。それから、３点目は減額した保険料の分については一般財源を投入しないように、保険制度の枠内で行うようにという３点です。","id":"exchange-052"},{"speaker":"須藤委員","kind":"質問","question":"今日本で介護保険制度が入っているというのは、３年後にまた見直ししてというような、その手直ししながらというような形で進んでいると思うんですね。みんなで支えるというような考え方から行くと、どこかへしわ寄せが行くというふうに考えますけれども、理事者のほうはいかがか尋ねました。","respondent":"早津高齢福祉課長","answer":"保険料をある層の方に減額をすれば、それは別な方のほうに上乗せされてくる、こういう構成です。","id":"exchange-053"},{"speaker":"須藤委員","kind":"質問","question":"ここで鈴木議員にもう一度お聞きをしますけれども、もう一度なぜここで条例をしなきゃいけないんだと、きれいな形ができています。後は運用で、規則のところでできるというふうに踏まえてあるのを、なぜあえてここで条例化してくるというふうな考え方を持ってきたんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そういう方ですから、こういう実態になったわけですから、やはり議員の提案というふうな形で議会が一致して。規則の提案というふうなことができるのであれば、条例の提案というふうな形になったわけですが、今回の提案になったわけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"須藤委員","kind":"質問","question":"ですから、そういった意味から言って、ある程度のどうしようもないというところは、昨年規則のところで対応してもらった。他の保険者に対して、その辺のところで、この条例に対しては非常に全体的から見るといかがかなというような考え方を持っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"鶴副委員長","kind":"提案","question":"こういうことですけれども、なぜ、どういう理由でその１４４名にとどまったというふうに詳細には分析されているわけですか。どういう条件が厳しかったからか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういうふうなことが一切加味されなくて、やはり生活保護基準をかなり下回っているという厳しい収入だということが第１点です。それと、いつどうなるかわからないという不安をたくさん持っているわけですけれども、ここのところの拡大というふうなところで考えたという次第ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"鶴副委員長","kind":"質問","question":"私がお尋ねしたのは、どうして、そういう条件が厳しいのはどことどこがどう厳しくてということを分析されているんですかと聞いたのですよ。どういう見込みでこの１４４名なら１４４名に、数字が違うんだったら訂正してほしいんですが、その１４４名にとどまった理由。","respondent":"早津高齢福祉課長","answer":"貯蓄のたぐいについては、そちらのほうが一体どのくらいの、３００万円という一定私どもとしては余裕のある数字というふうに考えてありますけれども。その結果、申請された方が１４４名と、こういうことですので、そういうものかというふうに受けとめているところです。","id":"exchange-059"},{"speaker":"鶴副委員長","kind":"質問","question":"ところで、低所得者というのはどういうことを言うんでしょうか。説明していただけませんか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"介護保険が始まってからも３％で受けられるというふうな、収入基準はたしか２３５万かそれぐらいになるんじゃないかなというふうに思います。ここに書いております低所得者ということに関しては、ここに書いてあるとおりですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"鶴副委員長","kind":"質問","question":"したがって、現行で言うですね、介護保険制度で言う原則的なその低所得者というのは、どこのところを指してそういうふうに言っているのですか。あなた方共産党はどういう定義に基づいて要支援だなという、低所得者という、どう認知されているかということを聞いたのですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"今回の提案についての低所得者という考え方は生活保護基準です。それまでの区の提案というのは、それに達していないという状況だったので、生活保護基準まで引き上げるということで考えたのが今回の提案の中身ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"鶴副委員長","kind":"質問","question":"要するに市町村民税の非課税世帯のことを原則として低所得者というふうに位置づけているというふうに私は思っておるんですが、どうですか。理事者に聞きます。","respondent":"早津高齢福祉課長","answer":"制度の中で明確に低所得者云々という形ではございませんが、保険料につきましては、周知のとおり５段階に所得等に応じまして分かれてあります。第２段階が世帯全員が住民税非課税というような形での５段階が出ておりまして、それはおのずと収入の差が反映された制度です。","id":"exchange-064"},{"speaker":"鶴副委員長","kind":"質問","question":"これはどういう概念ですか。生活保護法に基づいてお話ししていただけませんか。","respondent":"黒田生活福祉課長","answer":"それとあと資産調査をしますので、資産があるかないか、その基準以下の方が要保護世帯ということで見ます。ですから、収入が少なくても預貯金がある方は要保護にはなりません。","id":"exchange-065"},{"speaker":"鶴副委員長","kind":"提案","question":"通常、共産党に聞きたいんだけれども、５００万も資産を持っている人が、未満の人が、生活保護世帯に準ずるというふうにみなすのですか。提案理由の紹介された事例を聞きながら私たちはそう思ったわけですけれども、年間の所得でいったらどのぐらいのような人を低所得者というんか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが東京都の試算でも２１５万円もするわけですから、もう本当に１日１万８,０００円、これだと差額ベッド代だけで５４万円になるんですね。やっぱり貯金せざるを得ないという、そういうふうな状況になっているので、こういうふうに５００万というふうなことで考えました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"鶴副委員長","kind":"質問","question":"先ほどお出しになった、本会議でもお出しになったけれども、東京都内だけでしょうか、お葬式代２１４万というのは、これは根拠にならないですよ。あえてお伺いしますけれども、もし生活保護世帯の人が不幸にして亡くなったという場合のお葬式代、これはどのくらいかかっているんか尋ねました。","respondent":"黒田生活福祉課長","answer":"今年度につきましては、大人の方が１７万９,０００円というのが葬祭扶助です。そのほかにプラスされるものは１万円ちょっとありますけれども、通常１７万９,０００円というのが基準です。","id":"exchange-068"},{"speaker":"鶴副委員長","kind":"提案","question":"それから、例えば提案の説明によりますと、療養病床を２年すると月２０万前後かかる。この月２０万というのは、普通差額ベッドを除いて、普通の今のですね、医療制度の仕組みから見ますと、本人負担というのはどういう状況か尋ねました。","respondent":"黒田生活福祉課長","answer":"ご本人が負担するとすれば２割から３割、高齢者はもう少し安いということですので、それ以下ということになります。貯金は生活保護を受けているときに、申請の段階で１０万円を割った段階で、生活保護の対象にしています。","id":"exchange-069"},{"speaker":"鶴副委員長","kind":"提案","question":"区の斎場を利用したら６万じゃないですか。どうか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"予算の総額、そこのところで、７,７５２人から２００人を引いた７,５５２人で８２５円を掛けて求めた予算というのは１４年度５,６００万円です。これは本会議で提案をしているとおりですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"鶴副委員長","kind":"質問","question":"３原則というのがあって、三つ目は一般財源を繰り入れないというのが区の介護保険制度の趣旨ですから、これは相互扶助ですよね。ほかの人の理解を得ることができるのかどうかということはどういうふうにお考えか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それに対して１４４名という、こういう実数の数字ですから、品川区のもともとの考え方、基本的にはこの考え方でいっているということです。それで、基金の額もかなりの基金が積み立てられているという状況ですから、考え方としては品川区のこの考え方と全く同じです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"鶴副委員長","kind":"質問","question":"全く同じですか。共産党の考え方も区の考え方と全く同じだというふうにおっしゃっていたけれども、全く同じか尋ねました。","respondent":"早津高齢福祉課長","answer":"基準の考え方にしましても違っておりますし、私どもは、減額したものは保険料の中で。基金を取り崩すということではございません。","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"区が提案されたその予算に対して修正をするという考え方なので減額というふうな形になりますけれども、品川区が区はそういうふうな予算の提案権があって提案をするわけですから、考え方としては同じことですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"鶴副委員長","kind":"提案","question":"よく理解できないんですよ。同じだとおっしゃっているんですけれども、そうは思えないんですが、もっと提案者にわかるように説明していただけませんかとの意見を述べました。","respondent":"早津高齢福祉課長","answer":"区の予算では、保険料をこの措置を行うことで保険料の減が見込まれる。基金のほうを取り崩してという措置を講じているわけではございません。","id":"exchange-076"},{"speaker":"鶴副委員長","kind":"質問","question":"それで、５００万の資産を仮に持っている人を、それは低所得者と言うでしょうか。５００万の資産があって、あるいは保険料でその中から補い合って助けていかなければならない状況なのかとなると、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"先ほどからなぜ５００万にしたのかというところで話をさせていただいているとおり、そして、そういう状況になっていると思います。もう実際に、そういうふうな実態というのは先ほど説明したとおりですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"鶴副委員長","kind":"質問","question":"はいとおっしゃいましたので、どういうふうな検討をしているんですか。厚生労働省としては、今いろいろな負担が大変だ大変だということだけおっしゃったけれども、どうあるべきかということを今鋭意検討しているんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"船波委員","kind":"質問","question":"実際ふたをあけてみたところが、その条件に見合って軽減をしてほしいと申請した人は、見込みよりかは少なかったという現状なわけですよね。ですから、その余裕の部分に関してはどうしようというようなスタンスというか、方針はあるんか尋ねました。","respondent":"早津高齢福祉課長","answer":"数字がいろいろ出ておりますが、私どもとしては、まず１,０００人ぐらいの見込みというようなお話をさせていただきました。したがいまして、１,０００人と見て、それが差があるからそれをどうするとかという考え方には立っていないです。","id":"exchange-080"},{"speaker":"船波委員","kind":"質問","question":"それはもう決まってしまったもので、今後検討というか、変化する余地というか可能性はどうなんか尋ねました。","respondent":"早津高齢福祉課長","answer":"現在のところ特段考えてはございませんが、例えば収入の基準について、９６万円というのは、生活保護基準の１類、２類というものを参考にしていますので、そちらが改定されたとすれば、それは検討のきっかけにはなるだろうなというようなことは考えてあります。","id":"exchange-081"},{"speaker":"船波委員","kind":"確認","question":"その低所得者の方の負担を軽減するための措置としては、いろいろ説明を伺って理解しましたけれども。その辺をちょっと確認だけ。","respondent":"早津高齢福祉課長","answer":"保険料の改定時期には、議論の可能性としては、もちろんその場というのはあります。","id":"exchange-082"},{"speaker":"嶋委員","kind":"質問","question":"２番目の賃貸住宅に入居している場合の１２０万プラス８４万ということは、２０４万の収入ということでよろしいでしょうか。プラス５００万の資産があるということは、５００万の預貯金があるということは、皆さんはどういうふうに考えられたんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"実額ということで考えていますので、家賃を除くと生活の部分では１０万円というふうなことなので、やはり低所得者というふうに考えました。家賃があるなしで大きく支出額が変わるというところですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"嶋委員","kind":"意見","question":"月額１７万円で家賃７万円と言ったら、相当いい生活をできる状況がある。この中で十分やっていますので、ちょっと私は何回も申しわけないんですが、庶民感覚ではないですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"},{"speaker":"鶴副委員長","kind":"意見","question":"さっき聞き漏らしちゃったんですけれども、共産党というのは温かい心の持ち主なんだなと、月７万まで家賃を認める。生活保護法で言うところの家賃扶助の最高基準というのは幾らでしたっけ、生活保護基準に準じてとおっしゃっているからとの意見を述べました。","respondent":"黒田生活福祉課長","answer":"今年度につきましては、１人世帯ですと東京ですと５万３,７００円、２人以上ですと６万３,８００円です。","id":"exchange-086"},{"speaker":"鶴副委員長","kind":"質問","question":"このことについてはどういうふうにお考えでしょうか。鈴木委員。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"知事特認で６万９,８００円という、これは１人世帯ではありませんけれども、そういうふうなところを基準にして考えました。最高で７万円まで、入っているその家賃で計算されるわけですから、実額ということで７万円というのは最高ということで考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"鶴副委員長","kind":"意見","question":"なるほど、例えばどうしても生活が困窮して保険料が払えないという人については相談に乗る、そういう機会というのはあるわけでしょう。条例で細かく規定しなくてもとの意見を述べました。","respondent":"早津高齢福祉課長","answer":"お支払いの方法等についてのご相談等は応じます。現に第２段階に属している方であれば、区の条例の適用のための手続等のご紹介をしたりとかというようなことはやってあります。","id":"exchange-089"},{"speaker":"伊藤委員","kind":"確認","question":"確認だけですけれども、先ほど鈴木委員から対象者の数字が７,７５２名と出ました。この方々の資産調査はしていないですよね、その確認だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"資産調査というか、これはその予算を、この対象者をどうやって出してきたかということではなくてですか。一人一人の資産調査というのはもちろんできませんから、そういうふうなことはもちろん７,７５２人の資産調査はしていません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/534819?Template=document&Id=3010#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":53252,"voices":180}}]);
